nodes.statement:
Let $a$ be a nice clause of type $\bm{L}$ (meaning all its incident edges are nice in the sense of Definition~3.8). Given $\omega\in\bm{I}_0$, let $\hat{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\smash{\underline{\smash{\sigma}}}_{\delta a}$ which maximizes entropy subject to edge marginals $(\omega_{\bm{L},j})_j$. By Definition~9.1,
each $\smash{\underline{\smash{\sigma}}}_{\delta a}$ maps to a configuration
$\smash{\underline{\smash{\varsigma}}}_{\delta a}$, so $\hat{\nu}_{\bm{L}}$ also induces a probability measure on $(\mathscr{S}^2)^{\delta a}$. Under this measure we have
	\[
	\bm{\varpi}_{\bm{L},j}\Big(\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	=\hat{\nu}_{\bm{L}}\Big(\varsigma_j=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	\ge 1-O\bigg(\frac{k^2}{2^k}\bigg)
	\]
for all $1\le j\le k(\bm{L})$.

\begin{proof} For the proof we will mostly suppress $\bm{L}$ from the notation, and write $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$. We claim that for this proof it suffices to take $\sigma$ in the reduced alphabet $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. Indeed, each $\omega_{\bm{L},j}$ is a measure over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$, and naturally induces a measure $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, which we temporarily denote $\tilde{\omega}_{\bm{L},j}$. Let
$\tilde{\nu}\equiv\tilde{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\tilde{\smash{\underline{\smash{\sigma}}}}_{\delta a}\in(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^{\delta a})^2$ which maximizes entropy subject to edge marginals $(\tilde{\omega}_{\bm{L},j})_j$.
Since the clause factor (2.19) does not distinguish between \textup{\texttt{\footnotesize green}} and \textup{\texttt{\footnotesize blue}}, the optimal $\hat{\nu}\equiv\hat{\nu}_{\bm{L}}$ must take the form
	\begin{equation}
	\hat{\nu}_{\bm{L}}(\smash{\underline{\smash{\sigma}}}_{\delta a})
	= \tilde{\nu}(\tilde{\smash{\underline{\smash{\sigma}}}}_{\delta a})
	\prod_{j=1}^{k(\bm{L})}
	\frac{\omega_{\bm{L},j}(\sigma_j)}
	{\tilde{\omega}_{\bm{L},j}(\tilde{\sigma}_j)}\,,
	\end{equation}
where $\smash{\underline{\smash{\sigma}}}_{\delta a}\in(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^{\delta a})^2$ and $\tilde{\smash{\underline{\smash{\sigma}}}}_{\delta a}$ is its representative in $(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^{\delta a})^2$. Thus it suffices to study $\tilde{\nu}$. For the remainder of the proof we will abuse notation slightly and write $\hat{\nu},\smash{\underline{\smash{\sigma}}}_{\delta a}$ when we technically mean $\tilde{\nu},\tilde{\smash{\underline{\smash{\sigma}}}}_{\delta a}$. The remainder of the proof is divided into a few numbered steps. \smallskip 

\noindent\textbf{\textup{Step 1. Reduction to consideration of non-forcing clause colorings.}}
The single-copy marginals of $\omega$ are given by the canonical measure ${}_\star\hspace{-1pt}\pi$. Since $\bm{L}$ is assumed to be nice, it follows from Definition~3.8 that
	\begin{equation}
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize r}})
	\le\frac{O(1)}{2^k}\,,\quad
	\bigg|{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize c}})
	-\frac12\bigg|
	\le O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Let $\textup{\texttt{\footnotesize U}}$ denote the set of all \textbf{\textup{valid}} pair colorings $\smash{\underline{\smash{\sigma}}}_{\delta a} \in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^{2K}$, where we abbreviate $K\equiv k(\bm{L})$. Note that if $\smash{\underline{\smash{\sigma}}}_{\delta a}$ is a valid coloring belonging to the complement $\textup{\texttt{\footnotesize U}}^c$, then $\smash{\underline{\smash{\sigma}}}_{\delta a}$ must have at least one edge colored $\textup{\texttt{\footnotesize red}}$ in at least one of the two copies. It follows by the judicious condition together with (9.6) that
	\begin{equation}
	\hat{\nu}(\textup{\texttt{\footnotesize U}}^c)
	\le
	\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\textup{\texttt{\footnotesize r}})
	= 2 \sum_{j=1}^K
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize r}})
	\stackrel{(9.6)}{\le}
	O\bigg( \frac{k}{2^k}\bigg)\,.
	\end{equation}
Define the conditional measure $\mu(\smash{\underline{\smash{\sigma}}}_{\delta a})\equiv\hat{\nu}(\smash{\underline{\smash{\sigma}}}_{\delta a}\,|\,\textup{\texttt{\footnotesize U}})$. Let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$, so $\mu_j$ is a probability measure on $\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. Since $\hat{\nu}(\textup{\texttt{\footnotesize U}})$ is close to one by (9.7),
the single-copy marginals of $\mu_j$ must be close to ${}_\star\hspace{-1pt}\pi_{\bm{L}(j)}$; in particular, we must have
	\begin{equation}
	(\mu_j)^i(\textup{\texttt{\footnotesize c}})
	=\frac{ {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize c}})
		-\hat{\nu}(\textup{\texttt{\footnotesize U}}^c) \hat{\nu}( (\sigma_j)^i=\textup{\texttt{\footnotesize c}}\,|\,\textup{\texttt{\footnotesize U}}^c )}{1 - \hat{\nu}(\textup{\texttt{\footnotesize U}}^c)}
	\stackrel{(9.7)}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize c}}) + O\bigg(\frac1{2^k}\bigg)
	\stackrel{(9.6)}{=}
	\frac12 +O\bigg(
	\frac{1}{2^{k/10}}\bigg)\,.
	\end{equation}
Since $\hat{\nu}=\hat{\nu}_{\bm{L}}$ maximizes entropy subject to marginals $(\omega_{\bm{L},j})_j$, it must be that $\mu$ maximizes entropy subject to marginals $(\mu_j)_j$. Consequently, by the method of Lagrange multipliers, there must exist probability measures $q_j$ over $\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ (for $1\le j\le K$) such that
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}}_{\delta a})
	=
	\frac{\mathbf{1}\{\smash{\underline{\smash{\sigma}}}_{\delta a}\in\textup{\texttt{\footnotesize U}}\}
	Q(\smash{\underline{\smash{\sigma}}}_{\delta a})}{Q(\textup{\texttt{\footnotesize U}})},
	\quad
	Q(\smash{\underline{\smash{\sigma}}}_{\delta a})
	\equiv\prod_{j=1}^K q_j(\sigma_e)\,.
	\end{equation}
In the next step we will estimate the $q_j$ to show that under $\mu$, each edge is $\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$ with probability close to one. Since $\mu$ takes up most of the mass of $\hat{\nu}$ by (9.7), the result will follow.\smallskip

\noindent\textbf{\textup{Step 2. Construction of Lagrangian weights.}} We will iteratively construct a sequence $q_{j,t}$ that converges to the desired $q_j$
of (9.9) in the limit $t\to\infty$. We initialize $q_{j,0}=\mu_j$ for all $1\le j\le K$. Analogously to (9.9) let
	\[\mu_t(\smash{\underline{\smash{\sigma}}}_{\delta a})
	=
	\frac{\mathbf{1}\{\smash{\underline{\smash{\sigma}}}_{\delta a}\in\textup{\texttt{\footnotesize U}}\}
	Q_t(\smash{\underline{\smash{\sigma}}}_{\delta a})}{Q_t(\textup{\texttt{\footnotesize U}})},
	\quad
	Q_t(\smash{\underline{\smash{\sigma}}}_{\delta a})
	\equiv\prod_{j=1}^K q_{j,t}(\sigma_e)\,.
	\]
Let $\mu_{j,t}$ denote the marginal of $\mu_t$ on the $j$-th edge. Writing 
$\smash{\underline{\smash{\sigma}}}_{-j}\equiv (\sigma_\ell)_{\ell\in[K]\setminus j}$, we have
	\begin{equation}
	\mu_{j,t}(\sigma)
	= \frac1{\bar{z}_{j,t}}
	q_{j,t}(\sigma)
	\overbrace{
	\sum_{\smash{\underline{\smash{\sigma}}}_{-j}}
	\mathbf{1}\{\smash{\underline{\smash{\sigma}}}\in\textup{\texttt{\footnotesize U}}\}
	\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\sigma_\ell)
	}^{\textup{denote this }\xi_{j,t}(\sigma)}\,.
	\end{equation}
Note that $\xi_{j,t}(\sigma)$ has a simple expression for each $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$: for instance, for $\sigma=\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}}$ we have
	\[
	\xi_{j,t}(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	=1
	-\sum_{i=1,2}
	\prod_{\ell\in[K]\setminus j}
	(q_{\ell,t})^i(\textup{\texttt{\footnotesize y}})
	+\prod_{\ell\in[K]\setminus j}
	q_{\ell,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\,,
	\]
and we have similar expressions for $\sigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize y}}\}$. It is easily verified that
$1-k^{O(1)}/2^k\le \xi_{j,0}(\sigma)\le1$
for all $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, and substituting this estimate into (9.10) gives (crudely)
	\begin{equation}
	\bigg\| \frac{\mu_{j,0}}{\mu_j}-1
		\bigg\|_\infty
	\stackrel{(9.10)}{=}
	\bigg\| \frac{\xi_{j,0}}{ \bar{z}_{j,0}}-1
	\bigg\|_\infty \le \frac1{2^{2k/3}}\,.
	\end{equation}
Moreover, it follows by a straightforward calculation that 
	\begin{equation}
	\bigg|\frac{\partial \xi_{j,t}(\sigma)}
	{ \partial q_{\ell,t}(\sigma') }\bigg|
	\le \frac{k^{O(1)}}{2^k}
	\end{equation}
for all $j\ne \ell$ and all $\sigma,\sigma'\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. We now define
$q_{j,t+1}$ to be the probability measure such that
	\begin{equation}
	q_{j,t+1}(\sigma)
	\cong \frac{\mu_j(\sigma)}{\xi_{j,t}(\sigma)}
	\stackrel{(9.10)}
		{\cong}
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		q_{j,t}(\sigma)\,.
	\end{equation}
Let $z_{j,t+1}$ denote the normalizing constant such that
	\begin{equation}
	q_{j,t+1}(\sigma)
	=\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}
		\frac{q_{j,t}(\sigma)}{z_{j,t+1}}\,.
	\end{equation}
Now suppose inductively that for all $t\ge0$ we have
	\begin{equation}
	\bigg\|
	\frac{\mu_{j,t} }{ \mu_j}
	-1\bigg\|_\infty
	\le \frac1{(2^{2k/3})^{t+1}}\,,\end{equation}
where the base case $t=0$ is given by (9.11). Note that substituting (9.15) into (9.14) implies that $q_{j,t}$ is close to $z_{j,t+1}q_{j,t+1}$; since all the $q$'s are probability measures, it further implies that $z_{j,t+1}$ is close to one. Thus, for $t\ge0$,
the inductive hypothesis (9.15) leads to
	\begin{equation}
	\Big\|\xi_{j,t+1}-\xi_{j,t}\Big\|_\infty
	\stackrel{(9.12)}{\le}
	\frac{k^{O(1)}}{2^k}
	\Big\|q_{j,t+1}-q_{j,t}\Big\|_\infty
	\stackrel{(9.14)}{=}
	\frac{k^{O(1)}}{2^k}
	\Bigg\|q_{j,t}
	\bigg(
	\frac{\mu_j}{\mu_{j,t}}
		\frac{1}{z_{j,t+1}}
	-1\bigg)\Bigg\|_\infty
	\stackrel{(9.15)}{\le}
	\frac{k^{O(1)}}{2^k}
	\frac1{(2^{2k/3})^{t+1}}\,.
	\end{equation}
Recall that $\mu_{j,t+1} = q_{j,t+1} \xi_{j,t+1} / \bar{z}_{j,t+1}$ by (9.10), while
(9.13) implies that
there exists a normalizing constant $\acute{z}_{j,t+1}$ such that $\mu_j = q_{j,t+1} \xi_{j,t}/\acute{z}_{j,t+1}$. It follows that
	\[
	\bigg\| \frac{\mu_{j,t+1}}{\mu_j}-1\bigg\|_\infty
	=
	\bigg\| 
	\frac{\xi_{j,t+1} / \bar{z}_{j,t+1}}
		{\xi_{j,t} / \acute{z}_{j,t+1}}-1
	\bigg\|_\infty
	\stackrel{(9.16)}
		{\le}
	\frac1{(2^{2k/3})^{t+2}}\,,
	\]
which verifies the inductive hypothesis (9.15).\smallskip

\noindent
\textbf{\textup{Step 3. Conclusion.}}
Let $q_j=\lim_{t\to\infty} q_{j,t}$, where it is clear from (9.15) that the limit is well-defined. Moreover, summing (9.15) over $t\ge0$ implies
	\begin{align*}
	\bigg\|\frac{q_j}{\mu_j}-1\bigg\|_\infty
	&=\bigg\|\frac{q_j}{q_{j,0}}-1\bigg\|_\infty
	\le
	\sum_{t\ge0}
	\bigg\|\frac{q_{j,t+1}}{q_{j,t}}-1\bigg\|_\infty\\
	&\stackrel{(9.14)}
		{\le} O\Bigg(
	\sum_{t\ge0}
	\bigg\|\frac{\mu_{j,t}}{\mu_j}
		-1\bigg\|_\infty
		\Bigg)
	\stackrel{(9.15)}{\le}
	O\Bigg(
	\sum_{t\ge0}
	\frac1{(2^{2k/3})^{t+1}}\Bigg)
	\le \frac1{2^{k/2}}\,.
	\end{align*}
We can then straightforwardly derive from
(9.8), (9.9), and
the last bound that 	
	\[\mu\Big(\varsigma_j=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	\ge 1- O\bigg(\frac{k^2}{2^k}\bigg)\]
for all $1\le j\le K$. The result follows since $\mu$ is the measure $\hat{\nu}$ conditioned on event $\textup{\texttt{\footnotesize U}}$,
and we know that
 $\hat{\nu}(\textup{\texttt{\footnotesize U}}^c)$ is negligible by (9.7).
\end{proof}

Suppose $\omega\in\bm{I}_0$, and let $\pi\equiv(\pi_{\bm{t}})_{\bm{t}}$ be the marginal of $\omega$ --- each $\pi_{\bm{t}}$ is obtained by averaging over $\omega_{\bm{L},j}$ such that $\bm{L}\ni\bm{t}$ (see Definition~3.25). Let
	\[
	\nu^\textup{op}[\pi]
	\equiv
	\textup{arg\,max}_\nu
	\bigg\{
	\bm{\Phi}_{\mathscr{D},2}(\nu):
	\textup{$\nu$ is consistent with $\pi$}
	\bigg\}\,.
	\]
This is a relaxation of
(9.3), since if $\nu$ is consistent with $\omega$ then it is also consistent with $\pi$. The relaxation is also a strictly convex problem, so the maximizer $\nu^\textup{op}[\pi]$ is uniquely defined. Let $\acute{\omega}$ denote the marginals of $\nu^\textup{op}[\pi]$. Then, for every $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ and every non-compound edge $\bm{t}$ with $\pi_{\bm{t}}(\sigma)\ge 2^{-k/15}$, we have
	\[\min\bigg\{
	\frac{\acute{\omega}_{\bm{L},j}(\sigma)}{\pi_{\bm{t}}(\sigma)}
	:\bm{L}(j)=\bm{t}\bigg\}
	\ge \frac18\,,
	\]
where $j\equiv j(\bm{t})$. (If $\bm{t}$ is a compound edge type then there is only one clause type $\bm{L}$ with $\bm{L}(j)=\bm{t}$, so in this case $\omega_{\bm{L},j}=\pi_{\bm{t}}$ and there is nothing to prove.)

\begin{proof} The proof follows a familiar outline: we first reduce to a simplified constrained entropy maximization problem, then estimate the Lagrangian weights solving that problem to derive the conclusion.\smallskip

\noindent
\textbf{\textup{Step 1. Simplified entropy maximization problem.}}
From the expression (9.2)
for $\bm{\Phi}_{\mathscr{D},2}$, we see that to optimize
$\bm{\Phi}_{\mathscr{D},2}(\nu)$ given fixed $\pi$, we can optimize separately over the variable and clause empirical measures, $\dot{\nu}$ and $\hat{\nu}$. We can therefore consider $\hat{\nu}$ alone, since it determines $\acute{\omega}$. The optimal $\hat{\nu}$ is given by
	\begin{equation}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]
	\equiv
	\sum_{\bm{L}}\hat{\mathscr{D}}(\bm{L}) \mathcal{H}(\hat{\nu}_{\bm{L}})
	: \textup{$\hat{\nu}$ is judicious and 
	consistent with $\pi$}
	\Bigg\}
	\end{equation}
--- this is because $\mathbb{E}_{\hat{\mathscr{D}}}[\mathcal{H}(\hat{\nu}_{\bm{L}})]$ is the only term of (9.2) that varies with $\hat{\nu}$ when $\pi$ is fixed. Equivalently, recalling the combinatorial calculation (9.1), 
$\hat{\nu}$ must satisfy
	\begin{equation}
	\hat{\nu}=\textup{arg\,max}_{\hat{\nu}}
	\Bigg\{
	\prod_{\bm{L}}
	\binom{m_{\bm{L}}}{m_{\bm{L}}\hat{\nu}_{\bm{L}}}
	\Bigg\}\,,
	\end{equation}
that is to say, $\hat{\nu}$ is the empirical measure of clause colorings $\smash{\underline{\smash{\sigma}}}_{\delta a}$ that maximizes entropy subject to marginals $\pi$.

Now, as in the statement of the lemma, let us fix a non-compound edge type $\bm{t}$ such that $\pi_{\bm{t}}(\sigma)\ge 2^{-k/20}$. Denote $j=j(\bm{t})$, and recall that we write $\bm{L}\ni\bm{t}$ if and only if $\bm{L}(j)=\bm{t}$. 
Given $\mathscr{G}=(V,F,E)$, define the subset of clauses
	\[
	F(\bm{t})
	= \bigg\{ a\in F : \bm{L}_a \ni\bm{t}\bigg\}
	\subseteq F\,.
	\]
Note for all $\bm{L}\ni\bm{t}$
the clause width $k(\bm{L})$ equals the same value $K\in\{k-1,k\}$, since $\bm{L}$ must be compatible with $\bm{t}$. Recall from Definition~9.1 that a clause coloring
$\smash{\underline{\smash{\sigma}}}\in(\mathscr{X}^K)^2$
defines an element
$\smash{\underline{\smash{\varsigma}}}\in(\mathscr{S}^K)^2$. Let
	\[
	\textup{\texttt{\footnotesize N}}
	\equiv
	\textup{\texttt{\footnotesize N}}_j
	\equiv\bigg\{
	\smash{\underline{\smash{\sigma}}} \in (\mathscr{X}^K)^2
	: \sigma_j \in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2
	\textup{ and }
	\varsigma_j = \textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}
	\bigg\}\,.
	\]
Then, for any (pair) coloring $\smash{\underline{\smash{\sigma}}}$ on $\mathscr{G}$, let
	\[
	F(\bm{t},\smash{\underline{\smash{\sigma}}})
	\equiv
	\bigg\{ a\in F(\bm{t}) : 
		\smash{\underline{\smash{\sigma}}}_{\delta a}\in\textup{\texttt{\footnotesize N}}\bigg\}
	\subseteq F(\bm{t})\,.
	\]
\textbf{\textup{Within $F(\bm{t},\smash{\underline{\smash{\sigma}}})$ only,}} because each clause has $\varsigma_j=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$, we are free to reassign the value of $\sigma_j$ to any other color in $\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$, provided we continue to respect $\pi$ and the judicious constraints. Let $\mathbf{P}\equiv\mathbf{P}_{\bm{t}}$ be the probability measure
	\[
	\mathbf{P}\bigg(\bm{L},\smash{\underline{\smash{\sigma}}}_{\delta a}=\smash{\underline{\smash{\sigma}}}\bigg)
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\cdot \hat{\nu}_{\bm{L}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta a}=\smash{\underline{\smash{\sigma}}}
		\bigg)\,,
	\]
so $\mathbf{P}$ represents the empirical measure of clause types and colorings within $F(\bm{t})$. 
Note that marginal of $\mathbf{P}$ on $\bm{L}$ is $\mathbf{P}(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})$, while the marginal on $\sigma_j$ (for $j=j(\bm{t})$) is $\bm{L}(\sigma_j=\sigma)=\pi_{\bm{t}}(\sigma)$. Let $\zeta$ be the empirical measure for the $j$-th edges of the clauses in $F(\bm{t},\smash{\underline{\smash{\sigma}}})$, i.e.,
	\[
	\zeta(\sigma,\bm{L})
	= \mathbf{P}\bigg(
		\bm{L},\sigma_j=\sigma
		\,\bigg|\,\textup{\texttt{\footnotesize N}}
		\bigg)\,,
	\]
where $\textup{\texttt{\footnotesize N}}$ is shorthand for the event that $\smash{\underline{\smash{\sigma}}}\in\textup{\texttt{\footnotesize N}}$. If $\hat{\nu}$ is the maximizer as in (9.17) or (9.18), then $\zeta$ must satisfy
	\begin{equation}
	\zeta=\textup{arg\,max}_\zeta\left\{
	\begin{array}{c}\mathcal{H}(\zeta):
	\zeta(\bm{L}) = \mathbf{P}(\bm{L}\,|\,\textup{\texttt{\footnotesize N}}) \ \forall \bm{L},\\
	\zeta(\sigma) = \mathbf{P}(\sigma_j=\sigma\,|\,\textup{\texttt{\footnotesize N}})
		\ \forall \sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2,\\
	\zeta(\tau\,|\,\bm{L})
		=\mathbf{P}((\sigma_j)^i=\tau\,|\,\textup{\texttt{\footnotesize N}},\bm{L})
		\ \forall \tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}
	\end{array}\right\}\,.
	\end{equation}
By the method of Lagrange multipliers, there exist (real-valued) weights
$\gamma$, $\beta(\bm{L})$ , $(\beta_{\bm{L}})^1$, $(\beta_{\bm{L}})^2$ 
such that
	\begin{equation}
	\zeta(\bm{L},\sigma)\cong\exp\Bigg\{
		\gamma\mathbf{1}\{\sigma^1\ne\sigma^2\}
			+\beta(\bm{L})
		+2\sum_{i=1,2}
			(\beta_{\bm{L}})^i
				\mathbf{1}\{\sigma^i=\textup{\texttt{\footnotesize b}}\}
		\Bigg\}\,,
	\end{equation}
where $\gamma$ can be chosen independently of $\bm{L}$ since its purpose is to enforce the constraint on $\zeta(\sigma)$. (The weights $(\beta_{\bm{L}})^i$ are multiplied by a factor of two for convenience in subsequent calculations.)\smallskip

\noindent\textbf{\textup{Step 2. Estimation of marginals for (9.20).}} Note that since $\bm{t}$ was assumed to be a non-compound edge type, any clause type $\bm{L}\ni\bm{t}$ must be nice. It then follows from the judicious condition, Definition~3.8, and Lemma~9.5 that for all $\bm{L}\ni\bm{t}$ we have
	\begin{equation}
	1\ge \hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize N}})
	\ge
	\hat{\nu}_{\bm{L}}\Big(\varsigma_j=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	-\sum_{i=1,2}
	\overbrace{\hat{\nu}_{\bm{L}}\Big( (\sigma_j)^i=\textup{\texttt{\footnotesize g}}\Big)}^{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\textup{\texttt{\footnotesize g}})}
	\ge
	1-O\bigg(\frac{k^2}{2^k}\bigg)\,.
	\end{equation}
As a result, the quantities appearing in (9.19) can be written more explicitly and estimated as follows:
	\[\zeta(\bm{L})=\mathbf{P}(\bm{L}\,|\,\textup{\texttt{\footnotesize N}})
	=\frac{ \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
		\hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize N}})}
		{\sum_{\bm{L}'} \pi_{\mathscr{D}}(\bm{L}'\,|\,\bm{t})
		\hat{\nu}_{\bm{L}'}(\textup{\texttt{\footnotesize N}})}
	\stackrel{(9.21)}{=}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\Bigg\{ 1- O\bigg( \frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
i.e., the clause type proportions within $F(\bm{t},\smash{\underline{\smash{\sigma}}})$ are close to those within $F(\bm{t})$. Next, for each $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$, we have
	\[\zeta(\sigma)=
	\mathbf{P}\Big(\sigma_j=\sigma\,\Big|\,\textup{\texttt{\footnotesize N}}\Big)



	= \frac{\pi_{\bm{t}}(\sigma)
		-\mathbf{P}(\sigma_j=\sigma,\textup{\texttt{\footnotesize N}}^c)}
		{\mathbf{P}(\textup{\texttt{\footnotesize N}})}
	\stackrel{(9.21)}{=}
	\pi_{\bm{t}}(\sigma)
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,
	\]
where we note that the right-hand side
must be positive by the assumption that $\pi_{\bm{t}}\ge 2^{-k/20}$. 
Finally, for each $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ and each $\bm{L}$, we have
	\begin{equation}
	\zeta(\sigma\,|\,\bm{L})=
	\mathbf{P}\Big(\sigma_j=\sigma
		\,\Big|\,\textup{\texttt{\footnotesize N}},\bm{L}\Big)



	= \frac{\omega_{\bm{L},j}(\sigma) 
		-\mathbf{P}(\sigma_j=\sigma,\textup{\texttt{\footnotesize N}}^c\,|\,\bm{L})
		}{\mathbf{P}(\textup{\texttt{\footnotesize N}}\,|\,\bm{L})}
	\stackrel{(9.21)}{=} 
	\omega_{\bm{L},j}(\sigma) 
	-O\bigg( \frac{k^2}{2^k}\bigg)\,,\end{equation}
where we have not yet shown the right-hand side to be positive. Taking the marginal on the $i$-th copy gives
	\[
	\zeta( \sigma^i=\tau\,|\,\bm{L})=
	\mathbf{P}\Big((\sigma_j)^i=\tau
		\,\Big|\,\textup{\texttt{\footnotesize N}},\bm{L}\Big)
	= \frac{{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
		-\mathbf{P}((\sigma_j)^i=\tau,\textup{\texttt{\footnotesize N}}^c\,|\,\bm{L})
		}{\mathbf{P}(\textup{\texttt{\footnotesize N}}\,|\,\bm{L})}
	\stackrel{(9.21)}{=} 
	{}_\star\hspace{-1pt}\pi_{\bm{t}}(\tau)
	-O\bigg( \frac{k^2}{2^k}\bigg)
	\]
for each $\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}$.
This concludes our estimates for the quantities appearing in (9.19). Next, we note that by the judicious condition, for all $\bm{L},j$ we have
	\[\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}})-\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})
	=\bigg\{
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}})+\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\bigg\}
	-\bigg\{
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})+\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\bigg\}
	={}_\star\hspace{-1pt}\pi_{\bm{t}}(\textup{\texttt{\footnotesize y}})-{}_\star\hspace{-1pt}\pi(\textup{\texttt{\footnotesize y}})
	=0\,.
	\]
By the judicious condition together with the assumption that $\bm{t}=\bm{L}(j)$ is nice, we also have
	\[
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})-\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
	=\bigg\{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	+\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})\bigg\}
	-\bigg\{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
		+\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})
		\bigg\}
	={}_\star\hspace{-1pt}\pi(\textup{\texttt{\footnotesize y}})-{}_\star\hspace{-1pt}\pi(\textup{\texttt{\footnotesize b}})
	=O\bigg( \frac1{2^{k/10}}\bigg)\,.
	\]
Combining with (9.22) gives,
for all $\bm{L},j$ with $\bm{L}(j)=\bm{t}$, the bound
	\begin{equation}
	\bigg|\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})-\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L})\bigg|
	+\bigg|\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L})-\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})\bigg|
	\le O\bigg( \frac1{2^{k/10}}\bigg)\,.\end{equation}
With these estimates in hand, we now turn to estimating the weights in (9.20).\smallskip

\noindent\textbf{\textup{Step 3. Estimation of Lagrangian weights.}}
If $\bm{L}$ satisfies $\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})\ge 2^{-k/15}$, then it follows by combining with (9.23) that
	\[
	\bigg|\frac{\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L})}{\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}-1\bigg|
	\le
	\frac{|\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L})-\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})|
	}{
	\min\{
	\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L}),\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})\}}
	\stackrel{(9.23)}{\le}
	O\bigg(\frac{2^{-k/10}}{2^{-k/15}}\bigg)
	=O\bigg( \frac1{2^{k/30}}\bigg)\,.
	\]
On the other hand, from the Lagrangian solution (9.20), we have
	\[
	\frac{\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\,|\,\bm{L})}{\zeta(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}
	= \frac{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^2 \}}
	{\exp\{\beta(\bm{L})+\gamma+2(\beta_{\bm{L}})^1 \}}
	= \exp\bigg\{ 
	2\Big[
	(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big]\bigg\}\,.
	\]
Comparing the last two displays, we see that
	\begin{equation}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2-(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}
	\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
An entirely similar argument gives
	\begin{equation}
	\max\bigg\{
	\Big|(\beta_{\bm{L}})^2+(\beta_{\bm{L}})^1\Big| 
	:\bm{L}\ni\bm{t} \textup{ and }\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})
		\ge \frac1{2^{k/15}}\bigg\}
	\le
	O\bigg( \frac1{2^{k/30}}\bigg)\,.\end{equation}
Now suppose $\bm{t}$ is such that $\pi_{\bm{t}}(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\})\ge \chi$
for some $2^{-k/15}\le\chi\le 1/2$. It implies that for \textbf{\textup{some}} clause type $\bm{L}\ni\bm{t}$, we have
$\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L}) \ge \chi$. For this particular $\bm{L}$, 
writing $\mathrm{ch}$ for the hyperbolic cosine function, we have
	\begin{align}
	\chi &\le \frac{\chi}{1-\chi}
	\le
	\frac{\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})}
	{\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})}
	= e^\gamma
	\frac{\exp\{2 (\beta_{\bm{L}})^2\}+\exp\{ 2(\beta_{\bm{L}})^1\}}
	{1 + \exp\{2 (\beta_{\bm{L}})^1+2(\beta_{\bm{L}})^2\}}
	= e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{(9.24)}{\le}
	\frac{ e^\gamma
	[1 +O(2^{-k/30})]
	}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\le e^\gamma
	\bigg( 1 + O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.
	\end{align}
Next, for \textbf{\textup{every}} clause type $\bm{L}$ such that $\bm{L}\ni\bm{t}$,
since we assumed $\chi\le1/2$,
at least one of the two quantities
$\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})$ and
$\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})$ must be $\ge\chi$.
If $\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})\ge\chi$, then
	\begin{align*}
	\frac{\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})}
		{\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})}
	&=e^\gamma
	\frac{\mathrm{ch}((\beta_{\bm{L}})^1-(\beta_{\bm{L}})^2) }
	{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }
	\ge 
	\frac{e^\gamma}{\mathrm{ch}((\beta_{\bm{L}})^1+(\beta_{\bm{L}})^2) }\\
	&\stackrel{(9.25)}{\ge}
	\frac{e^\gamma}{1+O(2^{-k/30})}
	\stackrel{(9.26)}{\ge}
	\chi\bigg( 1 - O\bigg(\frac1{2^{k/30}}\bigg)\bigg)
	\,.
	\end{align*}
Combining the two cases
$\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})\ge\chi$ and
$\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}\,|\,\bm{L})\ge\chi$ gives
	\[
	\zeta(\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}\,|\,\bm{L})
	\ge
	\min\bigg\{
	\chi, \frac{\chi[1 -O(2^{-k/30})]}{1
		+\chi[1 -O(2^{-k/30})]}
	\bigg\}
	\ge \frac{2\chi}{3}
	\bigg( 1- O\bigg(\frac1{2^{k/30}}\bigg)\bigg)\,.
	\]
Recalling (9.22) again, this proves that 
if $\pi_{\bm{t}}(\sigma)\ge 2^{-k/15}$ for $\sigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}\}$,
then
	\[
	\omega_{\bm{L},j}(\sigma)
	\ge \frac{\chi}{4}
	\ge \frac{\pi_{\bm{t}}(\sigma)}{8}\,,
	\]
where the last bound follows by taking
$\chi=\min\{\pi_{\bm{t}}(\sigma),1/2\}$.
The analogous result for
$\sigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}\}$ by a symmetric argument, and this concludes the proof.
\end{proof}

Let $a$ be a clause of type $\bm{L}$ which is both nice
(meaning $\bm{t}$ is nice for all $\bm{t}\in\bm{L}$) and diverse (Definition~9.3). Given $\omega\in\bm{I}_0$, let $\hat{\nu}_{\bm{L}}$ be the probability measure on valid (pair) colorings $\smash{\underline{\smash{\sigma}}}_{\delta a}$ which maximizes entropy subject to edge marginals $(\omega_{\bm{L},j})_j$. Recall from Definition~9.1 that
each $\smash{\underline{\smash{\sigma}}}_{\delta a}$ maps to a configuration
$\smash{\underline{\smash{\varsigma}}}_{\delta a}\in(\mathscr{S}^2)^{\delta a}$. Let
	{\setlength{\jot}{0pt}\begin{align*}
	\textup{\texttt{\footnotesize A}}
	&\equiv \{\smash{\underline{\smash{\sigma}}}_{\delta a}
	: \sigma_e\ne\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}} \textup{ for all }e\in\delta a\}\,,\\
	\textup{\texttt{\footnotesize W}}^i
	&\equiv \{\smash{\underline{\smash{\sigma}}}_{\delta a}
	: (\varsigma_e)^i
	=\textup{\texttt{\footnotesize w}} \textup{ for all }e\in\delta a\}\,.
	\end{align*}}
There exists an absolute constant $\epsilon_1>0$ such that
	\begin{equation}
	1-\hat{\nu}_{\bm{L}}
	\Big(\textup{\texttt{\footnotesize W}}^1 \cup \textup{\texttt{\footnotesize W}}^2
	\,\Big|\, \textup{\texttt{\footnotesize A}}\Big)
	\le \frac1{2^{k(1+\epsilon_1)}}\,.
	\end{equation}
If in addition $\bm{L}$ is light (Definition~9.4), then it follows immediately that
	\begin{equation}
	1-\hat{\nu}_{\bm{L}}\Big(\textup{\texttt{\footnotesize W}}^1 \cup \textup{\texttt{\footnotesize W}}^2\Big)
	\le \frac1{2^{k(1+\epsilon_1)}}
	+ \frac{k}{2^{k(1+\epsilon_\circ)}}
	\le O\bigg(\frac{k}{2^{k(1+\epsilon_\circ)}}\bigg)\,,
	\end{equation}
where we can assume that $\epsilon_\circ\le\epsilon_1$.

\begin{proof} 
It is an immediate consequence of Lemma~9.6
that if $\bm{L}$ is both nice and diverse, then
	\begin{equation}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
		\omega_{\bm{L},j}\Big(
		\{\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}\}\Big)
	\ge \frac1{33}
	\bigg\}
	\ge \sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}})
		\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
In this proof, by the same reasoning as in the proof of Lemma~9.5 (see (9.5)), it suffices to take $\sigma$ in the reduced alphabet $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. We also abbreviate $\textup{\texttt{\footnotesize u}}\equiv\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. Throughout the following, $\epsilon_1$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. We denote the clause width by $K\equiv k(\bm{L})\in\{k-1,k\}$.
\smallskip

\noindent\textbf{\textup{Step 1. Reduction to entropy maximization for a conditional measure.}} As in the statement of the lemma, let $\hat{\nu}_{\bm{L}}$ be the optimizer given marginals $\omega$. Note that since $\omega$ is judicious and $\bm{L}$ is nice,
	\[
	\hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize A}}^c)
	\le\sum_{j=1}^K
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
	\le\sum_{i=1,2}
	\sum_{j=1}^K
	(\omega_{\bm{L},j})^i(\textup{\texttt{\footnotesize r}})
	= 2\sum_{j=1}^K {}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\textup{\texttt{\footnotesize r}})
	\le O\bigg( \frac{k}{2^k}\bigg)\,.
	\]
Let $\mu(\smash{\underline{\smash{\sigma}}})\equiv \hat{\nu}_{\bm{L}}(\smash{\underline{\smash{\sigma}}}\,|\, \textup{\texttt{\footnotesize A}})$
for $\smash{\underline{\smash{\sigma}}}\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^{2K}$. For each edge $1\le j\le K$, let $\mu_j$ be the marginal of $\mu$ on the $j$-th edge in $\delta a$. Thus $\mu_j$ is a probability measure over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$, and the preceding estimate implies
	\begin{equation}
	\mu_j(\sigma)
	=\frac{\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)
		-\hat{\nu}_{\bm{L}}(\sigma_j=\sigma;\textup{\texttt{\footnotesize A}}^c)}
		{1-\hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize A}}^c)}
	= \begin{cases}
	\omega_{\bm{L},j}(\sigma) +O(k/2^k)
		&\textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=0$,} \\
	\omega_{\bm{L},j}(\sigma) +O(1/2^k)
		&\textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=1$,}
	\end{cases}
	\end{equation}
where the last bound uses that $\hat{\nu}_{\bm{L}}(\sigma_j=\sigma)\le O(1/2^k)$ if $\textup{\texttt{\footnotesize r}}[\sigma]=1$. The measure $\mu$ maximizes entropy subject to the edge marginals $\mu_j$. Similarly as in the preceding proofs of this section, we shall construct a sequence of Lagrangian weights $b_{j,t}$ such that the measure
	\begin{equation}
	 \mu_t(\smash{\underline{\smash{\sigma}}})
	= \frac{ \mathbf{1}\{\smash{\underline{\smash{\sigma}}}\in\textup{\texttt{\footnotesize A}}\}}{Z_t}
	\prod_{j=1}^K b_{j,t}(\sigma_j)\end{equation}
converges to the desired $\mu$ as $t\to\infty$, where $Z_t$ is the normalizing constant. Let $\mu_{j,t}$ denote the marginals of the measure $\mu_t$.\smallskip

\noindent\textbf{\textup{Step 2. Initalization of Lagrangian weights.}} We initialize the construction with
	\begin{equation}
	b_{j,0}(\sigma)
	\equiv
	\frac{\mu_j(\sigma)}{1/ (2^{K-1})^{\textup{\texttt{\footnotesize r}}[\sigma]}}\,,\quad
	\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}\,.
	\end{equation}
We first estimate the marginals $\mu_{j,0}$ of the resulting measure $\mu_0$. Recall that we denote $\textup{\texttt{\footnotesize u}}\equiv\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. Note that (9.30), together with the judicious condition and the assumption that $\bm{L}$ is nice, gives
	\begin{equation}
	\mu_j(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})=1-O\bigg(\frac{k}{2^k}\bigg)\,,\quad
	\sum_{\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}}
	\Bigg\{
	\bigg|\mu_j(\tau\textup{\texttt{\footnotesize u}})-\frac12\bigg|
	+\bigg|\mu_j(\textup{\texttt{\footnotesize u}}\tau)-\frac12\bigg|\Bigg\}
	 \le \frac1{2^{k\epsilon_1}}\,.
	\end{equation}
Moreover, it follows from the diverse clause condition (9.32) together with (9.30) that
	\begin{equation}
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\min\Big\{	 \mu_j(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}),\mu_j(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})\Big\}
	\ge \frac1{65}
	\bigg\}
	\ge \frac{k}{10}\,.
	\end{equation}
Without loss of generality we now focus on the marginal on the edge indexed $j=1$: at time $t=0$, 
	\[
	Z_0\mu_{1,0}(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	= \mu_1(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	\Bigg\{
	\prod_{\ell=2}^K\mu_\ell(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
	-\prod_{\ell=2}^K\mu_\ell(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize y}})
	-\prod_{\ell=2}^K\mu_\ell(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	+\prod_{\ell=2}^K\mu_\ell(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\Bigg\}
	\stackrel{(9.33)}{=}
	\mu_1(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})\Bigg\{ 1 +O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
Similar calculations, again using (9.33), give the analogous estimate for $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$.
Next, for $\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}$, it follows from (9.33)
together with the diversity bound (9.34) gives
	\begin{align*}
	Z_0\mu_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}})
	&= \Big( \mu_1(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}) 2^{K-1}\Big)
	\Bigg\{\prod_{\ell=2}^K
	\mu_\ell(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	-\prod_{\ell=2}^K\mu_\ell(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Bigg\}\\
	&=\Big( \mu_1(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}) 2^{K-1}\Big)
	\frac{1+O(k/2^{k\epsilon_1})}{2^{K-1}}\Bigg\{1
	-\bigg(1-\frac{2}{65}\bigg)^{k/10}
	\Bigg\}
	= \mu_1(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}) 
	\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\end{align*}
(recalling our convention that $\epsilon_1$ can change from one expression to the next, but remains bounded below by a positive absolute constant). A similar calculation (again using
(9.33) and (9.34)) gives
an analogous estimate for $\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}$. Altogether we conclude
	\begin{equation}
	\mu_{1,0}(\sigma)
	=\frac{\mu_1(\sigma)}{Z_0}
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	= \mu_1(\sigma)
		\Bigg\{ 1 +O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,.
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$.\smallskip

\noindent\textbf{\textup{Step 3. Iterative analysis of Lagrangian weights.}} Suppose at time $t$ that we have weights $b_{j,t}$, which define a measure $\mu_t$ as in (9.31) with edge marginals $\mu_{j,t}$. We define the updated weights at time $t+1$ by
	\begin{equation}
	\frac{b_{j,t+1}(\sigma)}{b_{j,t}(\sigma)}
	= \frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}\,.
	\end{equation}
We will prove by induction that for all $t\ge0$, all $1\le j\le k(\bm{L})$, and all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$,
	\begin{equation}
	\Bigg|
	\frac{b_{j,t+1}(\sigma)}
		{b_{j,t}(\sigma)}-1 \Bigg|
	=\Bigg|
	\frac{\mu_j(\sigma)}{\mu_{j,t}(\sigma)}-1
	\Bigg|
	\le \frac{ y_{\textup{\texttt{\footnotesize r}}[\sigma]}}{2^{k(t+1)\epsilon_1/3}}\,,\quad
	\begin{pmatrix}y_0 \\ y_1\end{pmatrix}
	= \frac1{2^{3k\epsilon_1/2}}
	\begin{pmatrix}1 \\ 2^{k\epsilon_1/2} \end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ is implied by (9.35) (adjusting $\epsilon_1$ appropriately). Suppose then that (9.37) holds up to time $t-1\ge0$, and note it implies that for all $j,\sigma$ we have
	\begin{equation}
	\Bigg|\ln \frac{b_{j,t}(\sigma)}
		{\mu_j(\sigma) (2^{K-1})^{\textup{\texttt{\footnotesize r}}[\sigma]}}
		\Bigg|
	=\Bigg|\ln \frac{b_{j,t}(\sigma)}{b_{j,0}(\sigma)}
		\Bigg|
	\le \sum_{s=0}^{t-1}
	\Bigg|\ln \frac{b_{j,s+1}(\sigma)}{b_{j,s}(\sigma)}
		\Bigg|
	\stackrel{(9.37)}{\le}
		O\bigg( \frac1{2^{k\epsilon_1}}\bigg)\,.
	\end{equation}
To analyze the update (9.36), let us focus on the first two edges in the clause, and note that
	\begin{equation}
	\frac{\partial \mu_{1,t}(\sigma)}
		{\partial \ln b_{2,t}(\sigma')}
	=\mathrm{Cov}_{\mu_t}\bigg(
	\mathbf{1}\{\sigma_1=\sigma\},
	\mathbf{1}\{\sigma_2=\sigma'\}
	\bigg)
	\end{equation}
for all $\sigma,\sigma'\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$ (by direct calculation). We therefore define
	\[
	C_t(\sigma,\sigma')
	\equiv
	\frac{Z_t \mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_{j=1}(\sigma)
		\mu_{j'=2}(\sigma')}\,,
	\]
and proceed to estimate this quantity. In the simplest case $\sigma=\sigma'=\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}}$, we have
	\[
	C_t(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	=\frac{b_{1,t}(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	b_{2,t}(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})}
	{\mu_1(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})
	\mu_2(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})}
	\prod_{j=3}^K b_{j,t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
	\stackrel{(9.38)}{=}
	\Bigg\{
	\prod_{j=3}^K \mu_j(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{(9.33)}{=}
	1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\,.\]
A similar estimate holds for all cases where
$\textup{\texttt{\footnotesize r}}[\sigma]+\textup{\texttt{\footnotesize r}}[\sigma']=0$. Next,
	\[
	C_t(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})
	=\frac{ b_{1,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}})b_{2,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})}
		{\mu_1(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}})\mu_2(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})}
	\prod_{j=3}^K b_{j,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	\stackrel{(9.38)}{=}
	\Bigg\{ 2^{K-1} \prod_{j=3}^K \mu_j(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	\Bigg\}
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\stackrel{(9.33)}{=}
	2 \Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}\,,
	\]
and a similar estimate holds for $C_t(\sigma,\sigma')$ in all cases where $\textup{\texttt{\footnotesize r}}[\sigma]+\textup{\texttt{\footnotesize r}}[\sigma']=1$. Finally,
	\[
	C_t(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}})
	= \frac{b_{1,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}) b_{2,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}})}
		{\mu_1(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})\mu_2(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}})}
	\prod_{j=3}^K b_{j,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\stackrel{(9.38)}{=}
	(2^{K-1})^2
	\prod_{j=3}^K b_{j,t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\Bigg\{1 + O\bigg(\frac1{2^{k\epsilon_1}}\bigg)\Bigg\}
	\le \frac{2^k}{2^{k\epsilon_1}}\,,
	\]
where the last bound uses the diversity bound (9.34). Combining with (9.39) gives
	\begin{align*}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma) /
		\partial \ln b_{2,t}(\sigma')}
		{\mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg|
	&=\Bigg| \overbrace{\Bigg\{
		\frac{Z_t\mu_t(\sigma_1=\sigma,\sigma_2=\sigma')}
		{\mu_1(\sigma)\mu_2(\sigma')}
		\Bigg\}}^{C_t(\sigma,\sigma')}
	\overbrace{\Bigg\{
	\frac{\mu_1(\sigma)\mu_2(\sigma')}
		{Z_t \mu_{1,t}(\sigma)
		\mu_{2,t}(\sigma')}
		\Bigg\}}^{1 + O(2^{-k\epsilon_1})}
		{} -1 \Bigg| \\
	&\le O(1) \begin{cases}
	2^{-k\epsilon_1} & \textup{if 
		$\textup{\texttt{\footnotesize r}}[\sigma]+\textup{\texttt{\footnotesize r}}[\sigma']=0$,}\\
	1 & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]+\textup{\texttt{\footnotesize r}}[\sigma']=1$,}\\
	2^{k(1-\epsilon_1)} & \textup{if 
		$\textup{\texttt{\footnotesize r}}[\sigma]=\textup{\texttt{\footnotesize r}}[\sigma']=1$.}
	\end{cases}
	\end{align*}
Rewriting the above in a more convenient form gives
	\begin{equation}
	\frac1{\mu_1(\sigma)}
	\Bigg|\frac{\partial \mu_{1,t}(\sigma)}
		{\partial\ln b_{2,t}(\sigma')}
		\Bigg|
	\le O\Big( A_{\textup{\texttt{\footnotesize r}}[\sigma],\textup{\texttt{\footnotesize r}}[\sigma']}
		\Big)\,,\quad
	A = \begin{pmatrix} A_{0,0} & A_{0,1}\\
		A_{1,0} & A_{1,1} \end{pmatrix}
	= \begin{pmatrix} 2^{-k\epsilon_1} & 2^{-k} \\
		1 & 2^{-k\epsilon_1} \end{pmatrix}\,.\end{equation}
Now recall the definition (9.31)
of $\mu_t$, and define
	\[
	\tilde{\mu}_t(\smash{\underline{\smash{\sigma}}})
	= \frac{ \mathbf{1}\{\smash{\underline{\smash{\sigma}}}\in\textup{\texttt{\footnotesize A}}\}}{Z_t}
	b_{1,t}(\sigma_1)
	\prod_{j=2}^K b_{j,t-1}(\sigma_j)\,.
	\]
It follows from the update rule (9.36) that the marginal of $\tilde{\mu}_t$ on the first edge is precisely $\mu_1$. Consequently,
	\begin{align*}
	\Bigg|
	\frac{b_{1,t+1}(\sigma)}
		{b_{1,t}(\sigma)}-1 \Bigg|
	&\stackrel{(9.36)}{=}\Bigg|
	\frac{\tilde{\mu}_t(\sigma_1=\sigma)}
		{\mu_t(\sigma_1=\sigma)}-1
	\Bigg|
	\le \frac{O(1)}{\mu_1(\sigma)}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg| \frac{\partial\mu_{1,t}(\sigma)}
		{\partial \ln b_{j,t}(\sigma')}\Bigg|
	\cdot
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|\\
	&\stackrel{(9.40)}{\le}
	\sum_{\sigma'} A_{\textup{\texttt{\footnotesize r}}[\sigma],\textup{\texttt{\footnotesize r}}[\sigma']}
	\sum_{j=2}^K\sum_{\sigma'}
	\Bigg|\ln \frac{b_{j,t}(\sigma')}
		{b_{j,t-1}(\sigma')}\Bigg|
	\stackrel{(9.37)}{\le}
	\frac{k}{2^{kt\epsilon_1/3}} \frac1{2^{3k\epsilon_1/2}}
	\sum_{\sigma'}
	A_{\textup{\texttt{\footnotesize r}}[\sigma],\textup{\texttt{\footnotesize r}}[\sigma']}
	(2^{k\epsilon_1/2})^{\textup{\texttt{\footnotesize r}}[\sigma]}\\
	&\stackrel{(9.40)}{\le}
	\frac1{2^{k(t+1)\epsilon_1/3}}
	\frac{(2^{k\epsilon_1/2})^{\textup{\texttt{\footnotesize r}}[\sigma]}}{2^{3k\epsilon_1/2}} \,.
	\end{align*}
This verifies the induction and proves
(9.37) for all $t\ge0$.
Taking $t\to\infty$ gives the weights $b=b_\infty$ for the optimal measure $\mu$. We can then use this to estimate
	\begin{align*}
	1-\mu\Big(\textup{\texttt{\footnotesize W}}^1 \cup \textup{\texttt{\footnotesize W}}^2\Big)
	&\le
	\mu\bigg( \sum_{j=1}^K
	\mathbf{1}\Big\{\sigma_j
		\in\{\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}}\}\Big\} \le4
	\bigg)
	\le
	\mu\bigg( \sum_{j=1}^K
	\mathbf{1}\{\sigma_j=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\} \ge K-6\bigg)
	\\
	&\le \sum_{|S| \le 6} \prod_{j\in[K]\setminus S}
			 b_j(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\le \frac1{2^{k(1+\epsilon_1)}}\,,
	\end{align*}
where the last bound follows from (9.37) together with the diversity bound (9.34). This implies the first assertion
(9.27) of the lemma. The second assertion 
(9.28)
(removing the conditioning on $\textup{\texttt{\footnotesize A}}$)
follows trivially, since the assumption that $\bm{L}$ is light means (by Definition~9.4) that
$\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})\le 2^{-k(1+\epsilon_\circ)}$
for all $j$, and so a union bound gives
	\[\hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize A}}^c )\le
	\sum_{j=1}^{k(\bm{L})} \omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
	\le \frac{k}{ 2^{k(1+\epsilon_\circ)}}\,.
	\]
It follows by combining with (9.27) that
	\[
	\hat{\nu}_{\bm{L}}\bigg(
		(\textup{\texttt{\footnotesize W}}^1 \cup \textup{\texttt{\footnotesize W}}^2)^c\bigg)
	\le
	\hat{\nu}_{\bm{L}}(\textup{\texttt{\footnotesize A}}^c )
	+\hat{\nu}_{\bm{L}}\bigg(
	(\textup{\texttt{\footnotesize W}}^1 \cup \textup{\texttt{\footnotesize W}}^2)^c \,\bigg|\,\textup{\texttt{\footnotesize A}}^c
	\bigg)
	\le \frac1{2^{k(1+\epsilon_1)}}
	+ \frac{k}{2^{k(1+\epsilon_\circ)}}\,,
	\]
as claimed.\end{proof}

Let $v$ be a nice variable with incoming messages $\hat{p}$ (in the augmented pair coloring model). Recalling the notation of Definition~7.27,
assume that for all $e\in\delta v$ we have (cf.\ (7.25))
	\begin{equation}
	\widehat{\textup{\textbf{\textsf{ERR}}}}(
		{}_{*}\hat{Q}_e
		,\hat{p}_e)
	\le	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\,.\end{equation}
Suppose $v$ has weight $\Phi_v$, of the functional form (7.55),
such that the measure $\mu\equiv \nu_{\delta v}[\Phi_v;\hat{p}]$
(defined using the notation of
(7.57))
is fully judicious. For the variable weights that do not depend on the clause types, assume that
(cf.\ (7.26))
	\[
	\adjustlimits
	\sum_{j=1,2}
	\sum_{x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}}
	\Big|\phi^j(x)-1\Big|
	\le \frac{k^{O(1)}}{2^{k\zeta}}\,,\quad
	\max_{e\in\delta v}\Bigg\{
	\sum_{j=1,2}
	\Big|(\phi_e)^j(\textup{\texttt{\footnotesize r}})-1\Big|
	\Bigg\}
	\le \frac{ k^{O(1)}}{2^{k\zeta}}
	\,.\]
For the variable weights that do depend on the clause types, assume that 
	\begin{equation}
	\widehat{\textup{\textbf{\textsf{ERR}}}}({}_\star\hspace{-1pt}\psi_e,\phi_e)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}\end{equation}
for ${}_\star\hspace{-1pt}\psi_e$ as defined by
(7.56). Now suppose we have a new set of messages $\hat{q}_e$,
such that
 (7.59)
 also holds with $\hat{q}$ in place of $\hat{p}$, such that
	\begin{equation}
	\widehat{\textup{\textbf{\textsf{ERR}}}}(\hat{p}_e,\hat{q}_e)
	\le \begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\ddot{\epsilon}_e
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} \\ 1 \\ 2^k
	\end{pmatrix}
	\end{equation}
for each $e\in\delta v$.
Then there exists a new set of weights
$\Psi_v$, also of the functional form (7.55), such that
$\nu_{\delta v}[\Psi_v;\hat{q}]$ is fully judicious.
In addition, the clause-independent weights in $\Psi_v$ satisfy the bounds
(7.27)
from Proposition~7.13.
The clause-dependent weights in $\Psi_v$ satisfy
	\begin{align}
	\max_{\bm{L}}
	\Bigg\{
	\Bigg|\frac{\psi_e(\bm{L})}{\phi_e(\bm{L})}-1\Bigg|
	+
	\adjustlimits\max_{j=1,2}
	\max_{\tau\ne\textup{\texttt{\footnotesize r}}}
	\Bigg|\frac{(\psi_e)^j(\tau\,|\,\bm{L})}
		{(\phi_e)^j(\tau\,|\,\bm{L})}
		-1\Bigg|
	\Bigg\}
	&\le
	\epsilon_e 
	+\frac{\dot{\epsilon}_e}{2^k}
	+\frac{\min\{\ddot{\epsilon}_e,1\}}{2^{k(1+\zeta)}}
	+\frac{\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}\,,\\
	\adjustlimits
	\max_{\bm{L}}
	\max_{j=1,2}
	\Bigg|\frac{(\psi_e)^j(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})}
		{(\phi_e)^j(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})}
		-1\Bigg|
	&\le
	\epsilon_e 
	+\dot{\epsilon}_e
	+\frac{\min\{\ddot{\epsilon}_e,1\}}{2^{k\zeta}}
	+\frac{\textup{\textsf{err}}_v}{2^{k\zeta}}

	\end{align}
If $\dot{p}_e$ are the original outgoing messages
and $\dot{q}_e$ are the new ones, then
(cf.\ Corollary~7.14)
	\begin{equation}
	\dddot{\textup{\textbf{\textsf{ERR}}}}(\dot{p}_e,\dot{q}_e)
	\le
	k^{O(1)}
	\begin{pmatrix}
	1\\1\\1\\ 
	2^{-k\zeta} \\
	2^{-k\zeta}
	\end{pmatrix} \textup{\textsf{err}}_v
	+k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1\\
	1&2^{-k}&2^{-k}\\
	1&1&1\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}\,,
	\end{equation}
again using the notation from Definition~7.27.

\begin{proof}
Since the proof is somewhat involved, we divide it into a few numbered parts. We again recall from
 (3.75)
that $\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})$
denotes the indicator of a valid augmented pair coloring of $\delta v$. It can be expressed as
	\[
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})
	= \varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\mathbf{1}\{\bm{L}_e\ni \bm{t}_e\}\,,
	\]
where $\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})$ is the indicator of a valid pair coloring on $\delta v$ (not augmented with clause types) as defined in (2.20);
and we write $\bm{L}\ni\bm{t}$ to indicate that $\bm{L}_j=\bm{t}$ for $j=j(\bm{t})$.\smallskip



\noindent
\textbf{\textup{\hypertarget{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1}. Iterative construction of $\Psi_v$.}}
We first give an iterative definition for a sequence of weights $\Psi_{v,t}$ ($t\ge0$),
all of the functional form (7.55).
We emphasize that this index $t$ is \textbf{\textup{purely local to the proof of this proposition}}, and is not the same as the $t$ that indexes the up-and-down passes in
Definition~7.25. 
We will show in the remainder of the proof that this sequence converges as $t\to\infty$ to the desired weights $\Psi_v=\Psi_{v,\infty}$. Initialize $\Psi_{v,0}\equiv\Phi_v$. For each $t\ge0$, we will update from $\Psi_{v,t}$ to $\Psi_{v,t+1}$ in three stages, summarized by the following table:
	\begin{equation}
	\begin{array}{c|ccc}
	& \psi_v(\smash{\underline{\smash{\sigma}}}_{\delta v}) 
	& (\psi_e)^j(\sigma^j\,|\,\bm{L})
	& \psi_e(\bm{L}) \\
	\hline
	\Psi_{v,t} & t & t & t \\
	\Psi_{v,t+1/3}	& t+1 & t & t \\
	\Psi_{v,t+2/3}	& t+1 & t+1 & t 
	\end{array}
	\end{equation}
--- e.g., the last row of the table indicates that the weight $\Psi_{v,t+2/3}$ 
is defined by
(7.55)
with the $(t+1)$-versions of 
$\psi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})$
and $(\psi_e)^j(\sigma^j\,|\,\bm{L})$
(for both $j=1,2$ and all $e\in\delta v$), but with the $t$-version of $\psi_e(\bm{L})$ (again for all $e\in\delta v$). For notational convenience,
we also define $\Psi_t\equiv \Phi$ for all $t<0$, and
	\begin{equation}
	\hat{q}_{e,t}(\sigma,\bm{L})
	\equiv\begin{cases}
	\hat{p}_e(\sigma,\bm{L})
	&\textup{if }t<0\,,\\
	\hat{q}_e(\sigma,\bm{L})
	&\textup{if }t\ge0\,.\\
	\end{cases}
	\end{equation}
We then abbreviate $\nu_t\equiv\nu_{\delta v}[\Psi_{v,t};\hat{q}_t]$, using the notation of (7.57); in particular this means $\nu_t=\nu_{\delta v}[\Phi;\hat{p}]$ for all $t<0$, while $\nu_0=\nu_{\delta v}[\Phi;\hat{q}]$.
For $t>0$, the weights
of (7.64) are defined by the following procedure (with $t$ denoting an integer time from now on):
\begin{enumerate}[A.]
\item From $t$ to $t+1/3$: 
we will suppose inductively that the measure
$\nu_{t-2/3}$ is judicious on average (in the terminology of Definition~7.26).
(For $t=0$, recall that we defined
$\nu_{-2/3}\equiv\nu_{\delta v}[\Phi,\hat{p}]$,
which by hypothesis is fully judicious and therefore also judicious on average.)
 At time $t$ (for $t\ge0$) we have
	\[
	\nu_t(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})
	= \frac1{\bm{\dot{z}}_{v,t}}
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\mathbf{1}\{ \bm{L}_e\ni\bm{t}_e \}
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\Bigg\}\,.
	\]
The marginal law of $\smash{\underline{\smash{\sigma}}}_{\delta v}$ under $\nu_t$ can then be expressed as
	\begin{equation}
	\bar{\nu}_t(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\cong
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)\,,
	\end{equation}
where $\bar{q}_{e,t}$ denotes the message at time $t$ averaged over $\bm{L}$:
	\begin{equation}
	\bar{q}_{e,t}(\sigma)
	\equiv
	\frac1{\bar{z}_{e,t}}
	\sum_{\bm{L}}
	\mathbf{1}\{\bm{L}\ni\bm{t}_e\}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})\,,
	\end{equation}
where $\hat{q}_{e,t}$ is defined by (7.65). Since we also defined $\psi_{e,t}\equiv\phi_e$ for negative $t$, this means that $\bar{q}_{e,t}(\sigma_e)$ is also well-defined for negative $t$. For instance, the marginal law of $\smash{\underline{\smash{\sigma}}}_{\delta v}$ at time 
$t-2/3$ is
	\begin{equation}
	\bar{\nu}_{t-2/3}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\cong
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t-1}(\sigma_e)\,,
	\end{equation}
including in the case $t=0$. Now, from the inductive assumption, $\nu_{t-2/3}$ is judicious on average, which means that the measure
$\bar{\nu}_{t-2/3}$ in
(7.68)
is judicious in the sense of Definition~3.43.
Comparing (7.66) with (7.68),
we see that we can
apply Proposition~7.13
--- with the variable weight function $\psi_{v,t}(\smash{\underline{\smash{\sigma}}}_{\delta v})$
and the two sets of incoming messages
$\bar{q}_{e,t-1}$ and $\bar{q}_{e,t}$
--- to define a new variable weight function $\psi_{v,t+1}(\smash{\underline{\smash{\sigma}}}_{\delta v})$ such that the measure
	\[
	\bar{\nu}_{t+1/3}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\cong
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t+1}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\bar{q}_{e,t}(\sigma_e)
	\]
is judicious in the sense of Definition~3.43,
i.e., such that $\nu_{t+1/3}$ is judicious on average.
Note that, since $t+1/3=(t+1)-2/3$,
this verifies the inductive assumption that
$\nu_{t-2/3}$ is judicious on average.

\item From $t+1/3$ to $t+2/3$:
for all $e\in\delta v$ and both $j=1,2$, update
	\begin{equation}
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}
	=
	\frac{{}_\star\hspace{-1pt}\pi_e(\tau)}
		{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L}) }
	\end{equation}
for all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$.

\item From $t+2/3$ to $t+1$: for all $e\in\delta v$ and both $j=1,2$, update 
	\begin{equation}
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{ \nu_{e,t+2/3}
		(\bm{L}_e) }\,,
	\end{equation}
using the notation from (3.76).
\end{enumerate}
The rest of the proof is devoted to the analysis of this iterative procedure. For the calculations that follow, it is useful to note that if $\bm{L}\not\ni\bm{t}_e$, then we must have $\psi_{e,t}(\bm{L})=0$ for all $t$. 
\smallskip

\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}. Error notations.}}
In the proof we will track the following error quantities for all times $t$. Let $\kappa$ measure the deviation from being conditionally judicious:
for $e\in\delta v$, $j=1,2$, 
and $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$, let
	\begin{equation}
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\equiv
	\frac{(\nu_{e,t})^j
	( \tau\,|\,\bm{L}) }{{}_\star\hspace{-1pt}\pi_e(\tau)}
	-1\,.\end{equation}
Taking the marginal over $\bm{L}$ gives
	\begin{align*}
	(\nu_{e,t})^j(\tau)
	&= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot
	(\nu_{e,t})^j
		( \tau\,|\,\bm{L})
	= \sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{ 1 + 
	(\kappa_{e,t})^j
		(\tau\,|\,\bm{L})
	\Bigg\}\\
	&=
	{}_\star\hspace{-1pt}\pi_e(\tau)
	\Bigg\{
	1 + 
	\underbrace{\bigg[\sum_{\bm{L}}
	\nu_{e,t}(\bm{L})
	\cdot (\kappa_{e,t})^j(\tau\,|\,\bm{L})
	\bigg]}_{\textup{denote this }
	(\chi_{e,t})^j(\tau)}
	\Bigg\}\,.
	\end{align*}
Notice also that since ${}_\star\hspace{-1pt}\pi_e$
and $(\nu_{e,t})^j(\cdot\,|\,\bm{L})$
are both probability measures over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$, we must have
	\begin{equation}
	\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t})^j(\tau\,|\,\bm{L})
	=0
	=\sum_\tau
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\chi_{e,t})^j(\tau)\,.
	\end{equation}
Next let $\rho$ measure the deviations in the clause proportions: for $e\in\delta v$,
	\begin{equation}
	\rho_{e,t}(\bm{L})
	\equiv
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	{\nu_{e,t}(\bm{L})}-1\,.\end{equation}
Next, recall the definition (7.58) of ${}_{*}\hat{Q}_e(\sigma,\bm{L})$, and let
	\begin{equation}
	\alpha_{e,t}(\sigma,\bm{L})
	\equiv
	\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ \psi_{e,0}(\sigma,\bm{L}) {}_{*}\hat{Q}_e(\sigma,\bm{L}) }
	-1
	=\frac{\psi_{e,t}(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})}
	{ {}_\star\hspace{-1pt}\psi_e(\bm{L}) {}_{*}\hat{q}_e(\sigma) /\hat{Z}_e}
	-1\,.\end{equation}
Lastly, let $\xi$ measure the deviation from being a product measure: for $e\in\delta v$,
	\[
	\xi_{e,t}(\sigma\,|\,\bm{L})
	\equiv
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)}-1
	\]
We will also make some shorthand notation for the maximum absolute values of the above quantities: let
	\begin{equation}
	\kappa_{e,t}(\tau)
	\equiv
	\max_{\bm{L},j}\Bigg\{
	\Big|(\kappa_{e,t})^j(\tau\,|\,\bm{L})\Big|
	\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\kappa_{e,t}\\
	\dot{\kappa}_{e,t}
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max\{\kappa_{e,t}(\tau):\tau\ne\textup{\texttt{\footnotesize r}}\}\\
	\kappa_{e,t}(\textup{\texttt{\footnotesize r}})
	\end{pmatrix}\,,\end{equation}
and let $\rho_{e,t}
\equiv \max_{\bm{L}}\{|\rho_{e,t}(\bm{L})|\}$.
Finally let
	\begin{equation}
	\alpha_{e,t}(\sigma)
	\equiv
	\max_{\bm{L}}\Bigg\{
		\Big|\alpha_{e,t}(\sigma\,|\,\bm{L})\Big|
			\Bigg\}
	\,,\quad
	\begin{pmatrix}
	\alpha_{e,t}\\
	\dot{\alpha}_{e,t}\\
	\ddot{\alpha}_{e,t}
	\end{pmatrix}
	=\begin{pmatrix}
	\max\{\alpha_{e,t}(\sigma) : \textup{\texttt{\footnotesize r}}[\sigma]=0\}\\
	\max\{\alpha_{e,t}(\sigma) : \textup{\texttt{\footnotesize r}}[\sigma]=1\}\\
	\max\{\alpha_{e,t}(\sigma) : \textup{\texttt{\footnotesize r}}[\sigma]=2\}
	\end{pmatrix}\,,
	\end{equation}
and make the analogous notation with $\xi$ in place of $\alpha$.
We will show by induction that for all $e\in\delta v$,
	\begin{equation}
	\sum_{t\in\mathbb{Z}/3,t\ge1/3}
	\begin{pmatrix}
	\rho_{e,t}+\kappa_{e,t} + \alpha_{e,t}
		\\
	\dot{\kappa}_{e,t}+\dot{\alpha}_{e,t}
		+\xi_{e,t}
		+ \dot{\xi}_{e,t}\\
	\ddot{\alpha}_{e,t}
		+\ddot{\xi}_{e,t}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 
		\\ 2^k \end{pmatrix}\end{equation}
for all $t\ge 1/3$. We also record a calculation that we will use repeatedly in what follows: for any integer $t$, at time $t+1/3$, according to the table (7.64) we have
	\[
	\nu_{t+1/3}(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})
	\cong
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})
	\psi_{v,t+1}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\psi_{e,t}(\sigma_e,\bm{L}_e)
	\hat{q}_{e,t}(\sigma_e,\bm{L}_e)\Bigg\}\,,
	\]
where we recall that $\hat{q}_{e,t}$ is defined by (7.65) for all $t$.
From this it is straightforward to verify that the marginal on an edge $e\in\delta v$ is given by
\begin{equation}
	\nu_{e,t+1/3}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e,t+1/3}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}}
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t+1}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'}
	\bar{q}_{e,t}(\sigma_{e'})
	\Bigg]}^{\textup{denote this }u_{e,t+1/3}(\sigma)}
	\end{equation}
where $\dot{z}_{e,t+1/3}$ is the normalizing constant that makes $u_{e,t+1/3}$ a probability measure over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$, and $\bm{\bar{z}}_{e,t+1/3}$ is the normalizing constant that makes $\nu_{e,t+1/3}$ a probability measure over pairs $(\sigma,\bm{L})$. For integers $t$ we will compare the following measures:
	\begin{align}
	\bm{\bar{z}}_{e,t-2/3}\nu_{e,t-2/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t-1}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\

	\bm{\bar{z}}_{e,t-1/3}\nu_{e,t-1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t-1}(\sigma,\bm{L})
		\psi_{e,t-1}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-1/3}(\sigma,\bm{L})\,,\\

	\bm{\bar{z}}_{e\bullet,t}
		\nu_{e\bullet,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t-2/3}(\sigma,\bm{L})\,,\\

	\bm{\bar{z}}_{e,t}\nu_{e,t}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t}(\sigma,\bm{L})\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&=\hat{q}_{e,t}(\sigma,\bm{L})
		\psi_{e,t}(\bm{L})
		\psi_{e,t}(\sigma\,|\,\bm{L})
		u_{e,t+1/3}(\sigma,\bm{L})\,.

	\end{align}
The remaining parts of the proof are organized as follows:
\begin{enumerate}[--]
\item
\hyperlink{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}
proves some preliminary bounds.

\item 
\hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b} controls $\nu_{e,t+1/3}$ 
in terms of $\nu_{e\bullet,t}$ 
for integers $t\ge0$, in the bounds (7.97)~and~(7.98).
The bounds also depend on the error $\underline{\smash{\epsilon}}(t)$ (see (7.87))
between
$\bar{q}_{e,t-2/3}$ and $\bar{q}_{e,t}$.

\item
\hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a} 
controls 
 $\bar{q}_{e,t-1/3}$ in terms of
 $\nu_{e,t-2/3}$ and $\bar{q}_{e,t-2/3}$,
in the bound (7.104).

\item
\hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b} controls
$\bar{q}_{e,t}$ in terms of
$\nu_{e,t-1/3}$ and $\bar{q}_{e,t-1/3}$,
in the bound (7.107).
\item \hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a} controls
	$\nu_{e,t-1/3}$
	in terms of $\nu_{e,t-2/3}$
	 for integers $t\ge1$
	 (in the bounds (7.111)
and (7.112)).
\item \hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b} compares
	$\nu_{e,t-1/3}$
	with $\nu_{e\bullet,t}$
	and $\nu_{e,t}$ for integers $t\ge1$
	(in the bounds (7.115)
and (7.116)).

\item 
\hyperlink{p:ctypes.varupdate.CONCLUSION}{Part~6} 
combines the results of the preceding parts to show that the iteration of Part~1 converges to the desired weights $\Psi_v\equiv\Psi_{v,\infty}$, and moreover that these weights satisfy the claimed bounds
(7.27)~and~(7.62).

\item \hyperlink{p:ctypes.varupdate.OUTMSG}{Part~7}
shows that the messages outgoing from the variable
satisfy the claimed bound
(7.63), thereby concluding the proof.


\end{enumerate}\smallskip


\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.PRELIM.BOUNDS}{Part~3a}. Preliminary bounds.}} Recall the definition (7.74)
of $\alpha_{e,t}$, and observe that
$\alpha_{e,1/3}=\alpha_{e,0}$. It follows from the assumptions 
(7.59) and
(7.60) that
	\[
	\Big|\alpha_{e,1/3}(\sigma,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=0$,}\\
	1 & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=1$,}\\
	2^k & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=2$,}\\
	\end{cases}\]
which verifies that 
$\alpha_{e,1/3}(\sigma)$
 satisfies the bound from (7.77).
The marginal on $\bm{L}$ at time $t=1/3$ satisfies
	\begin{align}
	\nu_{e,1/3}(\bm{L})
	&\stackrel{(7.78)}{=}
	\frac1{\bm{\bar{z}}_{e,1/3}} \sum_\sigma
		\phi_e(\sigma,\bm{L})
		\hat{q}_e(\sigma,\bm{L})
		u_{e,1/3}(\sigma)
	\\
	&\stackrel{(7.74)}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})}{\bm{\bar{z}}_{e,1/3}
		\hat{Z}_e}
	\sum_\sigma
	{}_{*}\hat{q}_e(\sigma)
	\Bigg(1+\alpha_e(\sigma,\bm{L})\Bigg)
	u_{e,1/3}(\sigma)
	= {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,,

	\end{align}
which proves that $\rho_{e,1/3}$
also satisfies the bound
from (7.77).
Next, the marginal on $\sigma$ at time $t=1/3$ is given by
	\begin{equation}
	\nu_{e,1/3}(\sigma)
	= \frac{\bar{z}_{e,1/3}}{\bm{\bar{z}}_{e,1/3}}
	\overbrace{\Bigg[
	\frac1{\bar{z}_{e,1/3}}
	\sum_{\bm{L}}
	\mathbf{1}\{\bm{L}\ni\bm{t}_e\}
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L})
	\Bigg]}^{\bar{q}_{e,0}(\sigma)
		=\bar{q}_{e,1/3}(\sigma)}
	u_{e,1/3}(\sigma)\,,
	\end{equation}
where we recall that $\bar{q}_{e,t}$ is defined by
 (7.67). It follows from 
the assumptions (7.59) and (7.60)
that
	\begin{equation}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,1/3})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}\,.
	\end{equation}
Substituting
(7.82)
into (7.81)
shows that $\nu_{e,1/3}(\sigma)$
is very close to the 
normalization of the 
measure
${}_{*}\hat{q}_e(\sigma) u_{e,1/3}(\sigma)$.
On the other hand, the same must be true for the conditional measure $\nu_{e,1/3}(\sigma\,|\,\bm{L})$, since
	\begin{align*}
	\nu_{e,1/3}(\sigma\,|\,\bm{L})
	&\stackrel{(7.78)}{=}
	\frac{
	\phi_e(\sigma,\bm{L})\hat{q}_e(\sigma,\bm{L}) u_{e,1/3}(\sigma) }
	{ \bm{\bar{z}}_{e,1/3}\nu_{e,1/3}(\bm{L})}
	\stackrel{(7.74)}{=}
	\frac{{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)}{ \bm{\bar{z}}_{e,1/3} \hat{Z}_e
	\nu_{e,1/3}(\bm{L})}
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}\\
	&\stackrel{(7.80)}
		{=}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	{}_{*}\hat{q}_e(\sigma)
	u_{e,1/3}(\sigma)
	\Bigg\{ 1 + \alpha_e(\sigma,\bm{L})\Bigg\}
	\Bigg\{ 1 + \frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\}\,.
	\end{align*}
Thus, by comparing both $\nu_{e,1/3}(\sigma)$
and $\nu_{e,1/3}(\sigma\,|\,\bm{L})$
with the normalization of
${}_{*}\hat{q}_e(\sigma)u_{e,1/3}(\sigma)$, we deduce that
	\begin{equation}
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{\nu_{e,1/3}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=0$,}\\
	1 & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=1$,}\\
	2^k & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=2$.}\\
	\end{cases}\end{equation}
Since the measure
$\nu_{e,1/3}$ is judicious by construction, 
this implies that $\kappa_{e,1/3}(\tau)$
satisfies the bounds from (7.77). 
Finally, we note that the variable \textsc{bp} recursion
together with (7.82) implies
	\[\Bigg|
	\frac{u_{e,1/3}(\sigma)}
		{{}_{*}\dot{q}_e(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\]
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$. Combining this with (7.59)
and (7.60) gives
	\[
	\Bigg|
	\frac{\nu_{e,1/3}(\sigma\,|\,\bm{L})}
		{{}_{*}\omega_e(\sigma)
		}-1\Bigg|\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\times
	\begin{cases}
	1& \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]\le1$,}\\
	2^k & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=2$.}\\
	\end{cases}
	\]
This implies that $\xi_{e,1/3}(\sigma)$ satisfy the bounds from (7.77).
Thus we have proved (7.77)
for the case $t=1/3$. We note for later use that
the inductive hypothesis (7.77) 
implies that (7.82) and (7.83)
hold more generally:
	\begin{equation}
	\widehat{\textup{\textsf{\footnotesize ERR}}}({}_{*}\hat{q}_e,\bar{q}_{e,t})
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^k
		\end{pmatrix}
	\end{equation}
for all $t\ge1/3$, and likewise
	\begin{equation}
	\Bigg|
	\frac{\nu_{e,t}(\sigma\,|\,\bm{L})}
		{\nu_{e,t}(\sigma)}-1\Bigg|
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\begin{cases}
	2^{-k} & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=0$,}\\
	1 & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=1$,}\\
	2^k & \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=2$}\\
	\end{cases}\end{equation}
for all $t\ge1/3$.\smallskip 

\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}. Analysis of general applications of update A.}} We next analyze the update from $t-2/3$ to $t+1/3$ for integer times $t\ge0$. 
At times $t-2/3$ and $t+1/3$ we have
(cf.\ (7.78),
and using the notation from (7.65))
	\begin{align}
	\bm{\bar{z}}_{e,t-2/3}
	\nu_{e,t-2/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t-1}(\sigma,\bm{L})
	\hat{q}_{e,t-1}(\sigma,\bm{L})
	\overbrace{\Bigg[
	\frac1{\dot{z}_{e,t-2/3}}
	\sum_{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}}
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t-1}(\sigma_{e'})
	\Bigg]}^{u_{e,t-2/3}(\sigma) }\,,\\
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	\underbrace{\Bigg[
	\frac1{\dot{z}_{e,t+1/3}}
	\sum_{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}}
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\psi_{v,t+1}(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e',t}(\sigma_{e'})
	\Bigg]}_{u_{e,t+1/3}(\sigma) }\,.

	\end{align}
We then estimate the error between $u_{e,t-2/3}$ and $u_{e,t+1/3}$. Recall the notation of Definition~7.5, and let 
	\begin{equation}
	\underline{\smash{\epsilon}}(t)
	\equiv\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\ddot{\epsilon}_e(t)
	\end{pmatrix}
	\equiv
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})\,.\end{equation}
(Note that $\bar{q}_t=\bar{q}_{t+1/3}$.)
Recall also the notation of Definition~7.10, and let
	\begin{equation}
	\underline{\smash{\delta}}(t+1/3)
	\equiv
	\begin{pmatrix}
	\delta_e(t)\\
	\dot{\delta}_e(t+1/3)\\
	\ddot{\delta}_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\delta_e(t+1/3)\\
	{}^\textup{m}\hspace{-2pt}\dot{\delta}_e(t+1/3)
	\end{pmatrix}
	\equiv\dddot{\textup{\textsf{\footnotesize ERR}}}(
	u_{e,t-2/3},
	u_{e,t+1/3})\,.
	\end{equation}
The measure $\nu_{e,t-2/3}$ is judicious on average for all $t\ge0$ (and fully judicious for $t=0$).
It then follows by Corollary~7.14 (whose conditions are satisfied, in view of 
(7.84)) that
	\begin{equation}
	\underline{\smash{\delta}}(t+1/3)
	\le
	k^{O(1)}
	\begin{pmatrix}
	1\\1\\1\\ 2^{-k\zeta} \\2^{-k\zeta}
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ k^{O(1)}
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1\\
	1&2^{-k}&2^{-k}\\
	1&1&1\\
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\{\ddot{\epsilon}_e(t),1\}/2^{k\zeta}
	\end{pmatrix}\,,
	\end{equation}
with $\textup{\textsf{err}}_v(t)$ defined analogously to (7.27). Now,
recalling (7.86), we will consider also an intermediate measure $\nu_{e\bullet,t}$, which we define by
	\begin{equation}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	=\frac1{\bm{\bar{z}}_{e\bullet,t}}
		\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_{e,t}(\sigma,\bm{L})
	 u_{e,t-2/3}(\sigma)\,.\end{equation}
Let $\chi_{e\bullet,t}$,
$\kappa_{e\bullet,t}$, etc.\
be defined analogously to the quantities in 
\hyperlink{p:ctypes.varupdate.ERROR.NOTATIONS}{Part~2}
with $\nu_{e\bullet,t}$
in place of $\nu_{e,t}$. 
In this part of the proof we shall abbreviate
(recalling (7.75) and (7.76))
	\begin{equation}
	\begin{pmatrix}
	\kappa_{e\bullet}(\tau)\\
	\alpha_{e\bullet}(\sigma)
	\end{pmatrix}
	\equiv\begin{pmatrix}
	\max_{\bm{L},j}\{|(
		\kappa_{e\bullet,t}
		)^j(\tau\,|\,\bm{L})|\}\\
	\max_{\bm{L}}\{|
		\alpha_{e\bullet,t}
		(\sigma\,|\,\bm{L})|\}
	\end{pmatrix}\,,
	\end{equation}
Comparing with $\nu_{e,t+1/3}$ gives
	\begin{equation}
	\gamma_{e,t}(\sigma)
	\equiv
	\frac{\nu_{e,t+1/3}(\sigma,\bm{L})}
	{\nu_{e\bullet,t}(\sigma,\bm{L})} -1
	= 
	\frac{ \bm{\bar{z}}_{e\bullet,t}}{\bm{\bar{z}}_{e,t+1/3}}
	\cdot
	\frac{ u_{e,t+1/3}(\sigma)}
	{ u_{e,t-2/3}(\sigma)} - 1\,,
	\end{equation}
where we emphasize that this error does not depend on $\bm{L}$. As a result, marginally on $\sigma$ we also have
	\begin{equation}
	\gamma_{e,t}(\sigma)
	=
	\frac{\nu_{e,t+1/3}(\sigma)}
	{\nu_{e\bullet,t}(\sigma)} -1\,.\end{equation}
Substituting (7.89) into the expression (7.92) for $\gamma_{e,t}$ gives
	\begin{equation}
	\Big|\gamma_{e,t}(\sigma)\Big|
	\le 
	k^{O(1)}\Bigg\{
	\textup{\textsf{err}}_v(t)
	+ \mathbf{1}\{\textup{\texttt{\footnotesize r}}[\sigma]\ge1\}\Bigg(
	\dot{\epsilon}_e(t)
	+\frac{\min\{\ddot{\epsilon}_e(t),1\}}
		{2^{k\zeta}}
	\Bigg)
	\Bigg\}\,.
	\end{equation}
We then compare the marginal laws of $(\sigma^1,\bm{L})$ 
under $\nu_{e\bullet,t}$ and $\nu_{e,t+1/3}$:
by the definition of $\gamma_{e,t}$, we have
	\begin{align}
	&\nu_{e,t+1/3}(\sigma^1,\bm{L})
	-\nu_{e\bullet,t}(\sigma^1,\bm{L})
	=
	\sum_{\sigma^2}
	\nu_{e\bullet,t}(\sigma,\bm{L})
	\gamma_{e,t}(\sigma)\\
	&=
	\nu_{e\bullet,t}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	\underbrace{
	\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}
		{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]
	}_{\textup{denote this }
	(X_{e,t})^1(\sigma^1)}
	+
	\underbrace{\Bigg[
	\sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})
	-\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\gamma_{e,t}(\sigma)
	\Bigg]}_{\textup{denote this }
		(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L} )}
	\Bigg\}\,.

	\end{align}
We note that the $X$ term
in (7.95) can be simplified
using (7.93)
and the fact that $\nu_{e,t+1/3}$ is judicious on average:
	\[
	(X_{e,t})^1(\sigma^1)
	=\sum_{\sigma^2}	
	\frac{
	\nu_{e,t+1/3}(\sigma)
	-\nu_{e\bullet,t}(\sigma)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	= 1 -
	\frac{(\nu_{e\bullet,t})^1(\sigma^1)
	}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	=- (\chi_{e\bullet,t})^1(\sigma^1)\,.
	\]
It follows from the definition of $\chi$ that for all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$ we have
	\[
	\Big|
	(X_{e,t})^1(\tau)\Big|
	= \Big|
	(\chi_{e\bullet,t})^1(\tau)
	\Big|
	\le
	\max_{\bm{L}}
	\Bigg\{\Big|
	(\kappa_{e\bullet,t})^1(\tau\,|\,\bm{L})
	\Big|\Bigg\}
	=\kappa_{e\bullet}(\tau)\,.
	\]
Summing (7.95) over $\sigma^1=\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$
and recalling (7.72) gives
	\begin{equation}
	\nu_{e,t+1/3}(\bm{L})
	-\nu_{e\bullet,t}(\bm{L})
	= \nu_{e\bullet,t}(\bm{L})
	\Bigg\{\sum_{\tau}
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(Y_{e,t})^1(\tau\,|\,\bm{L} )
	\Bigg\}\,.
	\end{equation}
Now, the $Y$ term in (7.95) can be bounded as 
	\[\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le \sum_{\sigma^2}
	\frac{\nu_{e\bullet,t}(\sigma)}{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	\Bigg|
	\frac{\nu_{e\bullet,t}(\sigma\,|\,\bm{L})}
	{\nu_{e\bullet,t}(\sigma)}-1
	\Bigg|
	\gamma_{e,t}(\sigma)\,.\]
It follows from (7.85) and (7.94) that 
if $\sigma^1\ne\textup{\texttt{\footnotesize r}}$,
	\[
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\bigg(\gamma_{e,t}+\dot{\gamma}_{e,t}
		\bigg)
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\{\dot{\epsilon}_e(t),1\}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\]
If $\sigma^1=\textup{\texttt{\footnotesize r}}$ then we recall from
(7.79)
 that $\nu_{e\bullet,t}\cong
 \hat{q}_{e,t} \psi_{e,t} u_{e\bullet,t}$,
 from which it follows that
 $\nu_{e\bullet,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\,|\,\bm{L}) \le 
 k^{O(1)}/2^{-(1+\zeta)}$. 
It then follows that
	\begin{align*}
	\Big|(Y_{e,t})^1
		(\sigma^1\,|\,\bm{L})\Big|
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\dot{\gamma}_{e,t}
	+O\Bigg(
	\frac{\max_{\bm{L}}\{
	\nu_{e\bullet,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\,|\,\bm{L})\}}
	{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
	\ddot{\gamma}_{e,t}
	\Bigg)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\dot{\gamma}_{e,t}
	+\ddot{\gamma}_{e,t}\bigg)
	\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\{\dot{\epsilon}_e(t),1\}}
			{2^{k\zeta}}
	\Bigg\}
	\end{align*}
Substituting these bounds for $Y$ back into
(7.96) gives, for $t\ge1$, 
	\begin{equation}
	\rho_{e,t+1/3}
	= \max_{\bm{L}}\Bigg\{ \Big|
	\rho_{e,t+1/3}(\bm{L})\Big|\Bigg\}
	\le 
	\rho_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\textup{\textsf{err}}_v(t) + \dot{\epsilon}_e(t)
		+ \frac{\min\{\dot{\epsilon}_e(t),1\}}
			{2^{k\zeta}}
	\Bigg\}\,.
	\end{equation}
Substituting the bounds for $X$ and $Y$ back into (7.95),
and combining with (7.96), gives
	\begin{align}

	\kappa_{e,t+1/3}
	&\le 
	\rho_{e\bullet,t}
	+\kappa_{e\bullet,t}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)+\dot{\epsilon}_e(t)
	+\frac{\min\{\ddot{\epsilon}_e(t),1\}}
		{2^{k\zeta}}
	\Bigg\}\,,\\
	\dot{\kappa}_{e,t+1/3}
	&\le
	\rho_{e\bullet,t}
	+\dot{\kappa}_{e\bullet,t}+
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	 \textup{\textsf{err}}_v(t)
	+\dot{\epsilon}_e(t)
	+\frac{\min\{\ddot{\epsilon}_e(t),1\}}
		{2^{k\zeta}}
	\Bigg\}\,.

	\end{align}
for all $t\ge0$.
We next turn to the question of bounding $\underline{\smash{\epsilon}}(t)$ (as defined by (7.87)) for $t\ge1$.\smallskip



\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}. Errors in averaged messages incurred by update B.}} We now estimate the error between the averaged messages 
$\bar{q}_{e,t+1/3}$ and $\bar{q}_{e,t+2/3}$ for $t\ge0$. Between times $t+1/3$ and $t+2/3$ we only make the update
(7.69). In this part of the proof we will fix $e\in\delta v$ and abbreviate
(recalling
(7.75) and (7.76))
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma)
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t+1/3}(\sigma)
	\end{pmatrix}
	=\begin{pmatrix}
	\kappa_{e,t+1/3}(\tau) \\ 
	\alpha_{e,t}(\sigma)
	\end{pmatrix}
	\,.
	\]
By the definition
(7.71) of $\kappa$, it holds for all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$ that
	\begin{equation}
	0=
	\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_{\bm{L}}\nu_{e,t+1/3}(\bm{L})
	{}_\star\hspace{-1pt}\pi_e(\tau)
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})\,,
	\end{equation}
where the first equality holds because $\nu_{e,t+1/3}$ is judicious on average. We now turn to comparing the messages. At time $t+1/3$ we have
$\bar{q}_{e,t+1/3}=\bar{q}_{e,t}$, defined by
 (7.67). More explicitly, it follows using
(7.78) that
	\begin{equation}
	\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+1/3}
		\nu_{e,t+1/3}(\sigma)
		}{u_{e,t+1/3}(\sigma)}
	\,,\end{equation}
On the other hand, at time $t+2/3$ we have (by Taylor expansion)
	\begin{align}
	&\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	=\sum_{\bm{L}}
	\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1 +( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	}\\
	&\qquad
	=\bar{z}_{e,t}
	\Bigg\{
	\bar{q}_{e,t}(\sigma)
	\bigg\{
	1 + O \bigg(
		\sum_{j=1,2} \kappa_e(\sigma^j)^2
			\bigg)
	\bigg\}
	-\sum_{j=1,2}
	\underbrace{\Bigg[
	\sum_{\bm{L}}
	\frac{\psi_{e,t}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t}}
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg]}_{\textup{denote this }K^j(\sigma)}
	\Bigg\}

	\end{align} 
From the definition of $K^j(\sigma)$ we can easily deduce the bound 
	\begin{equation}
	\Big|K^j(\sigma)\Big|
	\le 
	O\Bigg(
	\frac{\kappa_e(\sigma^j)}{\bar{z}_{e,t}\hat{Z}_e}
	\bar{q}_{e,t}(\sigma)
	\sum_{\bm{L}} {}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg)
	= O\bigg(
	\bar{q}_{e,t}(\sigma)
	\cdot \kappa_e(\sigma^j) \bigg)\,,\end{equation}
where the last step uses that
$\bar{z}_{e,t}\hat{Z}_e=\Theta(1)$ by a similar calculation as in (7.80).
On the other hand, we also have
	\begin{align}
	\Big|K^j(\sigma)\Big|
	&=\Bigg|
	\frac{{}_{*}\hat{q}_e(\sigma)}{\hat{Z}_e}
	\sum_{\bm{L}}{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\Bigg(1 + 
	\alpha_{e,t}(\sigma,\bm{L})
		\Bigg)
	( \kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})
	\Bigg|\\
	&\stackrel{(7.99)}{\le}
	O\bigg( {}_{*}\hat{q}_e(\sigma) \cdot \kappa_e(\sigma^j) \cdot \alpha_e(\sigma) \bigg)\,.

	\end{align}
Combining (7.102) with (7.103) gives 
	\[
	K^j(\sigma)
	= O\Bigg(
	\bar{q}_{e,t}(\sigma)\cdot
	\kappa_e(\sigma^j)\cdot
	\min\bigg\{
	\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},
	1\bigg\}
	\Bigg)\,.
	\]
Substituting this bound into (7.101) gives 
	\begin{align*}
	\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	&= \bar{z}_{e,t}\bar{q}_{e,t}(\sigma)
	\Bigg\{
	1+\sum_{j=1,2}\kappa_e(\sigma^j)
	\cdot \min\bigg\{
		\frac{\alpha_e(\sigma) {}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t}(\sigma)},1\bigg\}
	\Bigg\}\,.
	\end{align*}
It then follows using the hypothesis 
(7.77) 
 that
	\[\Bigg|
	\frac{\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)}
	{\bar{z}_{e,t}\bar{q}_{e,t}(\sigma)}-1\Bigg|
	\le
	k^{O(1)}
	\begin{cases} \displaystyle
	\frac{\kappa}{2^{k(1+\zeta)}}
	&\textup{if }\textup{\texttt{\footnotesize r}}[\sigma]=0\,,\medskip\\
	\displaystyle
	\frac{\kappa+\dot{\kappa}}
		{2^{k\zeta}}
	&\textup{if }\textup{\texttt{\footnotesize r}}[\sigma]=1\,,\medskip\\
	\displaystyle \dot{\kappa}
	&\textup{if }\textup{\texttt{\footnotesize r}}[\sigma]=2\,.
	\end{cases}
	\]
Altogether, the error in averaged messages
between times $t+1/3$
and $t+2/3$ satisfies
	\begin{equation}
	\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t+1/3},
	\bar{q}_{e,t+2/3})
	=\widehat{\textup{\textsf{\footnotesize ERR}}}
	(\bar{q}_{e,t},
	\bar{q}_{e,t+2/3})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k}\\
	1 & 1 \\
	2^{-k}&2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\end{equation}
Substituting (7.104)
into the definition of $u$ from (7.78) gives
	\begin{equation}
	\Bigg|
	\frac{u_{e,t+2/3}(\sigma)}
		{u_{e,t+1/3}(\sigma)}
	-1\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\underbrace{\sum_{e\in\delta v}
	\kappa_{e,t+1/3}
	}_{\textup{denote this }\bm{\kappa}_{t+1/3}}
	+\underbrace{
	\sum_{e\in\delta v}
	\dot{\kappa}_{e,t+1/3}
	}_{\textup{denote this }\bm{\dot{\kappa}}_{t+1/3}}
	\Bigg\}
	\equiv
	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$.\smallskip


\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}. Errors in averaged messages incurred by update C.}} By a similar (but somewhat simpler) calculation, we can also estimate the error between the averaged messages $\bar{q}_{e,t+2/3}$ and $\bar{q}_{e,t+1}$ for $t\ge0$. Between times $t+2/3$ and $t+1$ we only make the update (7.70). 
In this part of the proof we will fix $e\in\delta v$ and abbreviate
	\[
	\begin{pmatrix}
	\kappa_e(\tau) \\ \alpha_e(\sigma) \\ \rho_e
	\end{pmatrix}
	\equiv
	\begin{pmatrix}
	\kappa_{e,t+2/3}(\tau) \\ 
	\alpha_{e,t+2/3}(\sigma) \\ 
	\rho_{e,t+2/3}
	\end{pmatrix}\,.
	\]
By the definition (7.73) of $\rho$, we have
	\begin{equation}	0=
	\sum_{\bm{L}}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	-\nu_{e,t+2/3}(\bm{L})
	\Bigg\}
	=\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{
	\rho_{e,t+2/3}(\bm{L})
	+O\Big((\rho_e)^2\Big)\Bigg\}\,.\end{equation}








We now turn to the comparison of the messages:
by the update rule (7.70),
	\begin{align*}
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	&= \sum_{\bm{L}}
	\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	\bigg\{1 + \rho_{e,t+2/3}(\bm{L}) \bigg\} \\
	&=\bar{z}_{e,t+2/3}
	\Bigg\{\bar{q}_{e,t+2/3}(\sigma)
	+\underbrace{
	\Bigg[\sum_{\bm{L}}
	\frac{\psi_{e,t+2/3}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})}{\bar{z}_{e,t+2/3}}
	\rho_{e,t+2/3}(\bm{L}) 
	\Bigg]}_{\textup{denote this }R(\sigma)}\Bigg\}\,.
	\end{align*}
From the definition of $R(\sigma)$ we can easily deduce the bound
	\[
	\Big|R(\sigma)\Big|
	\le
	O\bigg( \bar{q}_{e,t+2/3}(\sigma)
		\cdot \rho_e\bigg)\,.
	\]
On the other hand we also have
	\begin{align*}
	R(\sigma)
	&=
	\frac{{}_{*}\hat{q}_e(\sigma)
	}{\bar{z}_{e,t+2/3} \hat{Z}_e}
	\sum_{\bm{L}}
	{}_\star\hspace{-1pt}\psi_e(\bm{L})
	\bigg(1 + \alpha_{e,t+1/3}(\sigma,\bm{L})\bigg)
	\rho_{e,t+2/3}(\bm{L}) \\
	&=
	O\Bigg(
	{}_{*}\hat{q}_e(\sigma)\cdot
	\rho_e 
	\cdot\Big(\rho_e+\alpha_e(\sigma)\Big)\Bigg)\,,
	\end{align*}
where the last step uses (7.106).
Substituting back into the preceding calculation gives
	\[
	\bar{z}_{e,t+1}\bar{q}_{e,t+1}(\sigma)
	=\bar{z}_{e,t+2/3}\bar{q}_{e,t+2/3}(\sigma)
	\Bigg\{
	1 + O\bigg(
	\rho_e \cdot
	\min\bigg\{
	\frac{(\rho_e+\alpha_e(\sigma)){}_{*}\hat{q}_e(\sigma)}
		{\bar{q}_{e,t+2/3}(\sigma)} ,1
	\bigg\}\bigg)
	\Bigg\}\,.\]
It follows using the inductive bounds (7.77) that
	\begin{equation}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{e,t+2/3},\bar{q}_{e,t+1})
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\rho_{e,t+2/3}
	\begin{pmatrix} 2^{-k} \\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.
	\end{equation}
Substituting this again into the definition (7.78) of $u$ gives
	\begin{equation}
	\Bigg|
	\frac{u_{e,t+1}(\sigma)}
	{u_{e,t+2/3}(\sigma)}-1
	\Bigg|
	\le
	\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\sum_{e\in\delta v}
	\rho_{e,t+2/3}
	\equiv
	\frac{k^{O(1)} }{2^{k(1+\zeta)}}
		\bm{\rho}_{t+2/3}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$.\smallskip

\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.UPDATE.B.MGL}{Part 5a}. Errors in marginals incurred by update B.}} We now estimate the change in the edge marginals between times $t+1/3$ and $t+2/3$, resulting from update (7.69). To this end we introduce an intermediate measure $\nu_{e,t+1/2}$, in which we use the new weight $\psi_{e,t+1}(\sigma\,|\,\bm{L})$ but the old message $u_{e,t+1/3}$. Thus, recalling (7.78), we have
	\begin{align*}
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\sigma,\bm{L})
	&= 
	\hat{q}_e(\sigma,\bm{L})\psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+1/3}(\sigma)\,,\\
	\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	&=\hat{q}_e(\sigma,\bm{L}) \psi_{e,t}(\bm{L})
	\psi_{e,t+1}(\sigma\,|\,\bm{L})
	u_{e,t+2/3}(\sigma)\,.
	\end{align*}
We first estimate the error between times $t+1/3$ and $t+2/3$. For this purpose, note that (7.71) implies
(similarly to the relation (7.72) that was used earlier) that for all $\bm{L}$,
	\begin{align}
	0&=\sum_\tau
	\Bigg\{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-{}_\star\hspace{-1pt}\pi_e(\tau)\Bigg\}
	=\sum_\tau\Bigg\{
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	-\frac{ (\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})}
		{1 + (\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})}
	\Bigg\} \\
	&=\sum_\tau
	(\nu_{e,t+1/3})^j(\tau\,|\,\bm{L})
	(\kappa_{e,t+1/3})^j(\tau\,|\,\bm{L})
	+ O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}(\tau)^2\Bigg)\,.

	\end{align}
It follows using (7.109) that the marginal error on $\bm{L}$ between times $t+1/3$ and $t+1/2$ is given by
	\begin{align}
	\bm{\bar{z}}_{e,t+1/2}\nu_{e,t+1/2}(\bm{L})
	&=\sum_\sigma
	\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\sigma,\bm{L})
	\prod_{j=1,2}
	\frac1{1+(\kappa_{e,t+1/3})^j(\sigma^j\,|\,\bm{L})} \\
	&=\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})
	\Bigg\{1 +
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)\Bigg\}\,.

	\end{align}
We note the error term can be simplified
using (7.77) as
	\[
	\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2
	\le k^{O(1)}\Bigg(
	(\kappa_{e,t+1/3})^2
	+\frac{(\dot{\kappa}_{e,t+1/3})^2}{2^k}
	\Bigg)
	\le
	\frac{k^{O(1)}
		(\kappa_{e,t+1/3}+\dot{\kappa}_{e,t+1/3})}
		{ 2^{k(1+\zeta)}}\,.
	\]
The error between $u_{e,t+1/3}$ and $u_{e,t+2/3}$
is bounded by (7.105), and this gives the marginal error on $\bm{L}$ between times $t+1/2$ and $t+2/3$. Combining these bounds gives altogether
	\begin{equation}
	\rho_{e,t+2/3}
	-\rho_{e,t+1/3}
	\le
	\Bigg|\frac{\nu_{e,t+2/3}(\bm{L})}
	{\nu_{e,t+1/3}(\bm{L})}-1\Bigg|
	\le \frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}\,.
	\end{equation}
Next we argue that the update (7.69) in fact brings the measures closer to being conditionally judicious. Indeed, focusing on the first copy $j=1$,
we can express
	\[
	\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=
	\frac{
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\frac{\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{1+(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})}\,,
	\]
and summing over $\sigma^2$ gives
	\begin{align*}
	&\frac{\bm{\bar{z}}_{e,t+1/2}
	\nu_{e,t+1/2}(\sigma^1,\bm{L})}
	{\bm{\bar{z}}_{e,t+1/3}\nu_{e,t+1/3}(\bm{L})}
	=\frac{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	\sum_{\sigma^2}
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})
	\Bigg\{
	1 + O(\kappa_{e,t+1/3}(\sigma^2)^2) - 
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{ (\nu_{e,t+1/3})^1(\sigma^1\,|\,\bm{L}) }
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	\Bigg\}\\
	&\qquad=
	{}_\star\hspace{-1pt}\pi_e(\sigma^1)
	\Bigg\{
	1+ 
	O\Bigg(\sum_\tau
		{}_\star\hspace{-1pt}\pi_e(\tau) \kappa_{e,t+1/3}
		(\tau)^2\Bigg)
	-\underbrace{\sum_{\sigma^2}
	\frac{
	\nu_{e,t+1/3}(\sigma\,|\,\bm{L})}
	{{}_\star\hspace{-1pt}\pi_e(\sigma^1)}
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})
	}_{\textup{denote this }S^1(\sigma^1\,|\,\bm{L})}
	\Bigg\}\,.
	\end{align*}
We then use 
(7.77)
and (7.99) to estimate (with $\kappa\equiv \kappa_{e,t+1/3}$
and $\xi\equiv \xi_{e,t+1/3}$)
	\begin{align*}
	S(\sigma^1\,|\,\bm{L})
	&=
	\sum_{\sigma^2}
	\bigg\{
	1+\xi_{e,t+1/3}(\sigma\,|\,\bm{L})\bigg\}
	{}_\star\hspace{-1pt}\pi_e(\sigma^2)
	(\kappa_{e,t+1/3})^2(\sigma^2\,|\,\bm{L})\\
	&\le
	\begin{cases}\displaystyle
	k^{O(1)}\bigg(
	\kappa\xi + \frac{\dot{\kappa}\dot{\xi}}{ 2^k}\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\bigg(
	\kappa
	+	\frac{\dot{\kappa}}{2^k}
		\bigg)
	& \textup{if }\sigma^1\ne\textup{\texttt{\footnotesize r}}\,,\medskip\\
	\displaystyle
	k^{O(1)}\bigg(
	\kappa\dot{\xi} + \frac{\dot{\kappa} \ddot{\xi}}{2^k}
		\bigg)
	\le \frac{k^{O(1)}}{2^{k\zeta}}
		(\kappa + \dot{\kappa})
	& \textup{if }\sigma^1=\textup{\texttt{\footnotesize r}}\,.
	\end{cases}
	\end{align*}
By substituting this into the preceding calculation
 and combining with
(7.110), 
we conclude that
	\[
	\begin{pmatrix}
	\kappa_{e,t+1/2}\\
	\dot{\kappa}_{e,t+1/2}
	\end{pmatrix}
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} \\
	1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}\,.
	\]
We combine this with the error incurred by going from time $t+1/2$ to $t+2/3$ --- this results from the change in the message $u$, which again is bounded by (7.105). Altogether we conclude
	\begin{equation}
	\begin{pmatrix}
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1& 2^{-k} \\
	1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)}
		(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3})
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\end{pmatrix}
	\end{equation}
for all $e\in\delta v$.\smallskip


\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}. Errors in marginals incurred by update C.}} We now estimate the change in edge marginals between times $t+2/3$ and $t+1$, resulting from update (7.70). To this end, we can express
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\frac{u_{e,t+1}(\sigma)}{u_{e,t+2/3}(\sigma)}\\
	&=\bm{\bar{z}}_{e,t+2/3}\nu_{e,t+2/3}(\sigma,\bm{L})
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{\nu_{e,t+2/3}(\bm{L})}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{align*}
where the last estimate comes from (7.108). Summing over $\sigma$ gives
	\begin{equation}
	\nu_{e,t+1}(\bm{L})
	= \frac{\bm{\bar{z}}_{e,t+2/3}
		\cdot \pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{\bm{\bar{z}}_{e,t+1}}
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}\,,
	\end{equation}
where the last equality is because both 
$\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$
and $\nu_{e,t+1}(\bm{L})$ are probability measures over $\bm{L}$. On the other hand, the conditional measures given $\bm{L}$ change very little as a result of update (7.70): it follows from the above that
	\begin{equation}
	\nu_{e,t+1}(\sigma\,|\,\bm{L})
	=\nu_{e,t+2/3}(\sigma\,|\,\bm{L})
	\Bigg\{ 1 + O\bigg( 
	\frac{k^{O(1)} \bm{\rho}_{t+2/3}}{2^{k(1+\zeta)}}
		\bigg)\Bigg\}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2$. 
Combining (7.113) and (7.114) gives
	\begin{equation}
	\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	\le
	\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+ \frac{k^{O(1)}}{2^{k(1+\zeta)}} \bm{\rho}_{t+2/3}
		\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Finally,
recalling
(7.90), we compare the measures
	\begin{align*}
	\bm{\bar{z}}_{e,t+1}\nu_{e,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1}(\sigma)\,,\\
	\bm{\bar{z}}_{e\bullet,t+1}
		\nu_{e\bullet,t+1}(\sigma,\bm{L})
	&= \psi_{e,t+1}(\sigma,\bm{L})
	\hat{q}_e(\sigma,\bm{L})
	u_{e,t+1/3}(\sigma)\,.
	\end{align*}
It follows by combining
(7.105) and (7.108) that
	\begin{equation}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	\rho_{e,t+1}\\
	\kappa_{e,t+1}\\
	\dot{\kappa}_{e,t+1}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(\bm{\kappa}_{t+1/3}+\bm{\dot{\kappa}}_{t+1/3}
	+\bm{\rho}_{t+2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
This concludes our analysis of update C.\smallskip

\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.CONCLUSION}{Part~6}. Convergence of iterative procedure.}} We now collect the bounds obtained above to prove that the iterative procedure described in \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges. Recall from (7.87) the definition of $\underline{\smash{\epsilon}}(t)$. For $t\ge1$, it follows by combining (7.104) (from \hyperlink{p:ctypes.varupdate.UPDATE.B.MSG}{Part~4a}) and (7.107) (from \hyperlink{p:ctypes.varupdate.UPDATE.C.MSG}{Part~4b}) that we have
	\begin{equation}
	\underline{\smash{\epsilon}}(t)
	\le 
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta}
	&2^{-k}&2^{k\zeta} 
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}\,.
	\end{equation}
It will be useful to abbreviate $\bm{K}\equiv\bm{\kappa}+\bm{\dot{\kappa}}$.
Recall that $\textup{\textsf{err}}_v(t)$ is defined analogously to
(7.27), so
	\[\textup{\textsf{err}}_v(t)\le
	\sum_{e\in\delta v}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k(1+\zeta)}
	\end{pmatrix}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} &2^{k\zeta}
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-1/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}






	\le \frac{k^{O(1)}
		(\bm{K}_{t-2/3}
		+\bm{\rho}_{t-1/3}
	)}{2^{k(1+\zeta)}}
	\,.\]
We then substitute these bounds into the analysis of update A, from \hyperlink{p:ctypes.varupdate.UPDATE.A.GENERAL}{Part~3b}: from (7.97) 
and (7.98) we obtain
	\begin{equation}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	\frac{\bm{\rho}_{t-1/3}+\bm{K}_{t-2/3}}
		{2^{k(1+\zeta)}} 
	+ \frac{\kappa_{e,t-2/3}
	+\dot{\kappa}_{e,t-2/3}
	+\rho_{e,t-1/3}}{2^{k\zeta}}
	\Bigg\}
	\begin{pmatrix}
	1\\1\\2^k
	\end{pmatrix}\,.
	\end{equation}
Next, from the analysis of the marginal errors resulting from update B (\hyperlink{p:ctypes.varupdate.UPDATE.B.MGL}{Part~5a}), we have
the bounds
 (7.111) and
(7.112), which we recall give
	\begin{equation}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{k\zeta} &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t+1/3} \\
	\kappa_{e,t+1/3} \\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	+	\frac{k^{O(1)} \bm{K}_{t+1/3}
	}{2^{k(1+\zeta)}}
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}

















From the analysis of marginal errors resulting from update C (\hyperlink{p:ctypes.varupdate.UPDATE.C.MGL}{Part~5b}), we have the bounds 
(7.115)
and (7.116),
which combine to give
	\begin{equation}
	\begin{pmatrix}
	\rho_{e\bullet,t+1}\\
	\kappa_{e\bullet,t+1}\\
	\dot{\kappa}_{e\bullet,t+1}
	\end{pmatrix}
	\le\begin{pmatrix}
	0\\
	\kappa_{e,t+2/3}\\
	\dot{\kappa}_{e,t+2/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t+2/3}
	+\bm{K}_{t+1/3}
	\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{equation}
Combining the above bounds gives, for all $t\ge1$,
	\begin{align*}
	\begin{pmatrix}
	\rho_{e\bullet,t}\\
	\kappa_{e\bullet,t}\\
	\dot{\kappa}_{e\bullet,t}
	\end{pmatrix}
	&\stackrel{
	(7.120)
	}{\le}
	\begin{pmatrix}
	0\\
	\kappa_{e,t-1/3}\\
	\dot{\kappa}_{e,t-1/3}\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\\
	&\stackrel{(7.119)}{\le}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	0 &0&0\\
	0&1& 2^{-k} \\
	0&1 &1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3} \\
	\kappa_{e,t-2/3} \\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{k^{O(1)}
	}{2^{k(1+\zeta)}}
	\bigg(
	\bm{\rho}_{t-1/3}
	+\bm{K}_{t-2/3}\bigg)
	\begin{pmatrix}1\\1\\1\end{pmatrix}\,.
	\end{align*}
Substituting these bounds 
(along with (7.119))
into (7.118) gives
	\begin{equation}
	\begin{pmatrix}
	\rho_{e,t+1/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\left\{
	\begin{pmatrix} 
	0&0&0\\
	0&1&0\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,t-2/3}\\
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\\1
	\end{pmatrix}
	\right\}\,,
	\end{equation}
where $\bm{\Upsilon}\equiv\bm{\rho}+\bm{K}$.
(In the $3\times3$ matrix on the right-hand side of (7.121), some entries are zero because we absorbed the errors into the $\bm{\Upsilon}_{t-2/3}$ term.)
Aggregating the last bound over $e\in\delta v$ gives
	\[
	\bm{\Upsilon}_{t+1/3}
	\equiv
	\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}
	\le \frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{\bm{\rho}_{t+1/3}+\bm{K}_{t+1/3}\Bigg\}
	= \frac{k^{O(1)}}{2^{k\zeta}}
	\bm{\Upsilon}_{t-2/3}\,,
	\]
for all $t\ge1$. This implies that the iterative procedure of \hyperlink{p:ctypes.varupdate.ITERATIVE.CONSTRUCTION}{Part~1} converges to the desired weights
$\Psi_v\equiv\Psi_{v,\infty}$. We now turn to proving
that the weights satisfy the bounds (7.27) and (7.62). 
Summing (7.121) over $t\ge1$ gives
	\begin{align*}
	S_{\ge1} &\equiv
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,t-2/3}\\
	\dot{\kappa}_{e,t-2/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{t-2/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\\
	&\le
	\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix}
	1&0\\1&1
	\end{pmatrix}
	\sum_{t\ge1}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+ \frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+ S_{\ge1}
	\Bigg\}\,,
	\end{align*}
and rearranging this inequality gives an upper bound on $S_{\ge1}$. It follows using
(7.121) again that
	\begin{align*}
	\sum_{t\ge1}\begin{pmatrix}
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	&\le
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\Bigg\{
	\begin{pmatrix} 
	1&0\\
	1&1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^k}
	\begin{pmatrix}1\\1\end{pmatrix}
	+S_{\ge1}
	\Bigg\}\\
	&\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	1 & 0 \\ 2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix}1\\1\end{pmatrix}
	\Bigg\}\,,
	\end{align*}
where the last step makes use of the upper bound on $S_{\ge1}$. We can also use 
(7.119)
and (7.121)
to bound the sum of $\rho_{e,t+2/3}$ over all $t\ge1$, so altogether we have
	\begin{equation}
	\sum_{t\ge1}\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	k^{O(1)}\Bigg\{
	\begin{pmatrix}
	0&0&0\\
	0&1&0\\
	0&2^{-k\zeta} & 1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	+\frac{\bm{\Upsilon}_{1/3}}{2^{k(1+\zeta)}}
		\begin{pmatrix} 1\\ 1\\1\end{pmatrix}
	\Bigg\}
	\end{equation}
We can then apply 
(7.97) and (7.98) with $t=0$ to obtain
	\[
	\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1&0&0\\
	1&1&0\\
	1&0&1
	\end{pmatrix}
	\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	+\frac{k^{O(1)}}{2^{k(1+\zeta)}}
	\Bigg\{
	 \textup{\textsf{err}}_v
	+\dot{\epsilon}_e
	+\frac{\min\{\ddot{\epsilon}_e,1\}}
		{2^{k(1+\zeta)}}
	\Bigg\}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
Finally, since we see from (7.79)
that $\nu_{e,-2/3}
\cong \hat{p}_e \phi_e u_{e,-2/3}$
while
$\nu_{e\bullet,0}
\cong \hat{q}_e \phi_e u_{e,-2/3}$, we conclude
that 
	\[\begin{pmatrix}
	\rho_{e\bullet,0}\\
	\kappa_{e\bullet,0}\\
	\dot{\kappa}_{e\bullet,0}
	\end{pmatrix}
	\le
	\underbrace{\begin{pmatrix}
	\rho_{e,-2/3}\\
	\kappa_{e,-2/3}\\
	\dot{\kappa}_{e,-2/3}
	\end{pmatrix}
	}_{\textup{zero}}
	+
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}\,,
	\]
where the first term on the right-hand side vanishes because $\nu_{e,-2/3}$ is fully judicious by the assumption. Combining the last two bounds gives
	\[\begin{pmatrix}
	\rho_{e,1/3}\\
	\kappa_{e,1/3}\\
	\dot{\kappa}_{e,1/3}
	\end{pmatrix}
	\le\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)} \textup{\textsf{err}}_v}
		{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\]
This implies $\bm{\Upsilon}_{1/3} \le O(\textup{\textsf{err}}_v)$. It follows by combining with
(7.122) that
	\begin{equation}
	\sum_{t\in\mathbb{Z},t\ge 0}
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}
	\le
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k}\\
	1 & 2^{-k} & 2^{-k}\\
	1 & 1 & 1
	\end{pmatrix}
		\begin{pmatrix}
	\epsilon_e \\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\begin{pmatrix}
	1 \\ 1\\ 2^k
	\end{pmatrix}\,.
	\end{equation}
We remark that 
(7.123)
implies that the quantities $\rho,\kappa,\dot{\kappa}$ satisfy the claimed bound 
(7.77).
The quantities $\alpha,\xi$ can be bounded in terms 
of $\rho,\kappa,\dot{\kappa}$, so it is straightforward to deduce that 
(7.77) indeed holds.
To conclude, it follows by recalling (7.69)
and (7.71)
that
	\[\Bigg|\frac{(\psi_{e,\infty})^j
		(\tau\,|\,\bm{L})}
		{(\phi_e)^j(
		\tau\,|\,\bm{L})}-1\Bigg|
	\le
	O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{(\psi_{e,t+1})^j
		(\tau\,|\,\bm{L})}
		{(\psi_{e,t})^j(
		\tau\,|\,\bm{L})}-1\Bigg|
		\Bigg)
	\le O\Bigg(
	\sum_{t\ge0}
	\kappa_{e,t+1/3}(\tau)
	\Bigg)\,.\]
It follows by recalling
(7.70)
and (7.73)
that
	\[\sum_{t\in\mathbb{Z},t\ge 0}
	\Bigg|
	\frac{\psi_{e,t+1}(\bm{L})}{\psi_{e,t}(\bm{L})}-1\Bigg|
	\le O(1)
	\sum_{t\ge0}
	\rho_{e,t+2/3}\,.
	\]
These quantities are bounded by (7.123), and 
this implies the claimed bound 
(7.62) for the clause-dependent weights. 
The errors in the clause-independent weights $\psi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})$ can be bounded by applying
Proposition~7.13 with input errors $\underline{\smash{\epsilon}}(t)$ for integers $t\ge0$, where
(recalling (7.87)) we have
	\begin{align}
	\underline{\smash{E}}
	&\equiv \sum_{t\in\mathbb{Z},t\ge0} \underline{\smash{\epsilon}}(t)
	=\sum_{t\in\mathbb{Z},t\ge0}
	\Bigg\{\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-2/3},
	\bar{q}_{t-1/3})
	+\widehat{\textup{\textsf{\footnotesize ERR}}}(\bar{q}_{t-1/3},
	\bar{q}_{t})
	\Bigg\}\\
	&\stackrel{(7.117)}{\le}
	\underline{\smash{\epsilon}}(0)
	+\frac{k^{O(1)}}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k} & 2^{-k} & 2^{-k}\\
	1 & 1 & 1\\
	2^{k\zeta} & 2^{-k} & 2^{k\zeta} 
	\end{pmatrix}
	\sum_{t\in\mathbb{Z},t\ge0} 
	\begin{pmatrix}
	\rho_{e,t+2/3}\\
	\kappa_{e,t+1/3}\\
	\dot{\kappa}_{e,t+1/3}
	\end{pmatrix}  \\
	&\stackrel{(7.123)}{\le}
	k^{O(1)}
	\begin{pmatrix}
	1 & 2^{-k} & 2^{-k} \\
	1 & 1 & 1 \\
	1 & 1 & 1 
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}
	+\frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}
	\begin{pmatrix}
	2^{-k}\\ 1 \\ 2^{k\zeta}
	\end{pmatrix}\,.

	\end{align}
It follows from this that 
	\begin{align*}
	E_e + \frac{\dot{E}_e}{2^k}
	+ \frac{\min\{\ddot{E}_e,1\}}{2^{k(1+\zeta)}}
	&\le k^{O(1)}
	\Bigg\{
	\epsilon_e + \frac{\dot{\epsilon}_e}{2^k}
	+ \frac{\min\{\ddot{\epsilon}_e,1\}}{2^{k(1+\zeta)}}
	 + \frac{\textup{\textsf{err}}_v}{2^{k(1+\zeta)}}
	\Bigg\}\,,\\
	\dot{E}_e
	+\frac{\min\{\ddot{E}_e,1\}}{2^{k\zeta}}
	&\le
	k^{O(1)}
	\Bigg\{
	\epsilon_e + \dot{\epsilon}_e
	+ \min\{\ddot{\epsilon}_e,1\}
	 + \frac{\textup{\textsf{err}}_v}{2^{k\zeta}}
	\Bigg\}\,.
	\end{align*}
Thus, if we apply the bound Proposition~7.13
with input errors $\underline{\smash{\epsilon}}(t)$ 
summed over all $t\ge0$, the final bound
will still be of the form (7.27), as claimed.\smallskip


\noindent\textbf{\textup{\hypertarget{p:ctypes.varupdate.OUTMSG}{Part~7}. Error bound for outgoing messages.}}
It remains to verify (7.63). This follows by a similar argument as in \hyperlink{c:var.update.BETTER.MGL.BOUND}{Step~2 of the proof of Corollary~7.14}. 
Fix an edge $e\in\delta v$, and define $\hat{s}_e = \hat{p}_e$ and $\hat{s}_e=\hat{q}_{e'}$ for $e'\in\delta v\setminus e$. We can apply the above result to obtain weights $\Theta_v$
such that $\nu_{\delta v}[\Theta_v;\hat{s}]$
is fully judicious. On the same edge $e$, the outgoing \textsc{bp} messages for the measures
$\nu_{\delta v}[\Phi_v;\hat{p}]$,
$\nu_{\delta v}[\Theta_v;\hat{s}]$, and 
$\nu_{\delta v}[\Psi_v;\hat{q}]$ are given by
	\begin{align*}
	\dot{p}_e(\sigma,\bm{L})
	&\cong \phi_e(\sigma,\bm{L}) u_p(\sigma)\\
	\dot{s}_e(\sigma,\bm{L})
	&\cong \theta_e(\sigma,\bm{L}) u_s(\sigma)\\
	\dot{q}_e(\sigma,\bm{L})
	&\cong \psi_e(\sigma,\bm{L}) u_q(\sigma)
	\end{align*}
where $u_p \equiv u_{e,-2/3}$, $u_q \equiv u_{e,\infty}$, and analogously
	\[
	u_s(\sigma_e)
	\cong \sum_{\smash{\underline{\smash{\sigma}}}_{\delta a \setminus e}}
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\theta_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta a \setminus e}\Bigg\{
	\sum_{\bm{L}}
	\theta_{e'}(\sigma_{e'},\bm{L}_{e'})
	\hat{s}_{e'}(\sigma_{e'},\bm{L}_{e'})
	\Bigg\}\,.
	\]
Conditional on $\bm{L}$, we use (7.10) to define the reweighted messages 
$P_e(\sigma\,|\,\bm{L})$,
$S_e(\sigma\,|\,\bm{L})$,
$Q_e(\sigma\,|\,\bm{L})$.
Recall (7.88), and note that
	\[
	\underline{\smash{D}} 
	\equiv
	\dddot{\textup{\textsf{\footnotesize ERR}}}(u_p,u_q)
	\le O\Bigg(
	\sum_{t\in\mathbb{Z},t\ge0}
	\dddot{\textup{\textsf{\footnotesize ERR}}}
	(u_{e,t-2/3},u_{e,t+1/3})
	\Bigg)
	=O\Bigg( 
	\sum_{t\in\mathbb{Z},t\ge0}
	\underline{\smash{\delta}}(t+1/3)\Bigg)\,.\]
Let $\underline{\smash{D}}'$ denote the first three entries of $\underline{\smash{D}}$. Then 
	\begin{align*}
	\underline{\smash{D}}'
	&
	\stackrel{(7.89)}{\le}
	k^{O(1)}
	\sum_{t\in\mathbb{Z},t\ge0}
	\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v(t)
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e(t)\\
	\dot{\epsilon}_e(t)\\
	\min\{\ddot{\epsilon}_e(t),1\}/2^{k\zeta}
	\end{pmatrix}
	\right\} \\
	&\stackrel{(7.124)}{\le} k^{O(1)}\left\{
	\begin{pmatrix}
	1\\1\\1
	\end{pmatrix} \textup{\textsf{err}}_v
	+ 
	\begin{pmatrix}
	0&0&0\\
	0&1&1\\
	0&1&1
	\end{pmatrix}
	\begin{pmatrix}
	\epsilon_e\\
	\dot{\epsilon}_e\\
	\min\{\ddot{\epsilon}_e,1\}/2^{k\zeta}
	\end{pmatrix}\right\}
	\end{align*}
Meanwhile, the errors between the edge weights
$\phi_e(\sigma,\bm{L})$,
$\theta_e(\sigma,\bm{L})$, and $\psi_e(\sigma,\bm{L})$ are bounded by (7.62).
From this it is easy to see that
	\[
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{\dot{s}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|+ 
	\Bigg|
	\frac{\dot{q}_e(\bm{L})}{\dot{p}_e(\bm{L})}-1
	\Bigg|
	+\Bigg\|
	\frac{S_e(\cdot\,|\,\bm{L})}{P_e(\cdot\,|\,\bm{L})}-1
	\Bigg\|_\infty
	\Bigg\}
	\le
	k^{O(1)}
	\textup{\textsf{err}}_v\,.
	\]
Combining with the result of 
Lemma~7.18 gives
(cf.\ (7.43))
	\[
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(S_e)^j(\tau\,|\,\bm{L})}
		{(P_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	\le \frac{k^{O(1)}\textup{\textsf{err}}_v}{2^{k\zeta}}\,.
	\]
The error between $S_e$ and $Q_e$ is bounded by
(cf.\ (7.44) and (7.45))
	\begin{align*}
	\max_{\bm{L}}\Bigg\{
	\Bigg|
	\frac{Q_e(\sigma\,|\,\bm{L})}{S_e(\sigma\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le 
	k^{O(1)} \Bigg(
	\textup{\textsf{err}}_v
	+\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\sigma]\ge1\}
	\bigg(
	\dot{\epsilon}_e+
	\frac{\min\{\ddot{\epsilon}_e,1\}}{2^{k\zeta}}
	\bigg)\Bigg\} \\
	\max_{\bm{L}}\Bigg\{\Bigg|
	\frac{(Q_e)^j(\tau\,|\,\bm{L})}
		{(S_e)^j(\tau\,|\,\bm{L})}-1
	\Bigg|\Bigg\}
	&\le k^{O(1)}\Bigg( 
	\epsilon_e 
	+\frac1{(2^k)^{\mathbf{1}\{\tau\ne\textup{\texttt{\footnotesize r}}\}}}
	\bigg\{ \dot{\epsilon}_e
	+ \frac{\min\{\ddot{\epsilon}_e,1\}}{2^{k\zeta}}
	\bigg\}\Bigg)\,.
	\end{align*}
Combining these bounds gives the claim (7.63).
\end{proof}

Let $\epsilon_2$ be a small absolute constant. Fix $x\in\{\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize -}}\}$, and let $v$ be a variable of type $\bm{T}$. Suppose we are given $\omega\in\bm{I}_0$ with marginal $\pi$ such that for both $i=1,2$ we have 
	\begin{equation}
	\gamma^i\equiv
	\sum_{e\in\delta v(x)}
	\pi_e\Big(\sigma^i=\textup{\texttt{\footnotesize r}}
		\,\Big|\,\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2
		\Big)
	\ge k\epsilon_2\,,\end{equation}
where $\pi_e\equiv\pi_{\bm{t}}$ for an edge $e$ of type $\bm{t}$. Let $\Omega$ be the maximizer of (9.41) that is consistent with $\omega$, and let $\bm{\varpi}_{\bm{L},j}$ be the resulting joint distribution of $(\sigma,\upsilon)$. Then there exists an absolute constant $\epsilon_3$
(depending only on $\epsilon_2$) such that for every edge $e\in\delta v(x)$ we have
	\[\left.
	\begin{array}{r}
	\bm{\varpi}_{\bm{L},j}( 
		\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}} \,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})\\
	\bm{\varpi}_{\bm{L},j}( \upsilon^1=\textup{\texttt{\footnotesize v}}
		\,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}} )\\
	\bm{\varpi}_{\bm{L},j}(
		\upsilon^2=\textup{\texttt{\footnotesize v}} \,|\,\sigma=\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}} )\\
	\end{array} \hspace{-4pt}
	\right\}
	\ge 1-\frac1{2^{k\epsilon_3}}
	\]
for $j=j(\bm{t})$ and all clause types $\bm{L}$ such that 
$\bm{L}(j)=\bm{t}$.

\begin{proof} Throughout the proof, $\epsilon_3$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant that depends only on $\epsilon_2$.\smallskip

\noindent\textbf{\textup{Step 1. Reduction to entropy maximization for a conditional measure.}}
Note from (9.41) that if we fix
$\Omega_{\bm{t}}$, then we obtain separate entropy maximization problems over $\Omega_{\bm{T}}$ and $\Omega_{\bm{L}}$. Let us therefore fix $\Omega_{\bm{t}}=(\textup{\textsf{aug}}_{\mathscr{D}}(\omega))_{\bm{t}}$, and consider the optimization over $\Omega_{\bm{T}}$. Let $v$ denote a variable of type $\bm{T}$, and write $\Omega_v\equiv\Omega_{\bm{T}}$.
By the method of Lagrange multipliers, the optimal $\Omega_v$ must take the form
	\[
	\Omega_v\Big( (\smash{\underline{\smash{\sigma}}},\bm{L})_{\delta v}\Big)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}} 
		\prod_{e\in\delta v}
		\hat{q}_e(\sigma_e,\bm{L}_e)\,,\]
where each $\hat{q}_e$ is a probability measure over elements $(\sigma,\bm{L})$, chosen such that $\Omega_v$ has marginals $\Omega_e\equiv\Omega_{\bm{t}}$ for $e\in\delta v$ and $\bm{t}\equiv\bm{t}_e$. The marginal of $\Omega_v$ on $(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)$ is
	\[
	\Omega_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}}
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'})\,,
	\]
where $\bar{q}_{e'}$ denotes the marginal of $\hat{q}_{e'}$ on $\sigma_{e'}$ alone. It follows that
	\begin{equation}
	\Omega_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\bigg|\, (\sigma_e,\bm{L}_e)\bigg)
	= \dot{\nu}_{\bm{T}}
		\Big(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\Big|\,\sigma_e\Big)
	\cong 
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'}).
	\end{equation}
Thus, for the purposes of this lemma, it suffices to estimate only $\dot{\nu}_{\bm{T}}(\cdot\,|\,\sigma_e)$. To this end, assume without loss $x=\textup{\texttt{\footnotesize +}}$, and consider the event $x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$. In this case 
$\sigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ for all $e\in\delta v(\textup{\texttt{\footnotesize +}})$, and
$\sigma_e=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}$ for all $e\in\delta v(\textup{\texttt{\footnotesize -}})$. Let
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}})
	\equiv
	\dot{\nu}_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v(\textup{\texttt{\footnotesize +}})}=\smash{\underline{\smash{\sigma}}}
		\,\bigg|\,x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\bigg)\,.\end{equation}
Denote $D \equiv |\delta v(\textup{\texttt{\footnotesize +}})|$.
Then $\mu$ is a probability measure over colorings $\smash{\underline{\smash{\sigma}}}\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^{2D}$ with at least one $\textup{\texttt{\footnotesize red}}$ spin in each copy $i=1,2$. Moreover, $\mu$ must maximize entropy subject to its marginals 
$\mu_\ell$. It 
follows by the method of Lagrange multipliers that there exist probability measures $h_\ell$
over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ such that
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}})
	\cong
	\Bigg\{
	\prod_{i=1,2}\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\smash{\underline{\smash{\sigma}}}^i]\ge1\}\Bigg\}
	\Bigg\{
	\prod_{\ell=1}^D h_\ell(\sigma_\ell)
	\Bigg\}\,.
	\end{equation}
We now turn to the construction and estimation of the $h_\ell$.\smallskip

\noindent\textbf{\textup{Step 2. Construction of Lagrangian weights.}} As usual, we will construct $h_{\ell,t}\to h_\ell$ in the limit $t\to\infty$. We initialize the construction with $h_{\ell,0}\equiv\mu_\ell$. Let $\mu_t$
be defined by (9.46) with $h_{\ell,t}$ in place of $h_\ell$, and let $\mu_{\ell,t}$ denote the marginal of $\mu_t$ on the $\ell$-th edge in $\delta v(\textup{\texttt{\footnotesize +}})$. Similarly
to (9.10) we have
	\begin{equation}
	\mu_{\ell,t}(\sigma)
	\cong
	h_{\ell,t}(\sigma) \overbrace{
	\sum_{\smash{\underline{\smash{\sigma}}}_{-\ell}}
	\Bigg\{
	\prod_{i=1,2}\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\smash{\underline{\smash{\sigma}}}^i]\ge1\}\Bigg\}
	\prod_{\ell'\ne\ell}
	h_{\ell',t}(\sigma_{\ell'})
	}^{\textup{denote this }\xi_{\ell,t}(\sigma)}\,.
	\end{equation}
For the remainder of the proof, we assume without loss that $\ell=1$. Then at $t=0$ we have
	\begin{equation}
	0\le 1-\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	= \prod_{\ell=2}^D \bigg\{
		1- \mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
		\bigg\}
	\le \exp\Bigg\{ - \sum_{\ell=2}^D
		\mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Bigg\}
	\stackrel{(9.45)}{\le}
		\frac{e}{\exp(\gamma^2)}
	\stackrel{(9.43)}
		{\le} \frac1{2^{k\epsilon_3}}\,.
	\end{equation}
By similar calculations, $0\le 1-\xi_{1,0}(\sigma) \le 2^{-k\epsilon_3}$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$. (In fact $\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})=1$.) Given $h_{\ell,t}$ we define $h_{\ell,t+1}$ to be the probability measure such that
	\begin{equation}
	h_{\ell,t+1}(\sigma)
	\cong \frac{\mu_\ell(\sigma)}{\xi_{\ell,t}(\sigma)}
	\stackrel{(9.47)}{\cong}
		h_{\ell,t}(\sigma)
		\frac{\mu_\ell(\sigma)}{\mu_{\ell,t}(\sigma)}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$.\smallskip

\noindent\textbf{\textup{Step 3. Estimation of Lagrangian weights.}} Suppose inductively that
	\begin{equation}
	\bigg\|\frac{\mu_{\ell,t}}{\mu_\ell}-1 \bigg\|_\infty
	\le \frac1{2^{k\epsilon_3(t+1)/3}}\end{equation}
for all $1\le\ell\le D$, where the base case $t=0$ follows from the above bounds (see (9.48)) on $\xi_{\ell,0}$. 
If we assume (9.50) holds up to $t$, then taking a telescoping sum gives
	\begin{align}
	&\Big|\xi_{1,t+1}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	-\xi_{1,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})\Big|
	= \Bigg| \prod_{j=2}^D
		\Big\{1-h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Big\}
	-\prod_{j=2}^D
		\Big\{ 1-h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Big\}
	\Bigg| \\ 
	&\qquad\le \sum_{\ell=2}^D
	h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1\Bigg|
	\prod_{j=2}^{\ell-1}
	\bigg\{1-h_{j,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}
	\prod_{j=\ell+1}^D
	\bigg\{1-h_{j,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}\\ 
	&\qquad\le O(1)\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1
	\bigg|\Bigg\}\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg\}\Bigg/
	\exp\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg\} \\
	&\qquad\stackrel{(9.50)}{\le}
	O\Bigg( \frac{\gamma^2}{\exp(\gamma^2)}\Bigg)
	\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1
	\bigg|\Bigg\}
	\stackrel{(9.49)}{=}
	O\bigg( \frac{\gamma^2}{\exp(\gamma^2)}\bigg)
	\max_{1\le\ell\le D}
	\bigg| \frac{\mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}{\mu_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})} -1
	\bigg|
	\stackrel{(9.50)}{\le}
	\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\,.

	\end{align}
A similar estimate holds for
$\xi_{1,t+1}(\sigma)-\xi_{1,t}(\sigma)$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$.
Next note that if we let $\tilde{\mu}_{t+1}$ be defined by
(9.46) with weights 
$h_{1,t+1}$ and $h_{\ell,t}$ for $\ell\ge2$, then
the marginal on the first edge is, similarly to (9.47),
	\[
	\tilde{\mu}_{1,t+1}(\sigma)
	\cong h_{1,t+1}(\sigma)
		\xi_{1,t}(\sigma)
	\stackrel{(9.49)}{\cong}
	\frac{\mu_1(\sigma)}{\xi_{1,t}(\sigma)}
		\xi_{1,t}(\sigma)
	=\mu_1(\sigma)\,.
	\]
It follows from this that 
	\begin{align*}
	\bigg\|\frac{\mu_{1,t+1}}{\mu_1}
		-1 \bigg\|_\infty
	&=\bigg\|
		\frac{\mu_{1,t+1}}{\tilde{\mu}_{1,t+1}}
		-1 \bigg\|_\infty
	\stackrel{(9.49)}{=} \bigg\|
		\frac{\xi_{1,t+1}}{\xi_{1,t}}
		-1 \bigg\|_\infty
	\stackrel{(9.51)}{\le}
	O\bigg(\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\bigg)
	\le \frac1{2^{k\epsilon_3(t+2)/3}}\,,
	\end{align*}
which verifies the induction. We then take $t\to\infty$ to obtain the limiting weights $h_\ell\equiv h_{\ell,\infty}$ that define the optimal measure $\mu$ by (9.46). Suppose $e$ corresponds to the first edge in $\delta v(\textup{\texttt{\footnotesize +}})$. Then, for all $\sigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$,
	\[
	\dot{\nu}_{\bm{T}}\bigg(
	\sum_{e'\in\delta v(\textup{\texttt{\footnotesize +}})\setminus e}
	\mathbf{1}\{ (\sigma_{e'})^2=\textup{\texttt{\footnotesize r}}\} =0
	\,\bigg|\,\sigma_e
	\bigg)
	\stackrel{(9.45)}{=}
	\mu\bigg(
	\smash{\underline{\smash{\sigma}}}_{-1}\in\{\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize b}}\}^D \,\bigg|\,\sigma_1
	\bigg)
	\stackrel{(9.50)}{\le}
	O\Bigg(
	\prod_{\ell=2}^D
		\bigg\{ 1-h_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}
		\Bigg) \le \frac1{2^{k\epsilon_3}}\,.
	\]
The lemma follows by recalling (9.44).
\end{proof}

In this lemma we take $\sigma$ in the reduced alphabet $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. We continue to take $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$. We write $\sigma\sim\varsigma$ to indicate compatibility: if $\sigma^i=\textup{\texttt{\footnotesize r}}$ then $\varsigma^i=\textup{\texttt{\footnotesize r}}$; if $\sigma^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ then $\varsigma^i\in\{\sigma^i,\textup{\texttt{\footnotesize w}}\}$. On edge $e$ let $\mu_0$ be a probability measure on pairs $(\sigma,\varsigma)$ with $\sigma\sim\varsigma$, of the form
	\[
	\mu_0(\sigma,\varsigma)
	=\frac{\mathbf{1}\{\sigma\sim\varsigma\}}{z_0}
	\dot{q}(\sigma) 
	(b_0)^1(\sigma^1)(b_0)^2(\sigma^2)
	x_0(\varsigma)\,,
	\]
such that $\mu(\sigma^i=\tau)={}_\star\hspace{-1pt}\pi_e(\tau)$ for both $i=1,2$ and all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. Assume that ${}_\star\hspace{-1pt}\pi_e$ is nice in the sense of Definition~3.8, that $\dot{q}(\sigma)=\Theta(1)$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, and that
$b^i(\tau)=\Theta(1)$ for $i=1,2$ and all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$. Let $\zeta_0$ denote the marginal law of $\varsigma$ under $\mu_0$. Let $\zeta$ be another probability measure over $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$ whose single-copy marginals satisfy
$\zeta^1(\textup{\texttt{\footnotesize r}})={}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})=\zeta^2(\textup{\texttt{\footnotesize r}})$.
Assume that 
	\begin{align}
	\max\bigg\{ 1-\zeta_0(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}),
	1-\zeta(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})\bigg\}
	&\le \frac{k^{O(1)}}{2^k}\,,\\
	\hat{\iota} \equiv
	\frac{k^4}{4^k} + \max\bigg\{
	\zeta_0(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2),
	\zeta(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2)
	\bigg\}
	&\le \frac1{2^{k(1+\epsilon)}}\,.

	\end{align}
Assume moreover that we have parameters
$\delta \le O(1)$ and $\ddot{\delta}\le 2^{k(1-\epsilon)}$ such that
	\begin{align}

	\max
	\Bigg\{
	\Big|\zeta(\varsigma)-\zeta_0(\varsigma)\Big|
	: \varsigma\in\{
	\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}},
	\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}}\}
	\Bigg\}
	&\le \frac{k^{O(1)}\delta}{2^k}\,,\\

	\max
	\Bigg\{
	\Big|\zeta(\varsigma)-\zeta_0(\varsigma)\Big|
	: \varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2
	\Bigg\}
	&\le \hat{\iota} \delta\,, \\

	\bigg|
		\frac{\zeta(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
		{\zeta_0(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}-1\bigg|
	&\le\ddot{\delta}\,.
	\end{align}
Then there exist weights $(b_{3/4})^1$, $(b_{3/4})^2$, $x_{3/4}$ such that under the corresponding measure $\mu_{3/4}$ (see (9.99)) the spin $\varsigma$ has marginal $\zeta_{3/4}=\zeta$. Moreover, if we let $\hat{z}_t$ be the normalizing constant such that
	\[
	\hat{q}_t(\sigma)
	= \frac1{\hat{z}_t}
	(b_t)^1(\sigma^1)(b_t)^2(\sigma^2)
	\sum_{\varsigma:\varsigma\sim\sigma}
	x_t(\varsigma)
	\]
is a probability measure,
then the new weights can be chosen such that the error between $\hat{q}_0$ and $\hat{q}_{3/4}$ is very small:
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\hat{q}_0,\hat{q}_{3/4})
	\le k^{O(1)} \begin{pmatrix}
	\hat{\iota} & 0 \\ 2^k\hat{\iota} &0 \\ 1& 1
	\end{pmatrix}
	\begin{pmatrix}
	\delta \\ \ddot{\delta}
	\end{pmatrix}\,,\]
using the notation of 
Definition~7.5.


\begin{proof} We begin with some easy observations.
By the assumption that $\dot{q}=\Theta(1)$ 
and $b^i=\Theta(1)$, we have
	\[
	\mu_0(\sigma,\varsigma)
	=
	\frac{\mathbf{1}\{\sigma\sim\varsigma\} }{z_0}
	\Theta(1)
	x(\varsigma)\,.
	\]
It then follows from (9.93)
and (9.94) that
$x(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})/z_0\ge 1-k^{O(1)}/2^k$, while
	\begin{align*}
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2
		\setminus\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}
	\Bigg\}
	&\le
	\frac{k^{O(1)}}{2^k}\,,\\
	\max\Bigg\{
	\frac{x(\varsigma)}{z_0}
	: \varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2
	\Bigg\} 
	\le O(\hat{\iota})
	&\le \frac{O(1)}{2^{k(1+\epsilon)}}\,.
	\end{align*}
This implies that $\mu_0(\sigma)=\Theta(1)$ for all $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, since in this case
	\[
	\mu_0(\sigma)
	=\frac1{z_0}\bigg\{ \Theta(1) 
	x(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}) + \frac{k^{O(1)}}{2^k}\bigg\}
	=\Theta(1)\,.
	\]
Next, by the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice and $\mu_0$ is judicious, we have
	\[
	\frac{\Theta(1)}{2^k}
	= {}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})
	= \mu_0(\sigma^1=\textup{\texttt{\footnotesize r}})
	= \frac{\Theta(1)}{z_0}
	\sum_{\vartheta\in \{\textup{\texttt{\footnotesize r}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}}
	x(\vartheta)
	= \frac{\Theta(1)x(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})}{z_0}
	+ \frac{O(1)}{2^{k(1+\epsilon)}}\,,
	\]
which shows that $x(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})=\Theta(2^{-k})$. It follows from this that 
	\[
	\mu_0(\sigma=\vartheta)
	= \frac{\Theta(1)}{2^k}
	\quad\textup{for all }
	\vartheta\in\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}},
		\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize r}}\}\,.
	\]
Lastly, we note that (9.94) directly implies
$\mu_0(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
=\zeta_0(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}) \le 2^{-k(1+\epsilon)}$. In summary we have seen that the assumptions of the lemma imply
	\begin{equation}
	\mu_0(\sigma=\vartheta)
	= \begin{cases}
	\Theta(1) & \textup{if $\textup{\texttt{\footnotesize r}}[\vartheta]=0$,}\\
	\Theta(2^{-k}) & \textup{if $\textup{\texttt{\footnotesize r}}[\vartheta]=1$,}\\
	O(2^{-k(1+\epsilon)})
	& \textup{if $\textup{\texttt{\footnotesize r}}[\vartheta]=2$,}
	\end{cases}\end{equation}
for $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$.\smallskip


\noindent\textbf{\textup{Part 1. Description of update procedure.}} We will define a sequence of weights $(b_t)^i$, $x_t$ ending with the desired weights at $t= 3/4$. For each $t$ denote the corresponding measure
	\begin{equation}
	\mu_t(\sigma,\varsigma)
	=\frac{\mathbf{1}\{\sigma\sim\varsigma\}}{z_t}
	\dot{q}(\sigma) 
	(b_t)^1(\sigma^1)(b_t)^2(\sigma^2)
	x_t(\varsigma)\,,\end{equation}
with $z_t$ the normalizing constant. 
Let $\zeta_t$ denote the marginal law of $\varsigma$ under $\mu_t$.
\begin{enumerate}[(a)]
\item 
\textit{Time $t=0$ to $t=1/4$.} First adjust the weight on $\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}$: set
	\begin{align}

	\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}
	&= \frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	\,,\\
	\frac{x_{1/4}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}{x_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	&= \frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})
	-\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
		{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	\frac{\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}{\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}\,.

	\end{align}
We call (9.100) and (9.101) the \textbf{\textup{$\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}$-update}}. At the same time also make the updates
(9.100)
and (9.101)
with $\textup{\texttt{\footnotesize c}}$ in place of $\textup{\texttt{\footnotesize y}}$,
to define new weights
$(b_{1/4})^1(\textup{\texttt{\footnotesize c}})$ and $x_{1/4}(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}})$
--- we call this the \textbf{\textup{$\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}$-update}}.
Keep all the other weights unchanged, that is,
$(b_{1/4})^1(\textup{\texttt{\footnotesize r}})=(b_0)^1(\textup{\texttt{\footnotesize r}})$,
$(b_{1/4})^2(\tau)=(b_0)^1(\tau)$ for all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$, and $x_{1/4}(\varsigma)=x_0(\varsigma)$ for all $\varsigma \notin\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}\}$.



\item 
Time $t=1/4$ to $t=1/2$. Perform the analogous update in the second copy: for the \textbf{\textup{$\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}$-update}}, set
	\begin{align*}
	\frac{(b_{1/2})^2(\textup{\texttt{\footnotesize y}})}{(b_{1/4})^2(\textup{\texttt{\footnotesize y}})}
	&= \frac{\mu_{1/4}(\sigma^2=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
	{\mu_{1/4}(\sigma^2=\textup{\texttt{\footnotesize y}})
	-\mu_{1/4}(\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
	\,,\\
	\frac{x_{1/2}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}{x_{1/4}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
	&= \frac{\mu_{1/4}(\sigma^2=\textup{\texttt{\footnotesize y}})
	-\mu_{1/4}(\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
		{\mu_{1/4}(\sigma^2=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
	\frac{\zeta(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}
	{\mu_{1/4}(\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}})}\,.
	\end{align*}
Likewise make the \textbf{\textup{$\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}}$-update}}, to define new weights $(b_{1/2})^2(\textup{\texttt{\footnotesize c}})$ and $x_{1/2}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}})$. Again, keep all the other weights unchanged.

\item  Time $t=1/2$ to $t=3/4$. Finally, for all $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$, update
	\[
	\frac{x_{3/4}(\varsigma)}{x_{1/2}(\varsigma)}
	= \frac{\zeta(\varsigma)}{\zeta_{1/2}(\varsigma)}\,.
	\]
Leave the $b$-weights unchanged, that is,
$(b_{3/4})^i(\tau)=(b_{1/2})^i(\tau)$
for $i=1,2$ and all $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$.
\end{enumerate}
We begin with a simple observation about the first update, from $t=0$ to $t=1/4$. At time $t=0$, the non-normalized weight on the event $\{\sigma^1=\textup{\texttt{\footnotesize y}}\}$ is given by $z_0\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})$. At time $t=1/4$, the non-normalized weight on the same event is
	\begin{align}
	z_{1/4}\mu_{1/4}(\sigma^1=\textup{\texttt{\footnotesize y}})
	&= z_0\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}
	\Bigg(
	\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}},\varsigma\ne\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	+\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\frac{x_{1/4}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}{x_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	\Bigg)
	\\
	&= 
	z_0 \Bigg\{
	\Big(\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})\Big)
	+ \zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	 \Bigg\}
	= z_0 \mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})\,,

	\end{align}
and likewise
$z_{1/4}\mu_{1/4}(\sigma^1=\textup{\texttt{\footnotesize c}})=
z_0 \mu_0(\sigma^1=\textup{\texttt{\footnotesize c}})$. The weight of the event $\{\sigma^1=\textup{\texttt{\footnotesize r}}\}$ remains unchanged, so altogether we have $z_{1/4}=z_0$. For the same reason $z_{1/2}=z_{1/4}$. We now turn to analyzing the effect of these updates on the $\sigma$-marginal.\smallskip

\noindent\textbf{\textup{Part~2. Effect of update (i:ZETA.update.yw) on $\sigma$-marginal.}}
The first change in the $b$-weights can be bounded as
	\begin{align}
	\bigg|\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}-1\bigg|
	&\stackrel{(9.100)}{=}
	\bigg|\frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}-1\bigg|
	\stackrel{(9.95)}{=}
	\bigg|\frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
		- k^{O(1)} \delta/2^k}-1\bigg|\\
	&\stackrel{(9.93)}{=}
	\bigg|\frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})
		- k^{O(1)}\delta/2^k}
	{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})
		- k^{O(1)} \delta/2^k}-1\bigg|
	\le \frac{k^{O(1)} \delta}{2^k}

	\end{align}
--- the last estimate above uses the assumption that ${}_\star\hspace{-1pt}\pi_e$ is nice, which implies that ${}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})=\Theta(1)$.
Now, note it follows from (9.102) that it does not make a difference if the $\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}$-update and $\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}$-update are done simultaneously or in sequence. Suppose for this part of the proof that we make only the $\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}$-update (i.e., only (9.100) and (9.101)), without making the $\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}$-update. Let $\mu_{1/8}$ denote the measure that results, and define the signed measure $\Gamma\equiv\Gamma_{1/8}\equiv\mu_{1/8}-\mu_0$; we now proceed to bound $\Gamma$. The event $\{\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}\}$ is affected by both the $b$- and $x$-updates: 
	\begin{align}
	\Big|\Gamma(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})\Big|
	&\equiv\Big|\zeta_{1/8}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
		-\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})\Big|
	=\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\Bigg| 
	\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}
	\frac{x_{1/4}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}{x_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}-1\Bigg|
	\stackrel{(9.101)}{=}
	\Bigg| \zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}
	-\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})\Bigg|
	\\ 
	&\stackrel{(9.101)}{=}
	\bigg|
	\frac{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})
	-\mu_0(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
		{\mu_0(\sigma^1=\textup{\texttt{\footnotesize y}})-\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})}
	\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	-\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\bigg|\stackrel{(9.103)}{=}
	\bigg|
	\bigg(1 + \frac{k^{O(1)}\delta}{2^k}
	 \bigg) \zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})-\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\bigg|\\
	&\stackrel{(9.93)}{=} \bigg|
	\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})-\zeta_0(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	+ \frac{k^{O(1)}\delta}{4^k}
	\bigg|
	\stackrel{(9.95)}{\le }
	\frac{k^{O(1)}\delta}{2^k}\,.

	\end{align}
Next let us consider events that are only affected by the $b$-update: using (9.103) gives
	\begin{align*}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\\
	\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\\
	\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}-1 
	\Bigg|
	\stackrel{(9.94)}{\le} 
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k} \,,\\
	\Bigg|\Gamma
	\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\\
	\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}
	\end{array}\hspace{-3pt}\Bigg)\Bigg|
	&=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\\
	\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}
	\end{array}\hspace{-3pt}\Bigg)\cdot
	\Bigg|
	\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}-1\Bigg|
	\stackrel{(9.93)}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{align*}
Similarly, for any $\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ we have,
again using (9.103), that
	\begin{equation}
	\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\mu_0\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	\cdot\Bigg|
		\frac{(b_{1/4})^1(\textup{\texttt{\footnotesize y}})}{(b_0)^1(\textup{\texttt{\footnotesize y}})}-1
		\Bigg|
	\stackrel{(9.93)}{\le} 
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
As a consequence, for any $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2\setminus\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$ we have
	\begin{equation}
	\Big|\Gamma(\varsigma=\vartheta)
\Big|
	=\Bigg| \Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)
	+\overbrace{\Gamma
		\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\textup{\texttt{\footnotesize y}},\\
		\varsigma=\vartheta
		\end{array}\hspace{-3pt}\Bigg)}^\textup{zero}
		\Bigg|
	\stackrel{(9.105)}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.
	\end{equation}
Similarly we also have the bound
	\begin{equation}
	\Bigg|
	\Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma\in\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}\}
		\end{array}\hspace{-3pt}\Bigg)\Bigg|
	=\Bigg| \overbrace{
	\Gamma(\sigma^1=\textup{\texttt{\footnotesize y}})
	}^\textup{zero by
		(9.102)}
	{} - \Gamma\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma
		\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\}
		\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
		\end{array}\hspace{-3pt}\Bigg)
	\Bigg|
	\stackrel{(9.105)}{\le}
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next we note that under both $\mu_0$ and $\mu_{1/4}$, the conditional probability of $\sigma^2$ given $\sigma^1=\textup{\texttt{\footnotesize y}}$ and $\varsigma$ is given by
	\[
	\mu_t\Bigg(\sigma^2=\textup{\texttt{\footnotesize y}}\,\Bigg|\,
		\hspace{-3pt}\begin{array}{c}\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma=\vartheta\end{array}\hspace{-3pt}\Bigg)
	=\begin{cases}
	1 & \textup{if $\vartheta\in
		\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}\}$,}\\
	\displaystyle\frac{\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})(b_0)^2(\textup{\texttt{\footnotesize y}})}
		{\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})(b_0)^2(\textup{\texttt{\footnotesize y}})
			+\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})(b_0)^2(\textup{\texttt{\footnotesize c}})}
	\le O(1)
	&\textup{if $\vartheta\in
		\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$,}
	\end{cases}
	\]
for both $t=0$ and $t=1/4$. It follows that
	\[
	\Big|\Gamma(\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Big|
	=\Bigg|
	\underbrace{\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\varsigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}\}\end{array}\hspace{-3pt}\Bigg)
		}_{\textup{bounded by (9.105)}}
		\cdot1
		+
	\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
	\sigma^1=\textup{\texttt{\footnotesize y}},\\
	\varsigma\in\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}\}
	\end{array}\hspace{-3pt}\Bigg)
	}_{\textup{bounded by (9.107)}}
	\cdot O(1)
		\Bigg|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\]
Similar arguments (details omitted) can be used to bound $\Gamma(\sigma=\vartheta)$ for all $\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, so altogether we have
	\begin{equation}
	\max\Bigg\{
	\Big| \Gamma(\sigma=\vartheta)\Big|
	:\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2
	\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Lastly we note that $\Gamma(\sigma^1=\textup{\texttt{\footnotesize r}})=0$, while
	\begin{equation}
	\Big|\Gamma(\sigma^2=\textup{\texttt{\footnotesize r}})\Big|
	=\Bigg|\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1=\textup{\texttt{\footnotesize y}},\\
		\sigma^2=\textup{\texttt{\footnotesize r}}\end{array}\hspace{-3pt}
		\Bigg)
	+\underbrace{
	\Gamma\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma^1\ne\textup{\texttt{\footnotesize y}},\\
		\sigma^2=\textup{\texttt{\footnotesize r}}\end{array}\hspace{-3pt}
		\Bigg)
	}_\textup{zero}
	\Bigg|
	\stackrel{(9.106)}{\le}
	\frac{k^{O(1)} \delta}{4^k}\,.\end{equation}
This concludes our analysis of the effect of 
(9.100) and (9.101) alone on the $\sigma$-marginal.\smallskip

\noindent\textbf{\textup{Part 3. Effect of updates (i:ZETA.update.yw) and (i:ZETA.update.wy) on $\sigma$-marginal.}} Recall that $\mu_{1/2}$ is the measure that results after completing updates (i:ZETA.update.yw) and (i:ZETA.update.wy), and denote the signed measure $\Delta\equiv\mu_{1/2}-\mu_0$. Recall that (9.108) bounds $|(\mu_{1/8}-\mu_0)(\sigma=\vartheta)|$ for all $\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, where from time $t=0$ to time $t=1/8$ we perform only the $\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}$-update.
From time $t=1/8$ to time $t=1/2$ we perform analogously the $\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}$-, $\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}$-, and $\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}}$-updates, for which the analogous estimate holds. Therefore
	\[\max\Bigg\{\Big|\Delta(\sigma=\vartheta)\Big|
	:\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\Bigg\}
	\le \frac{k^{O(1)}\delta}{4^k}\,.\]
On the other hand, the $\{\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$ event is completely unaffected by updates
(i:ZETA.update.yw) and (i:ZETA.update.wy),
so $\Delta(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})=0$. It remains to 
estimate $\Delta(\sigma=\vartheta)$ for $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ with $\textup{\texttt{\footnotesize r}}[\vartheta]=1$. To this end we note that for any $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, the event $\{\varsigma=\vartheta\}$ is affected only by the $b$-updates, so
	\begin{equation}
	\Delta(\varsigma=\vartheta)
	\stackrel{(9.103)}{=}
	\frac{k^{O(1)}\delta}{2^k}
	\zeta_0(\vartheta)
	\stackrel{(9.94)}{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	\stackrel{(9.94)}{\le}
	\frac{k^{O(1)} \delta}{2^{k(2+\epsilon)}}
	\,.\end{equation}
By combining (9.110) with (9.109) we obtain 
	\begin{equation}
	\Big| \Delta(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})\Big|
	=\bigg|
	\Delta(\sigma^1=\textup{\texttt{\footnotesize r}})
	-\Delta(\varsigma\in
		\{\textup{\texttt{\footnotesize r}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\})
	\bigg|
	\le \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{(9.94)}{\le} 
	\frac{k^{O(1)}\delta}{4^k} 
	\,.\end{equation}
The probability of $\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}$
conditional on $\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}$ is given by
	\begin{equation}
	\mu_{1/2}\Big(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}
		\,\Big|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\Big)
	=\frac{\dot{q}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}) (b_{1/2})^2(\textup{\texttt{\footnotesize y}})}
		{\dot{q}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}) (b_{1/2})^2(\textup{\texttt{\footnotesize y}})
		+\dot{q}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}) (b_{1/2})^2(\textup{\texttt{\footnotesize c}})}
	\stackrel{(9.103)}{=}
	\mu_0\Big(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}\,
		\Big|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}
		\Big)
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}\,.
	\end{equation}
Meanwhile $\mu_{1/2}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}\,|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})=1$. Combining the last few estimates gives
	\begin{align*}
	\mu_{1/2}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	&=\overbrace{
		\Bigg\{ \mu_{1/2}(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})
		\cdot\mu_{1/2}\Big(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}
			\,\Big|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\Big)\Bigg\}
		}^{\textup{estimate by
			(9.111)
			and (9.112)}}
		+
		\overbrace{\Bigg\{
		\mu_{1/2}(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})\cdot1\Bigg\}
		}^{\textup{estimate by (9.110)}}\\
	&=\Bigg\{ \mu_0(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})
	+ \frac{k^{O(1)}\delta}{4^k} 
	\Bigg\}
	\mu_0(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}\,|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})
	\Bigg\{1 + \frac{k^{O(1)} \delta}{2^k}\Bigg\}
	+\Bigg\{
	\mu_0(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})+
		\frac{k^{O(1)}\hat{\iota}\delta}{2^k}\Bigg\}\\
	&\stackrel{(9.93)}{=}
	\mu_0(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	+ \bigg(\frac1{2^k} + \hat{\iota} \bigg)
	\frac{k^{O(1)}\delta}{2^k} 
	\stackrel{(9.94)}{=} 
	\mu_0(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})+
	\frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for the event $\{\sigma=\vartheta\}$ for all $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ with $\textup{\texttt{\footnotesize r}}[\vartheta]=1$. Altogether, if we write $\omega_t$ for the marginal law of $\sigma$ under $\mu_t$, then we have
	\begin{equation}
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{1/2})
	\le k^{O(1)} \begin{pmatrix}
	4^{-k} \\ 2^{-k} \\ 0
	\end{pmatrix} \delta\,,\end{equation}
having made use of (9.98).
\smallskip

\noindent\textbf{\textup{Part 4. Effect of updates (i:ZETA.update.yw) and (i:ZETA.update.wy) on $\varsigma$-marginal.}} Recall that $\zeta_t$ denotes the marginal law of $\varsigma$ under $\mu_t$. 
Update (i:ZETA.update.yw) results in 
$\zeta_{1/4}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}\}$. Update (i:ZETA.update.wy) 
results in $\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}}\}$, but it need not hold that
$\zeta_{1/2}(\varsigma)=\zeta(\varsigma)$
for $\varsigma\in\{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}\}$.
However we claim that the discrepancy is very small. 
Recall that as a consequence of (9.102) we have $z_0=z_{1/4}=z_{1/2}$. Therefore
	\begin{align*}
	\mu_{1/2}(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	&\stackrel{(9.99)}{=}
	\frac1{z_{1/2}}
	x_{1/2}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	(b_{1/2})^1(\textup{\texttt{\footnotesize y}})
	\Bigg\{ \dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})(b_{1/2})^2(\textup{\texttt{\footnotesize y}})
	+\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})(b_{1/2})^2(\textup{\texttt{\footnotesize c}})
	\Bigg\} \\
	&\stackrel{(9.103)}{=}
	\frac1{z_{1/4}}
	x_{1/4}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	(b_{1/4})^1(\textup{\texttt{\footnotesize y}})
	\Bigg\{\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})(b_{1/4})^2(\textup{\texttt{\footnotesize y}})
	+\dot{q}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})(b_{1/4})^2(\textup{\texttt{\footnotesize c}})
	\Bigg\}
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}\\
	&\stackrel{(9.99)}{=}
	\mu_{1/4}(\varsigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	\Bigg\{1 + \frac{k^{O(1)}\delta}{2^k}\Bigg\}
	\stackrel{(9.93)}{=} 
	\zeta(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}})
	+ \frac{k^{O(1)}\delta}{4^k}\,.
	\end{align*}
The analogous estimate holds for $\varsigma=\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}$.
Denote the signed measure $\Upsilon\equiv\zeta_{1/2}-\zeta$; the above can be rewritten as
	\begin{equation}
	\max\Bigg\{
	\Big|\Upsilon(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}) \Big|,
	\Big|\Upsilon(\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}) \Big|\Bigg\}
	=
	\Big|(\zeta_{1/2}-\zeta)(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}) \Big|
	\le \frac{k^{O(1)}\delta}{4^k}\,.
	\end{equation}
Next, for all $\vartheta\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ we have
	\begin{equation}
	\Big|\Upsilon(\vartheta)\Big|
	=\bigg| (\zeta_{1/2}-\zeta_0)(\vartheta)
	+(\zeta_0-\zeta)(\vartheta)\bigg|
	\stackrel{(9.110)}
		{\le}
	\frac{k^{O(1)} \hat{\iota} \delta}{2^k}
	+\Big| (\zeta_0-\zeta)(\vartheta)\Big|
	\stackrel{(9.96)}
		{\le}
		O(\hat{\iota}\delta)\,.\end{equation}
Recall that $\mu_0(\sigma^i=\textup{\texttt{\footnotesize r}})={}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})=\zeta^i(\textup{\texttt{\footnotesize r}})$
for $i=1,2$. Therefore, using
(9.111) 
and (9.115), we have
	\begin{equation}
	\Upsilon(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})
	=\Bigg|(\mu_{1/2}-\mu_0)(\sigma^1=\textup{\texttt{\footnotesize r}})
	-\sum_{\vartheta\in\{\textup{\texttt{\footnotesize r}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}}
	\Upsilon(\vartheta)\Bigg|
	\le\bigg( \frac{1}{4^k}
		+ \hat{\iota} \bigg) k^{O(1)} \delta
	\stackrel{(9.94)}{\le} 
	k^{O(1)}\hat{\iota}\delta \,.\end{equation}
Combining
(9.114),
(9.115), and (9.116) gives
	\begin{equation}
	\Big|\Upsilon(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})\Big|
	= \Bigg|-\Upsilon
		\Bigg(\hspace{-3pt}\begin{array}{c}(\{\textup{\texttt{\footnotesize w}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\})\\
		\cup(	\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}\times\{\textup{\texttt{\footnotesize w}}\})
		\end{array}\hspace{-3pt}
		\Bigg)
	-\Upsilon\Big(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\Big)
	\Bigg|
	\le
	\bigg(\frac1{4^k} + \hat{\iota} \bigg)
		k^{O(1)}\delta
	\stackrel{(9.94)}{\le} 
	k^{O(1)}\hat{\iota}\delta\,.
	\end{equation}
This concludes our analysis of updates (i:ZETA.update.yw) and (i:ZETA.update.wy).\smallskip

\noindent\textbf{\textup{Part 5. Effect of update (i:ZETA.update.x.only).}} It is clear that we will have $\zeta_{3/4}=\zeta$, so it remains to understand the effect of update (i:ZETA.update.x.only) on the $\sigma$-marginal. 
Note that since the $b$-weights remain the same during update (i:ZETA.update.x.only), the conditional probabilities of $\sigma$ given $\varsigma$ remain unchanged between times $t=1/2$ and $t=3/4$. Thus we have
	\[
	\mu_{3/4}(\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	= \sum_{\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\}^2}
	\mu_{3/4}(\varsigma=\vartheta)
	\mu_{1/2}(\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\,|\,\varsigma=\vartheta)
	= \mu_{1/2}(\sigma=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	+ k^{O(1)} \hat{\iota}\delta\,,
	\]
where the last estimate uses
(9.114), 
(9.115),
and (9.117). The analogous bound holds for $\{\sigma=\vartheta\}$ for each $\vartheta\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. Similarly we also have
	\[\mu_{3/4}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	=\Bigg\{ \mu_{3/4}(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}})
	\mu_{1/2}\Big(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}\,\Big|\,\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\Big)\Bigg\}
	+ \mu_{3/4}(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	\stackrel{(9.116)}{=}
	\mu_{3/4}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	+ k^{O(1)}\hat{\iota}\delta\,,\]
and the analogous bound holds for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ with $\textup{\texttt{\footnotesize r}}[\sigma]=1$.
Lastly, for the case $\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$, we note that
	\[
	\frac{\mu_{3/4}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
		{\mu_{1/2}(\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
	= \frac{\mu_{3/4}(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
		{\mu_0(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
	=\frac{\zeta(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
		{\zeta_0(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})}
	\stackrel{(9.97)}{=}
	 1 + O(\ddot{\delta})\,.
	\]
Combining the above estimates with 
(9.98) and 
(9.113) gives
	\[
	\widehat{\textup{\textsf{\footnotesize ERR}}}(\omega_0,\omega_{3/4})
	\le
	k^{O(1)} \begin{pmatrix}
	\hat{\iota} & 0 \\ 2^k\hat{\iota}&0 \\ 1&1
	\end{pmatrix}
	\begin{pmatrix} \delta \\ \ddot{\delta}
		\end{pmatrix} \,.
	\]
This can be translated to a similar error bound for the clause-to-variable messages via the relation
	\[
	\hat{q}_t(\sigma)
	=\frac{ \omega_t(\sigma)/\dot{q}(\sigma)}
		{\sum_{\sigma'}
		\omega_t(\sigma')/\dot{q}(\sigma')}\,.
	\]
The claimed result follows.
\end{proof}

Let $\epsilon_2$ be a small absolute constant. Fix $x\in\{\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize -}}\}$, and let $v$ be a variable of type $\bm{T}$. Suppose we are given $\omega\in\bm{I}_0$ with marginal $\pi$ such that for both $i=1,2$ we have 
	\begin{equation}
	\gamma^i\equiv
	\sum_{e\in\delta v(x)}
	\pi_e\Big(\sigma^i=\textup{\texttt{\footnotesize r}}
		\,\Big|\,\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2
		\Big)
	\ge k\epsilon_2\,,\end{equation}
where $\pi_e\equiv\pi_{\bm{t}}$ for an edge $e$ of type $\bm{t}$. Let $\Omega$ be the maximizer of (9.41) that is consistent with $\omega$, and let $\bm{\varpi}_{\bm{L},j}$ be the resulting joint distribution of $(\sigma,\upsilon)$. Then there exists an absolute constant $\epsilon_3$
(depending only on $\epsilon_2$) such that for every edge $e\in\delta v(x)$ we have
	\[\left.
	\begin{array}{r}
	\bm{\varpi}_{\bm{L},j}( 
		\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}} \,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})\\
	\bm{\varpi}_{\bm{L},j}( \upsilon^1=\textup{\texttt{\footnotesize v}}
		\,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}} )\\
	\bm{\varpi}_{\bm{L},j}(
		\upsilon^2=\textup{\texttt{\footnotesize v}} \,|\,\sigma=\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}} )\\
	\end{array} \hspace{-4pt}
	\right\}
	\ge 1-\frac1{2^{k\epsilon_3}}
	\]
for $j=j(\bm{t})$ and all clause types $\bm{L}$ such that 
$\bm{L}(j)=\bm{t}$.

\begin{proof} Throughout the proof, $\epsilon_3$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant that depends only on $\epsilon_2$.\smallskip

\noindent\textbf{\textup{Step 1. Reduction to entropy maximization for a conditional measure.}}
Note from (9.41) that if we fix
$\Omega_{\bm{t}}$, then we obtain separate entropy maximization problems over $\Omega_{\bm{T}}$ and $\Omega_{\bm{L}}$. Let us therefore fix $\Omega_{\bm{t}}=(\textup{\textsf{aug}}_{\mathscr{D}}(\omega))_{\bm{t}}$, and consider the optimization over $\Omega_{\bm{T}}$. Let $v$ denote a variable of type $\bm{T}$, and write $\Omega_v\equiv\Omega_{\bm{T}}$.
By the method of Lagrange multipliers, the optimal $\Omega_v$ must take the form
	\[
	\Omega_v\Big( (\smash{\underline{\smash{\sigma}}},\bm{L})_{\delta v}\Big)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}} 
		\prod_{e\in\delta v}
		\hat{q}_e(\sigma_e,\bm{L}_e)\,,\]
where each $\hat{q}_e$ is a probability measure over elements $(\sigma,\bm{L})$, chosen such that $\Omega_v$ has marginals $\Omega_e\equiv\Omega_{\bm{t}}$ for $e\in\delta v$ and $\bm{t}\equiv\bm{t}_e$. The marginal of $\Omega_v$ on $(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)$ is
	\[
	\Omega_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}}
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'})\,,
	\]
where $\bar{q}_{e'}$ denotes the marginal of $\hat{q}_{e'}$ on $\sigma_{e'}$ alone. It follows that
	\begin{equation}
	\Omega_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\bigg|\, (\sigma_e,\bm{L}_e)\bigg)
	= \dot{\nu}_{\bm{T}}
		\Big(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\Big|\,\sigma_e\Big)
	\cong 
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'}).
	\end{equation}
Thus, for the purposes of this lemma, it suffices to estimate only $\dot{\nu}_{\bm{T}}(\cdot\,|\,\sigma_e)$. To this end, assume without loss $x=\textup{\texttt{\footnotesize +}}$, and consider the event $x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$. In this case 
$\sigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ for all $e\in\delta v(\textup{\texttt{\footnotesize +}})$, and
$\sigma_e=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}$ for all $e\in\delta v(\textup{\texttt{\footnotesize -}})$. Let
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}})
	\equiv
	\dot{\nu}_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v(\textup{\texttt{\footnotesize +}})}=\smash{\underline{\smash{\sigma}}}
		\,\bigg|\,x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\bigg)\,.\end{equation}
Denote $D \equiv |\delta v(\textup{\texttt{\footnotesize +}})|$.
Then $\mu$ is a probability measure over colorings $\smash{\underline{\smash{\sigma}}}\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^{2D}$ with at least one $\textup{\texttt{\footnotesize red}}$ spin in each copy $i=1,2$. Moreover, $\mu$ must maximize entropy subject to its marginals 
$\mu_\ell$. It 
follows by the method of Lagrange multipliers that there exist probability measures $h_\ell$
over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ such that
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}})
	\cong
	\Bigg\{
	\prod_{i=1,2}\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\smash{\underline{\smash{\sigma}}}^i]\ge1\}\Bigg\}
	\Bigg\{
	\prod_{\ell=1}^D h_\ell(\sigma_\ell)
	\Bigg\}\,.
	\end{equation}
We now turn to the construction and estimation of the $h_\ell$.\smallskip

\noindent\textbf{\textup{Step 2. Construction of Lagrangian weights.}} As usual, we will construct $h_{\ell,t}\to h_\ell$ in the limit $t\to\infty$. We initialize the construction with $h_{\ell,0}\equiv\mu_\ell$. Let $\mu_t$
be defined by (9.46) with $h_{\ell,t}$ in place of $h_\ell$, and let $\mu_{\ell,t}$ denote the marginal of $\mu_t$ on the $\ell$-th edge in $\delta v(\textup{\texttt{\footnotesize +}})$. Similarly
to (9.10) we have
	\begin{equation}
	\mu_{\ell,t}(\sigma)
	\cong
	h_{\ell,t}(\sigma) \overbrace{
	\sum_{\smash{\underline{\smash{\sigma}}}_{-\ell}}
	\Bigg\{
	\prod_{i=1,2}\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\smash{\underline{\smash{\sigma}}}^i]\ge1\}\Bigg\}
	\prod_{\ell'\ne\ell}
	h_{\ell',t}(\sigma_{\ell'})
	}^{\textup{denote this }\xi_{\ell,t}(\sigma)}\,.
	\end{equation}
For the remainder of the proof, we assume without loss that $\ell=1$. Then at $t=0$ we have
	\begin{equation}
	0\le 1-\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	= \prod_{\ell=2}^D \bigg\{
		1- \mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
		\bigg\}
	\le \exp\Bigg\{ - \sum_{\ell=2}^D
		\mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Bigg\}
	\stackrel{(9.45)}{\le}
		\frac{e}{\exp(\gamma^2)}
	\stackrel{(9.43)}
		{\le} \frac1{2^{k\epsilon_3}}\,.
	\end{equation}
By similar calculations, $0\le 1-\xi_{1,0}(\sigma) \le 2^{-k\epsilon_3}$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$. (In fact $\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})=1$.) Given $h_{\ell,t}$ we define $h_{\ell,t+1}$ to be the probability measure such that
	\begin{equation}
	h_{\ell,t+1}(\sigma)
	\cong \frac{\mu_\ell(\sigma)}{\xi_{\ell,t}(\sigma)}
	\stackrel{(9.47)}{\cong}
		h_{\ell,t}(\sigma)
		\frac{\mu_\ell(\sigma)}{\mu_{\ell,t}(\sigma)}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$.\smallskip

\noindent\textbf{\textup{Step 3. Estimation of Lagrangian weights.}} Suppose inductively that
	\begin{equation}
	\bigg\|\frac{\mu_{\ell,t}}{\mu_\ell}-1 \bigg\|_\infty
	\le \frac1{2^{k\epsilon_3(t+1)/3}}\end{equation}
for all $1\le\ell\le D$, where the base case $t=0$ follows from the above bounds (see (9.48)) on $\xi_{\ell,0}$. 
If we assume (9.50) holds up to $t$, then taking a telescoping sum gives
	\begin{align}
	&\Big|\xi_{1,t+1}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	-\xi_{1,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})\Big|
	= \Bigg| \prod_{j=2}^D
		\Big\{1-h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Big\}
	-\prod_{j=2}^D
		\Big\{ 1-h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Big\}
	\Bigg| \\ 
	&\qquad\le \sum_{\ell=2}^D
	h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1\Bigg|
	\prod_{j=2}^{\ell-1}
	\bigg\{1-h_{j,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}
	\prod_{j=\ell+1}^D
	\bigg\{1-h_{j,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}\\ 
	&\qquad\le O(1)\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1
	\bigg|\Bigg\}\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg\}\Bigg/
	\exp\Bigg\{
	\sum_{\ell=1}^D h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
	\Bigg\} \\
	&\qquad\stackrel{(9.50)}{\le}
	O\Bigg( \frac{\gamma^2}{\exp(\gamma^2)}\Bigg)
	\Bigg\{
	\max_{1\le\ell\le D}
	\bigg| \frac{h_{\ell,t+1}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}
		{h_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}-1
	\bigg|\Bigg\}
	\stackrel{(9.49)}{=}
	O\bigg( \frac{\gamma^2}{\exp(\gamma^2)}\bigg)
	\max_{1\le\ell\le D}
	\bigg| \frac{\mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})}{\mu_{\ell,t}(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})} -1
	\bigg|
	\stackrel{(9.50)}{\le}
	\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\,.

	\end{align}
A similar estimate holds for
$\xi_{1,t+1}(\sigma)-\xi_{1,t}(\sigma)$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$.
Next note that if we let $\tilde{\mu}_{t+1}$ be defined by
(9.46) with weights 
$h_{1,t+1}$ and $h_{\ell,t}$ for $\ell\ge2$, then
the marginal on the first edge is, similarly to (9.47),
	\[
	\tilde{\mu}_{1,t+1}(\sigma)
	\cong h_{1,t+1}(\sigma)
		\xi_{1,t}(\sigma)
	\stackrel{(9.49)}{\cong}
	\frac{\mu_1(\sigma)}{\xi_{1,t}(\sigma)}
		\xi_{1,t}(\sigma)
	=\mu_1(\sigma)\,.
	\]
It follows from this that 
	\begin{align*}
	\bigg\|\frac{\mu_{1,t+1}}{\mu_1}
		-1 \bigg\|_\infty
	&=\bigg\|
		\frac{\mu_{1,t+1}}{\tilde{\mu}_{1,t+1}}
		-1 \bigg\|_\infty
	\stackrel{(9.49)}{=} \bigg\|
		\frac{\xi_{1,t+1}}{\xi_{1,t}}
		-1 \bigg\|_\infty
	\stackrel{(9.51)}{\le}
	O\bigg(\frac{2^{-k\epsilon_3}}{2^{k\epsilon_3(t+1)/3}}\bigg)
	\le \frac1{2^{k\epsilon_3(t+2)/3}}\,,
	\end{align*}
which verifies the induction. We then take $t\to\infty$ to obtain the limiting weights $h_\ell\equiv h_{\ell,\infty}$ that define the optimal measure $\mu$ by (9.46). Suppose $e$ corresponds to the first edge in $\delta v(\textup{\texttt{\footnotesize +}})$. Then, for all $\sigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$,
	\[
	\dot{\nu}_{\bm{T}}\bigg(
	\sum_{e'\in\delta v(\textup{\texttt{\footnotesize +}})\setminus e}
	\mathbf{1}\{ (\sigma_{e'})^2=\textup{\texttt{\footnotesize r}}\} =0
	\,\bigg|\,\sigma_e
	\bigg)
	\stackrel{(9.45)}{=}
	\mu\bigg(
	\smash{\underline{\smash{\sigma}}}_{-1}\in\{\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize b}}\}^D \,\bigg|\,\sigma_1
	\bigg)
	\stackrel{(9.50)}{\le}
	O\Bigg(
	\prod_{\ell=2}^D
		\bigg\{ 1-h_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\bigg\}
		\Bigg) \le \frac1{2^{k\epsilon_3}}\,.
	\]
The lemma follows by recalling (9.44).
\end{proof}

Let $\epsilon_2$ be a small absolute constant. Fix $x\in\{\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize -}}\}$, and let $v$ be a variable of type $\bm{T}$. Suppose we are given $\omega\in\bm{I}_0$ with marginal $\pi$ such that for both $i=1,2$ we have 
	\begin{equation}
	\gamma^i\equiv
	\sum_{e\in\delta v(x)}
	\pi_e\Big(\sigma^i=\textup{\texttt{\footnotesize r}}
		\,\Big|\,\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2
		\Big)
	\ge k\epsilon_2\,,\end{equation}
where $\pi_e\equiv\pi_{\bm{t}}$ for an edge $e$ of type $\bm{t}$. Let $\Omega$ be the maximizer of (9.41) that is consistent with $\omega$, and let $\bm{\varpi}_{\bm{L},j}$ be the resulting joint distribution of $(\sigma,\upsilon)$. Then there exists an absolute constant $\epsilon_3$
(depending only on $\epsilon_2$) such that for every edge $e\in\delta v(x)$ we have
	\[\left.
	\begin{array}{r}
	\bm{\varpi}_{\bm{L},j}( 
		\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}} \,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})\\
	\bm{\varpi}_{\bm{L},j}( \upsilon^1=\textup{\texttt{\footnotesize v}}
		\,|\, \sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}} )\\
	\bm{\varpi}_{\bm{L},j}(
		\upsilon^2=\textup{\texttt{\footnotesize v}} \,|\,\sigma=\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}} )\\
	\end{array} \hspace{-4pt}
	\right\}
	\ge 1-\frac1{2^{k\epsilon_3}}
	\]
for $j=j(\bm{t})$ and all clause types $\bm{L}$ such that 
$\bm{L}(j)=\bm{t}$.

\begin{proof} Throughout the proof, $\epsilon_3$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant that depends only on $\epsilon_2$.\smallskip

\noindent\textbf{\textup{Step 1. Reduction to entropy maximization for a conditional measure.}}
Note from (9.41) that if we fix
$\Omega_{\bm{t}}$, then we obtain separate entropy maximization problems over $\Omega_{\bm{T}}$ and $\Omega_{\bm{L}}$. Let us therefore fix $\Omega_{\bm{t}}=(\textup{\textsf{aug}}_{\mathscr{D}}(\omega))_{\bm{t}}$, and consider the optimization over $\Omega_{\bm{T}}$. Let $v$ denote a variable of type $\bm{T}$, and write $\Omega_v\equiv\Omega_{\bm{T}}$.
By the method of Lagrange multipliers, the optimal $\Omega_v$ must take the form
	\[
	\Omega_v\Big( (\smash{\underline{\smash{\sigma}}},\bm{L})_{\delta v}\Big)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}} 
		\prod_{e\in\delta v}
		\hat{q}_e(\sigma_e,\bm{L}_e)\,,\]
where each $\hat{q}_e$ is a probability measure over elements $(\sigma,\bm{L})$, chosen such that $\Omega_v$ has marginals $\Omega_e\equiv\Omega_{\bm{t}}$ for $e\in\delta v$ and $\bm{t}\equiv\bm{t}_e$. The marginal of $\Omega_v$ on $(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)$ is
	\[
	\Omega_v(\smash{\underline{\smash{\sigma}}}_{\delta v},\bm{L}_e)
	= \frac{\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})}{\bm{\dot{z}}}
	\hat{q}_e(\sigma_e,\bm{L}_e)
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'})\,,
	\]
where $\bar{q}_{e'}$ denotes the marginal of $\hat{q}_{e'}$ on $\sigma_{e'}$ alone. It follows that
	\begin{equation}
	\Omega_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\bigg|\, (\sigma_e,\bm{L}_e)\bigg)
	= \dot{\nu}_{\bm{T}}
		\Big(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
		\,\Big|\,\sigma_e\Big)
	\cong 
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e'\in\delta v\setminus e}
	\bar{q}_{e'}(\sigma_{e'}).
	\end{equation}
Thus, for the purposes of this lemma, it suffices to estimate only $\dot{\nu}_{\bm{T}}(\cdot\,|\,\sigma_e)$. To this end, assume without loss $x=\textup{\texttt{\footnotesize +}}$, and consider the event $x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$. In this case 
$\sigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ for all $e\in\delta v(\textup{\texttt{\footnotesize +}})$, and
$\sigma_e=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}$ for all $e\in\delta v(\textup{\texttt{\footnotesize -}})$. Let
	\begin{equation}
	\mu(\smash{\underline{\smash{\sigma}}})
	\equiv
	\dot{\nu}_{\bm{T}}\bigg(\smash{\underline{\smash{\sigma}}}_{\delta v(\textup{\texttt{\footnotesize +}})}=\smash{\underline{\smash{\sigma}}}
		\,\bigg|\,x_v=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\bigg)\,.\end{equation}
Denote $D \equiv |\delta v(\textup{\texttt{\footnotesize +}})|$.
Then $\mu$ is a probability measure over colorings $\smash{\underline{\smash{\sigma}}}\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^{2D}$ with at least one $\textup{\texttt{\footnotesize red}}$ spin in each copy $i=1,2$. Moreover, $\mu$ must maximize entropy subject to its marginals 
$\mu_\ell$. It 
follows by the method of Lagrange multipliers that there exist probability measures $h_\ell$
over $\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ such that
