	\mu(\smash{\underline{\smash{\sigma}}})
	\cong
	\Bigg\{
	\prod_{i=1,2}\mathbf{1}\{\textup{\texttt{\footnotesize r}}[\smash{\underline{\smash{\sigma}}}^i]\ge1\}\Bigg\}
	\Bigg\{
	\prod_{\ell=1}^D h_\ell(\sigma_\ell)
	\Bigg\}\,.
	\end{equation}
We now turn to the construction and estimation of the $h_\ell$.\smallskip

\noindent\textbf{\textup{Step 2. Construction of Lagrangian weights.}} As usual, we will construct $h_{\ell,t}\to h_\ell$ in the limit $t\to\infty$. We initialize the construction with $h_{\ell,0}\equiv\mu_\ell$. Let $\mu_t$
be defined by (9.46) with $h_{\ell,t}$ in place of $h_\ell$, and let $\mu_{\ell,t}$ denote the marginal of $\mu_t$ on the $\ell$-th edge in $\delta v(\textup{\texttt{\footnotesize +}})$. Similarly
to (9.10) we have
	\begin{equation}
