	\prod_{\ell'\ne\ell}
	h_{\ell',t}(\sigma_{\ell'})
	}^{\textup{denote this }\xi_{\ell,t}(\sigma)}\,.
	\end{equation}
For the remainder of the proof, we assume without loss that $\ell=1$. Then at $t=0$ we have
	\begin{equation}
	0\le 1-\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	= \prod_{\ell=2}^D \bigg\{
		1- \mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})
		\bigg\}
	\le \exp\Bigg\{ - \sum_{\ell=2}^D
		\mu_\ell(\textup{\texttt{\footnotesize p}}\textup{\texttt{\footnotesize r}})\Bigg\}
	\stackrel{(9.45)}{\le}
		\frac{e}{\exp(\gamma^2)}
	\stackrel{(9.43)}
		{\le} \frac1{2^{k\epsilon_3}}\,.
	\end{equation}
By similar calculations, $0\le 1-\xi_{1,0}(\sigma) \le 2^{-k\epsilon_3}$ for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$. (In fact $\xi_{1,0}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})=1$.) Given $h_{\ell,t}$ we define $h_{\ell,t+1}$ to be the probability measure such that
	\begin{equation}
	h_{\ell,t+1}(\sigma)
	\cong \frac{\mu_\ell(\sigma)}{\xi_{\ell,t}(\sigma)}
	\stackrel{(9.47)}{\cong}
		h_{\ell,t}(\sigma)
		\frac{\mu_\ell(\sigma)}{\mu_{\ell,t}(\sigma)}
	\end{equation}
for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$.\smallskip

\noindent\textbf{\textup{Step 3. Estimation of Lagrangian weights.}} Suppose inductively that
	\begin{equation}
	\bigg\|\frac{\mu_{\ell,t}}{\mu_\ell}-1 \bigg\|_\infty
	\le \frac1{2^{k\epsilon_3(t+1)/3}}\end{equation}
for all $1\le\ell\le D$, where the base case $t=0$ follows from the above bounds (see (9.48)) on $\xi_{\ell,0}$. 
If we assume (9.50) holds up to $t$, then taking a telescoping sum gives
	\begin{align}
	&\Big|\xi_{1,t+1}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	-\xi_{1,t}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})\Big|
	= \Bigg| \prod_{j=2}^D
