	\[
	\dot{\nu}_{\bm{T}}\bigg(
	\sum_{e'\in\delta v(\textup{\texttt{\footnotesize +}})\setminus e}
	\mathbf{1}\{ (\sigma_{e'})^2=\textup{\texttt{\footnotesize r}}\} =0
