If the clause type $\bm{L}$ is nice
and diverse (Definition~9.3), then
	\[
	\bm{\varpi}_{\bm{L},j}(\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})
	\le \frac1{2^{k(1+\epsilon_4)}}\]
for all $1\le j\le k(\bm{L})$, where $\epsilon_4$ is an absolute constant.

\begin{proof} Throughout the proof, $\epsilon_4$ denotes a small positive number, whose value may change from one occurrence to the next, but ultimately is taken as an absolute constant. Fix $\bm{L},j$, and let $\Xi$ denote the empirical measure of configurations $(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{(\delta v\cup\delta a)\setminus e})$ over all $e=(av)$ such that $\bm{L}_a=\bm{L}$ and $j(v;a)=j$. In the proof below we assume without loss of generality that the edge $e$ has label $\textup{\texttt{\footnotesize L}}_e=\textup{\texttt{\footnotesize +}}$.\smallskip

\noindent\textbf{\textup{Step 1. Reduction to entropy maximization for a conditional measure.}} Let $\textup{\texttt{\footnotesize V}}$ denote the subset of all valid configurations $(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{(\delta v\cup\delta a)\setminus e})$ that have $\Sigma_e\in\{\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize v}}\}^2$. Define the conditional measure
	\[
	\mu\Big(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\equiv
	\Xi\bigg(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{(\delta v\cup\delta a)\setminus e}\,\bigg|\, \textup{\texttt{\footnotesize V}}\bigg)\,.
	\]
Note the marginals of $\mu$ must be close to those of the original measure $\Xi$, since Lemma~9.5 gives
	\begin{equation}
	\Xi(\textup{\texttt{\footnotesize V}})
	\ge
	\bm{\varpi}_{\bm{L},j}(\varsigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})
	\ge 1-O\bigg(\frac{k^2}{2^k}\bigg)\,.\end{equation}
The measure $\mu$ maximizes entropy subject to the marginal distributions of $\sigma_{e'}$ for $e'\ne e$,
as well as of $(\Sigma_e)^i$ for $i=1,2$. By the method of Lagrange multipliers, we can express
	\begin{equation}
	\mu\Big(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{(\delta v\cup\delta a)\setminus e}\Big)
	\cong 
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\Bigg\{
	\prod_{e'\in(\delta v \cup \delta a)\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}
	\mathbf{1}_{\textup{\texttt{\footnotesize V}}}\,,
	\end{equation}
where we fix $(b_e)^i(\textup{\texttt{\footnotesize w}})\equiv1$ for both $i=1,2$.
For $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$, let us write
$(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e})\sim x$
if $(\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e})$ is consistent with frozen spin $x_v=x$. Note that for $\Sigma_e\in\{\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize v}}\}^2$, we have
	\[
	\bigg\{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e})\sim x
	\bigg\}
	= S(x) \equiv \prod_{i=1,2} S^i(x^i)\,,
	\]
where $S^i(x^i)$ \textbf{\textup{does not depend on $\Sigma_e$}}. For instance, for all $\Sigma_e\in\{\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize v}}\}^2$,
	\[
	\bigg\{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e}
	: (\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e})
	\sim \textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}
	\bigg\}
	=\prod_{i=1,2}
	\overbrace{\Bigg\{(\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e})^i
	: (\smash{\underline{\smash{\sigma}}}_{\delta v(\textup{\texttt{\footnotesize -}})})^i
		\equiv\textup{\texttt{\footnotesize y}},
	(\smash{\underline{\smash{\sigma}}}_{\delta v(\textup{\texttt{\footnotesize +}})\setminus e})^i
		\equiv \textup{\texttt{\footnotesize p}},
	\sum_{e'\in \delta v(\textup{\texttt{\footnotesize +}})\setminus e}
	\mathbf{1}\{(\sigma_{e'})^i=\textup{\texttt{\footnotesize r}}\}\ge1
	\Bigg\}}^{S^i(\textup{\texttt{\footnotesize +}})}\,.
	\]
Consequently, the marginal of (9.54)
on $(x_v,\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta a\setminus e})$ can be written as
	\begin{equation}
	\mu(x_v,\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta a\setminus e})
	=\frac{\mathbf{1}_{\textup{\texttt{\footnotesize V}}}}Z
	\Bigg\{\prod_{i=1,2} (b_e)^i((\Sigma_e)^i)\Bigg\}
	\overbrace{
	\Bigg\{\sum_{\smash{\underline{\smash{\sigma}}}_{\delta v\setminus e} \in S(x_v)}
	\prod_{e'\in\delta v\setminus e}
	b_{e'}(\sigma_{e'})
	\Bigg\}}^{\textup{denote this }b_v(x_v)}
	\Bigg\{ \prod_{e'\in \delta a\setminus e}
	b_{e'}(\sigma_{e'})\Bigg\}\,,\end{equation}
where $Z$ is the normalizing constant. We next turn to the construction and estimation of the weights in (9.55).\smallskip

\noindent\textbf{\textup{Step 2. Initialization of Lagrangian weights.}} We will construct weights $b_t\to b$ in the limit $t\to\infty$. At $t=0$, on the variable $v$ and on the edges $\delta a\setminus e$, we put
	{\setlength{\jot}{0pt}\begin{alignat}{2}

	b_{v,0}(x)
		&\equiv \mu_v(x)
		\equiv \mu(x_v=x)\quad
		&&\textup{for 
		$x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$,} \\
	b_{e',0}(\sigma)
		&\equiv \mu_{e'}(\sigma)
		\equiv \mu( \sigma_{e'}=\sigma )\quad
		&&\textup{for 
		$\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$
		and $e'\in\delta a\setminus e$.}

		\end{alignat}}
Abbreviate $K\equiv k(\bm{L})$. On the central edge $e=(av)$, for $i=1,2$ we put
	\[(b_{e,0})^i( (\Sigma_e)^i )
		\equiv
		\frac{(\mu_e)^i( (\Sigma_e)^i)}
			{ 1/ (2^K)^{\mathbf{1}\{(\Sigma_e)^i=\textup{\texttt{\footnotesize v}}\}} }\,.
		\]
Let $\mu_t$ be defined as $\mu$ in (9.55), but with $b_t$ in place of $b$, and normalizing constant $Z_t$. We begin by estimating the marginals at time $t=0$. Recalling the notation $\textup{\texttt{\footnotesize u}}\equiv\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$, we have
	\[
	Z_0\mu_{e,0}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})
	= (\mu_e)^1(\textup{\texttt{\footnotesize w}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	= (\mu_e)^1(\textup{\texttt{\footnotesize w}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})
	\Bigg\{ 1 - O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,,
	\]
where the estimate uses (9.53) and the assumption that $\bm{L}$ is nice, which implies
(together with the judicious condition) $\Xi_{e'}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})\ge 1-O(2^{-k})$ for all $e'\in\delta a$. (In the above calculation, the $O(k^2/2^k)$ error comes from the fact that among the configurations $\smash{\underline{\smash{\sigma}}}_{\delta a\setminus e}$ with $\sigma_{e'}\in\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}}$ for all $e'$, some will not be compatible with $\sigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$ because they will have too few $\textup{\texttt{\footnotesize c}}$ spins.) Next recall that (as noted in the proof of Lemma~9.7) if $\bm{L}$ is both nice and diverse, then Lemma~9.6 implies (9.29), which says that $\omega_{\bm{L},j}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}})\ge1/65$ for at least $k/10$ indices $1\le j\le k(\bm{L})$. Recall also that (9.53) implies that the marginals of $\mu$ are close to those of the original measure $\Xi$, so (9.29) implies
	\begin{equation}
	\min\Bigg\{
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}})\ge\frac1{66}
	\bigg\},
	\sum_{j=1}^{k(\bm{L})}
	\mathbf{1}\bigg\{
	\mu_j(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}})\ge\frac1{66}
	\bigg\}
	\Bigg\} \ge \frac{k}{10}\,.\end{equation}
It follows using (9.57) that 
	\begin{align*}
	Z_0\mu_{e,0}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}})
	&=
	(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})
	\frac{\mu_v(\textup{\texttt{\footnotesize +}}) }{1/2}
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\frac{\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})}{1/2}
	\Bigg\}
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\\
	&=
	(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})
	\Bigg\{ 1 - O\bigg(\frac1{2^{k\epsilon_4}}\bigg)
	\Bigg\}\,,
	\end{align*}
where the factors of $1/2$ come from the $2^K$ term in the definition of $(b_{e,0})^1(\textup{\texttt{\footnotesize v}})$. Lastly,
	\begin{equation}
	Z_0\mu_{e,0}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})
	=\overbrace{
	\frac{(\mu_e)^1(\textup{\texttt{\footnotesize v}})}{1/2^K}
	\frac{(\mu_e)^2(\textup{\texttt{\footnotesize v}})}{1/2^K}
	}^{O(1)}
	\overbrace{\mu_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	\Bigg\{\prod_{e'\in\delta a\setminus e}
	\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\Bigg\}}^{\textup{at most $2^{-k(1+\epsilon_4)}$
		by (9.57)}}
	\le 
	O\bigg(
	\frac{\min\{(\mu_e)^1(\textup{\texttt{\footnotesize v}}),(\mu_e)^2(\textup{\texttt{\footnotesize v}})\}}
		{2^{k\epsilon_4}}
	\bigg)\,.
	\end{equation}
The above estimates imply that the single-copy marginals of $\mu_{e,0}$ are close to those of $\mu_e$: more precisely, we have
	\begin{equation}
	\bigg|
	\frac{(\mu_{e,0})^i(\Sigma^i)}{(\mu_e)^i(\Sigma^i)}-1
	\bigg|
	\le
	\begin{cases}
	k^{O(1)}/2^k &\textup{if $\Sigma^i=\textup{\texttt{\footnotesize w}}$,}\\
	O(2^{-k\epsilon_4}) &\textup{if $\Sigma^i=\textup{\texttt{\footnotesize v}}$,}\\
	\end{cases}
	\end{equation}
for both $i=1,2$. We then turn to estimating the marginals at $t=0$ on the edges of $\delta a\setminus e$. For $e'\in \delta a\setminus e$ and $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, we can represent the marginal probability of $\sigma$ on $e'$ as
	\begin{equation}
	\mu_{e',0}(\sigma)
	=\sum_{\Sigma\in\{\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize r}}\}^2}
	\mu_{e,0}(\Sigma)
	\mu_0\Big(\sigma_{e'}=\sigma\,
		\Big|\,\Sigma_e=\Sigma\Big)\,.
	\end{equation}
The term $\mu_{e,0}(\Sigma)$ was just estimated above,
while the conditional probability 
$\mu_0(\sigma_{e'}=\sigma\,|\,\Sigma_e=\Sigma)$ can be obtained from the representation (9.55). For instance, for each $e'\in\delta a\setminus e$, we have
	\[
	\mu_0\Big(\sigma_{e'}=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\,
		\Big|\,\Sigma_e=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}\Big)
	\stackrel{(9.55)}{=}
	\frac{\displaystyle 
	\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\prod_{e''\in\delta a\setminus\{e,e'\}}
	\mu_{e''}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})}
	{\displaystyle \mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}}) 
	\prod_{e''\in\delta a\setminus\{e,e'\}}
	\mu_{e''}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})}
	\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	= \frac{\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}\,,
	\]
where the last estimate uses that $e'$ is a nice edge, so $\mu_{e''}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})$ is close to $1/2$. Similarly,
	\[\mu_0\Big(\sigma_{e'}=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\,
		\Big|\,\Sigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	\stackrel{(9.55)}{=}
	\frac{\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})}{\mu_{e'}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})}
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\]
Lastly we have $\mu_0(\sigma_{e'}=\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}\,|\,\Sigma_e=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})=1$. Substituting the last few estimates into (9.60) gives
	\begin{align*}
	\mu_{e',0}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	&\stackrel{(9.60)}{=}
	\mu_{e,0}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})
	+\mu_{e,0}\Big(\{\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize v}}\}\Big)
	\frac{\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})}{1/2}
		\Bigg\{1-O\bigg(\frac1{2^{k\epsilon_4}}\bigg)\Bigg\}
	+\mu_{e,0}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}) 
	\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\Bigg\{1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\\
	&\stackrel{(9.58)}{=}
	\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Bigg\{
	O\bigg(\frac1{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg( \frac1{2^k}\bigg)
	+ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}
	=\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Bigg\{ 1-O\bigg(\frac{k^2}{2^k}\bigg)\Bigg\}\,.
	\end{align*}
By similar (but simpler) calculations, the same estimate holds for the other elements $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. Lastly, we estimate the marginal law at $t=0$ for the frozen spin $x_v$, using a similar conditioning as in (9.60). To this end, note that
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\Big)
	\stackrel{(9.55)}{=}
	\frac{\displaystyle b_{v,0}(x)
	\prod_{i=1,2}(b_{e,0})^i(\textup{\texttt{\footnotesize w}})}{
	\displaystyle
	\sum_{x'\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2}
	b_{v,0}(x')
	\prod_{i=1,2}(b_{e,0})^i(\textup{\texttt{\footnotesize w}})}
	\stackrel{(9.56)}{=}
	\mu_v(x)
	\]
for any $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$. Likewise we have
	\[
	\mu_0\Big(x_v=x\,\Big|\,\Sigma_e=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}\Big)
	\stackrel{(9.55)}{=}
	\frac{\mathbf{1}\{x^1=\textup{\texttt{\footnotesize +}}\} b_{v,0}(x)
		(b_{e,0})^1(\textup{\texttt{\footnotesize v}})(b_{e,0})^2(\textup{\texttt{\footnotesize w}})}
	{\displaystyle\sum_{x'\in\{\textup{\texttt{\footnotesize +}}\}
		\times\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}}
		b_{v,0}(x')
		(b_{e,0})^1(\textup{\texttt{\footnotesize v}})(b_{e,0})^2(\textup{\texttt{\footnotesize w}})}
	\stackrel{(9.56)}{=}
	\frac{\mu_v(x)}{(\mu_v)^1(\textup{\texttt{\footnotesize +}})}
	\mathbf{1}\{x^1=\textup{\texttt{\footnotesize +}}\}\,,
	\] 
and a similar expression holds for the case $\Sigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}}$. Lastly, note that
$\mu_0(x_v=x\,\Big|\,\Sigma_e=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})
=\mathbf{1}\{x=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\}$. Substituting these into (9.60) gives 
	\begin{align*}
	\mu_{v,0}(x)
	&\stackrel{(9.60)}{=}
	\mu_{e,0}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})\mathbf{1}\{x=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\}
	+ \mu_{e,0}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}})\frac{\mu_v(x)}
		{(\mu_v)^1(\textup{\texttt{\footnotesize +}})}
		{\mathbf{1}\{x^1=\textup{\texttt{\footnotesize +}}\}}
	+ \mu_{e,0}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize v}})\frac{\mu_v(x)}
		{(\mu_v)^2(\textup{\texttt{\footnotesize +}})}
		{\mathbf{1}\{x^2=\textup{\texttt{\footnotesize +}}\}}
	+\mu_{e,0}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}) \mu_v(x)\\
	&\stackrel{(9.58)}{=}
	\mu_v(x)
	\Bigg\{
	O\bigg(\frac{\mathbf{1}\{x=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}\}}{2^{k(1+\epsilon_4)}}\bigg)
	+O\bigg(\frac{\mathbf{1}\{x^1=\textup{\texttt{\footnotesize +}}\}
		+ \mathbf{1}\{x^2=\textup{\texttt{\footnotesize +}}\}}{2^k}\bigg)
	+1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}
	=\mu_v(x)\Bigg\{
	1-O\bigg(\frac{k^2}{2^k}\bigg)
	\Bigg\}\,.
	\end{align*}
To summarize the last few estimates, we have shown that at $t=0$ we have 
	\begin{equation}
	\begin{pmatrix}
	\displaystyle\bigg\|\frac{\mu_{v,0}}{\mu_v}-1\bigg\|_\infty
	+
	\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,0})^i(\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^i(\textup{\texttt{\footnotesize w}})}-1\bigg|
	+
	\sum_{e'\in\delta a\setminus v}
	\bigg\|\frac{\mu_{e',0}}{\mu_{e'}}-1\bigg\|_\infty
	\\
	\displaystyle\sum_{i=1,2} \bigg|\frac{(\mu_{e,0})^i(\textup{\texttt{\footnotesize v}})}
		{(\mu_e)^i(\textup{\texttt{\footnotesize v}})}-1\bigg|
		\end{pmatrix}
	\le k^{O(1)}
	 \begin{pmatrix}
		2^{-k}\\ 2^{-k\epsilon_4} \end{pmatrix}\,.
	\end{equation}
We now turn to the construction of the sequence $b_t\to b_\infty\equiv b$, where we recall that $b$ denotes the limiting weights in (9.55) that give the solution to the constrained entropy maximization problem.\smallskip

\noindent\textbf{\textup{Step 3. Iterative construction and covariance estimates.}} For each $t\ge0$, suppose we have the weights $b_t$, which define the measure $\mu_t$. We then define the weights at time $t+1$ by setting
	\begin{equation}
	\frac{b_{v,t+1}(x)}{b_{v,t}(x)}
		=\frac{\mu_v(x)}{\mu_{v,t}(x)}\,,\quad
	\frac{b_{e',t+1}(\sigma)}{b_{e',t}(\sigma)}
		=\frac{\mu_{e'}(\sigma)}{\mu_{e',t}(\sigma)}
			\,,\quad
	\frac{(b_{e,t+1})^i(\Sigma^i)}{(b_{e,t})^i(\Sigma^i)}
		=\frac{\mu_e(\Sigma^i)}{\mu_{e,t}(\Sigma^i)}
	\end{equation}
for all $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$,
 $e'\in\delta a\setminus e$,
 $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, 
 $i=1,2$, and $\Sigma^i\in\{\textup{\texttt{\footnotesize w}},\textup{\texttt{\footnotesize v}}\}$. We will show by induction that for all $t\ge0$ we have the bound
	\begin{equation}
	\begin{pmatrix} \displaystyle
	\bigg\|
		\frac{\mu_{v,t}}{\mu_v}
		-1\bigg\|_\infty
	+\sum_{i=1,2}
	\bigg|\frac{(\mu_{e,t})^i(\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^i(\textup{\texttt{\footnotesize w}})}-1\bigg|
	+\sum_{e'\in\delta a\setminus e}
	\bigg\| \frac{\mu_{e',t}}{\mu_{e'}}-1\bigg\|_\infty\\
	\displaystyle \sum_{i=1,2}
		\bigg|\frac{(\mu_{e,t})^i(\textup{\texttt{\footnotesize v}})}
		{(\mu_e)^i(\textup{\texttt{\footnotesize v}})}-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
where the base case $t=0$ follows from (9.61).
Note that
(9.62) and (9.63)
together imply
	\begin{equation}
	\begin{pmatrix}
	\displaystyle \Bigg\{
		\bigg\|\frac{b_{v,t+1}}{b_{v,t}}-1\bigg\|_\infty
		+\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\textup{\texttt{\footnotesize w}})}
			{(b_{e',t})^i(\textup{\texttt{\footnotesize w}})}
			-1\bigg|
		+\sum_{e'\in\delta a\setminus e}
		\bigg\|\frac{b_{e',t+1}}{b_{e',t}}-1\bigg\|_\infty
		\Bigg\}\\
	\displaystyle\sum_{i=1,2}
		\bigg|\frac{(b_{e',t+1})^i(\textup{\texttt{\footnotesize v}})}
			{(b_{e',t})^i(\textup{\texttt{\footnotesize v}})}
			-1\bigg|
	\end{pmatrix}
	\le \frac{k^{O(1)}}{(2^{k\epsilon_4})^{t/2}}
	\begin{pmatrix}2^{-k}\\2^{-k\epsilon_4}
		\end{pmatrix}\,,
	\end{equation}
Towards the proof of (9.63),
we estimate covariances under the measure $\mu_t$. First, for all $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ we have 	\begin{align*}
	\frac{Z_t \mu_t(x_v=x,(\Sigma_e)^1=\textup{\texttt{\footnotesize w}})}
		{\mu_v(x) (\mu_e)^1(\textup{\texttt{\footnotesize w}})}
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\textup{\texttt{\footnotesize w}})}{\mu_v(x) (\mu_e)^1(\textup{\texttt{\footnotesize w}})}
	\Bigg\{
	(b_{e,t})^2(\textup{\texttt{\footnotesize w}})
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
		\bigg(1-\frac{k^{O(1)}}{2^k}\bigg)\\
	&\qquad\qquad\qquad
		+\mathbf{1}\{x^2=\textup{\texttt{\footnotesize +}}\}(b_{e,t})^2(\textup{\texttt{\footnotesize v}})
		\prod_{e'}b_{e',t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize y}})
		\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=\frac{b_{v,t}(x)
	(b_{e,t})^1(\textup{\texttt{\footnotesize w}})}{\mu_v(x) (\mu_e)^1(\textup{\texttt{\footnotesize w}})}
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{(9.64)}{=}
	1-\frac{k^{O(1)}}{2^k}\,.
	\end{align*}
In combination with (9.63), this implies that for all $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ and $i=1,2$ we have
	\[\Bigg|
	\frac{\mathrm{Cov}_{\mu_t}(
		\mathbf{1}\{x_v=x\},
		\mathbf{1}\{(\Sigma_e)^i=\textup{\texttt{\footnotesize w}}\})}
		{\mu_v(x) (\mu_e)^i(\textup{\texttt{\footnotesize w}})}\Bigg|
	=\Bigg| \frac{\mu_t(x_v=x,(\Sigma_e)^1=\textup{\texttt{\footnotesize w}})}
		{\mu_v(x) (\mu_e)^1(\textup{\texttt{\footnotesize w}})}
		-\frac{\mu_{v,t}(x) (\mu_{e,t})^1(\textup{\texttt{\footnotesize w}})}
		{\mu_v(x) (\mu_e)^1(\textup{\texttt{\footnotesize w}})}
		\Bigg|
	\le \frac{k^{O(1)}}{2^k}\,.
	\]
Next, for $e'\in\delta a\setminus e$ and
$\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, we calculate
	\begin{align*}
	\frac{Z_t \mu_t((\Sigma_e)^1=\textup{\texttt{\footnotesize w}},
		\sigma_{e'}=\sigma)}
		{(\mu_e)^1(\textup{\texttt{\footnotesize w}})\mu_{e'}(\sigma)}
	&=
	\frac{(b_{e,t})^1(\textup{\texttt{\footnotesize w}})b_{e',t}(\sigma)}
		{(\mu_e)^1(\textup{\texttt{\footnotesize w}})\mu_{e'}(\sigma)}
	\Bigg\{
	(b_{e,t})^2(\textup{\texttt{\footnotesize w}})
	\prod_{e''\in\delta a\setminus\{e,e'\}}
	b_{e'',t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
	\bigg(1-\frac{k^{O(1)}}{2^k}\bigg) \\
	&\qquad\qquad\qquad
	+\mathbf{1}\{\sigma^2=\textup{\texttt{\footnotesize y}}\}
	(b_{e,t})^2(\textup{\texttt{\footnotesize v}})
	(b_{v,t})^2(\textup{\texttt{\footnotesize +}})
	\prod_{e''\in\delta a\setminus\{e,e'\}}
	b_{e'',t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize y}})
	\bigg(1-\frac{O(1)}{2^{k\epsilon_4}}\bigg)
	\Bigg\}\\
	&=	\frac{(b_{e,t})^1(\textup{\texttt{\footnotesize w}})b_{e',t}(\sigma)}
		{(\mu_e)^1(\textup{\texttt{\footnotesize w}})\mu_{e'}(\sigma)}
	\Bigg\{1- \frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{(9.64)}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\end{align*}
This implies that for all $e'\in\delta a\setminus e$ and $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, we have
	\[
	\frac{\mathrm{Cov}_{\mu_t}(
		\mathbf{1}\{(\Sigma_e)^i=\textup{\texttt{\footnotesize w}}\},
		\mathbf{1}\{\sigma_{e'}=\sigma\})}
		{(\mu_e)^i(\textup{\texttt{\footnotesize w}})
		\mu_{e'}(\sigma)
		 }
		\le\frac{k^{O(1)}}{2^k}\,.
	\]
Similar calculations for the case $(\Sigma_e)^i=\textup{\texttt{\footnotesize v}}$ give 
	\begin{align*}
	\frac{\mathrm{Cov}_{\mu_t}(\mathbf{1}\{x_v=x\},
		\mathbf{1}\{(\Sigma_e)^i=\textup{\texttt{\footnotesize v}}\})}
		{\mu_v(x)
		(\mu_e)^i(\textup{\texttt{\footnotesize v}})}
	&\le O(1)\,,\\
	\frac{\mathrm{Cov}_{\mu_t}(
		\mathbf{1}\{(\Sigma_e)^i=\textup{\texttt{\footnotesize v}}\},
		\mathbf{1}\{\sigma_{e'}=\sigma\})}
			{(\mu_e)^i(\textup{\texttt{\footnotesize v}})
		\mu_{e'}(\sigma)}
	&\le O(1)\,,
	\end{align*}
for all $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$,
 $e'\in\delta a\setminus e$, and $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$. Next, on the edge $e=(av)$, we have
 	\[
	\frac{Z_t\mu_{e,t}(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize w}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})}
	= \frac{(b_{e,t})^1(\textup{\texttt{\footnotesize w}})(b_{e,t})^2(\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize w}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})}
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\textup{\texttt{\footnotesize u}}\textup{\texttt{\footnotesize u}})
	\Bigg\{1-\frac{k^{O(1)}}{2^k}\Bigg\}
	\stackrel{(9.64)}{=}
	1- \frac{k^{O(1)}}{2^k}\,.
	\]
Next, using the diversity bound
(9.57), we also have
	\begin{align*}
	\frac{Z_t\mu_{e,t}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})}
	&\stackrel{(9.57)}{=} 
	\frac{(b_{e,t})^1(\textup{\texttt{\footnotesize v}})(b_{e,t})^2(\textup{\texttt{\footnotesize w}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize w}})}
	(b_{v,t})^1(\textup{\texttt{\footnotesize +}}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\} \\
	&
	\stackrel{(9.64)}{=}
	\Bigg\{1-\frac{O(1)}{2^{k\epsilon_4}}\Bigg\}
	2^K (b_{v,t})^1(\textup{\texttt{\footnotesize +}}) 
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize u}})
	\stackrel{(9.64)}{=}
	1-\frac{O(1)}{2^{k\epsilon_4}}\,,\\
	\frac{Z_t\mu_{e,t}(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize v}})}
	&= \frac{(b_{e,t})^1(\textup{\texttt{\footnotesize v}})(b_{e,t})^2(\textup{\texttt{\footnotesize v}})}
		{(\mu_e)^1(\textup{\texttt{\footnotesize v}})(\mu_e)^2(\textup{\texttt{\footnotesize v}})}
	\mu_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\\
	&\stackrel{(9.64)}{=} 2^K \cdot 2^K\cdot
	\mu_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	\prod_{e'\in\delta v\setminus e}
	b_{e',t}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})
	\stackrel{(9.57)}{\le }
	O\bigg( \frac{2^k}{2^{k\epsilon_4}}\bigg)
	\,.\end{align*}
The last few estimates combined imply
	\[
	\frac{\mathrm{Cov}_{\mu_t}(\mathbf{1}\{(\Sigma_e)^1=\Sigma^1\},
	\mathbf{1}\{(\Sigma_e)^2=\Sigma^2\})}
		{(\mu_e)^1(\Sigma^1)
		(\mu_e)^2(\Sigma^2)}
	\le k^{O(1)} \begin{cases}
	2^{-k}&\textup{if $\Sigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$,}\\
	2^{-k\epsilon_4}&\textup{if $\Sigma\in\{\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}},
		\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize v}}\}$,}\\
	2^{k(1-\epsilon_4)}
	&\textup{if $\Sigma=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}}$.}
	\end{cases}
	\]
Lastly, it is straightforward to verify (details omitted) that
	\[\frac{\mathrm{Cov}_{\mu_t}(
		\mathbf{1}\{x_v=x\},
		\mathbf{1}\{\sigma_{e'}=\sigma\})}
			{ \mu_v(x) \mu_{e'}(\sigma)}
	\le \frac{k^{O(1)}}{2^k}
	\]
for all 
 $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$,
$e'\in\delta a \setminus e$, and $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$.\smallskip

\noindent\textbf{\textup{Step 4. Estimates on Lagrangian weights.}}
Now recall from 
(9.39)
that derivatives of $\mu_t$-marginals with respect to $b_t$ can be expressed as covariance. Let $\tilde{\mu}_{t+1}$ be defined by
	\[
	\tilde{\mu}_{t+1}
	\Big(x_v,\Sigma_e,\smash{\underline{\smash{\sigma}}}_{\delta a\setminus e}\Big)	
	=
	\frac1{\tilde{Z}_{t+1}}
	b_{v,t}(x)
	(b_{e,t+1})^1((\Sigma_e)^1)
	(b_{e,t})^2((\Sigma_e)^2)
	\prod_{e'\in\delta a\setminus e}
		b_{e',t}(\sigma_{e'})\,,
	\]
where $\tilde{Z}_{t+1}$ is the normalizing constant. It follows from the update rule (9.62) that
the marginal of $\tilde{\mu}_{t+1}$ on $(\Sigma_e)^1$
is exactly the desired marginal $(\mu_e)^1$. Consequently,
	\begin{align*}
	\delta_{t+1}(\Sigma^1) &\equiv \bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}{(\mu_e)^1(\Sigma^1)}-1
	\bigg|
	=\bigg|
	\frac{(\mu_{e,t+1})^1(\Sigma^1)}
		{(\tilde{\mu}_{e,t+1})^1(\Sigma^1)}-1\bigg|
	\\
	&\le
	\frac1{(\mu_e)^1(\Sigma^1)}
	O\Bigg(
	\sum_x
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{v,t+1}(x)}
	\bigg| \frac{b_{v,t+1}(x)}{b_{v,t}(x)}-1\bigg|
	+\sum_{\Sigma^2}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln (b_{e,t+1})^2(\Sigma^2)}
	\bigg| \frac{(b_{e,t+1})^2(\Sigma^2)}
		{(b_{e,t})^2(\Sigma^2)}
	-1\bigg|
	\\
	&\qquad\qquad\qquad\qquad\qquad\qquad\qquad
	+\sum_{e',\sigma}
	\frac{\partial\mu_{e,t+1}(\Sigma^1)}
		{\partial\ln b_{e',t+1}(\sigma)}
		\bigg|
		\frac{b_{e',t+1}(\sigma)}
			{b_{e',t}(\sigma)}-1\bigg|
	\Bigg)\,.
	\end{align*}
Substituting the preceding covariance estimates into the last bound and applying (9.64) gives
	\begin{align*}
	\delta_{t+1}(\textup{\texttt{\footnotesize w}})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}} \cdot
	(\mu_e)^2(\textup{\texttt{\footnotesize v}})
	\cdot
	\bigg|\frac{(b_{e,t+1})^2(\textup{\texttt{\footnotesize v}})}
		{(b_{e,t})^2(\textup{\texttt{\footnotesize v}})}-1 \bigg|
	\Bigg\}\\
	&\le k^{O(1)}\Bigg\{
	\frac1{2^k}
	\cdot
	\frac{1}{2^k(2^{k\epsilon_4/2})^t}
	+	\frac1{2^{k\epsilon_4}}
	\cdot \frac1{2^k}
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le \frac{k^{O(1)}}{2^k(2^{k\epsilon_4/2})^{t+2}}\,,\\
	\delta_{t+1}(\textup{\texttt{\footnotesize v}})
	&\le
	k^{O(1)}\Bigg\{
	\frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	+ 2^{k(1-\epsilon_4)}
	\cdot(\mu_e)^2(\textup{\texttt{\footnotesize v}})
	\cdot \frac1{2^{k\epsilon_4}((2^{k\epsilon_4/2})^t}
	\Bigg\}
	\le 
	\frac{k^{O(1)}}{2^{k\epsilon_4}(2^{k\epsilon_4/2})^{t+2}}\,.
	\end{align*}
This verifies the inductive hypothesis (9.63) for the quantities
	\[
	\delta_{t+1}(\Sigma^i)
	= \bigg|\frac{(\mu_{e,t+1})^i(\Sigma^i)}
		{(\mu_e)^i(\Sigma^i)}-1\bigg|\,.
	\]
The remaining estimates in (9.63) follow by similar calculations (details omitted). It follows that as $t\to\infty$ the weights $b_t$ converge to the desired limiting weights $b_\infty\equiv b$ that define the optimal measure $\mu$ in (9.55). It then follows from the bound (9.64) that
	\begin{align*}
	\mu_e(\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})
	&\stackrel{(9.55)}{=}
	O\Bigg(
	b_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	\Bigg\{\prod_{i=1,2} (b_e)^i(\textup{\texttt{\footnotesize v}})\Bigg\}
	\Bigg\{ \prod_{e'\in\delta a\setminus e}
		b_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Bigg\}
		\Bigg)\\
	&\stackrel{(9.64)}{=}
	O\Bigg(
	\mu_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	\prod_{i=1,2}\Big(
	(\mu_e)^i(\textup{\texttt{\footnotesize v}}) 2^K\Big)
	\prod_{e'\in\delta a\setminus e}
		\mu_{e'}(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\Bigg)
	\stackrel{(9.57)}{\le}
	\frac1{2^{k(1+\epsilon_4)}}\,,
	\end{align*}
as claimed.
\end{proof}

Suppose $v$ is a non-defective variable of type $\bm{T}$, satisfying the bounds $\pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	=\pi_{\bm{T}}(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})\ge 2^{-k/16}$ and
	\begin{equation}
	\cancel{\mathbb{D}}(v)
	\stackrel{(9.4)}{=}
	\sum_{\bm{t}\in\bm{T}}\sum_{\bm{L}}
	\mathbf{1}\{\bm{L}\notin\mathbb{D}\}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t})
	\le 2^k\,.
	\end{equation}
Then, for every edge $e\in\delta v(\textup{\texttt{\footnotesize +}})$, we have (with $\epsilon_4$ as in Lemma~9.10) the bound
	\[
	\max_{\bm{L},j}
	\bigg\{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
	: 
	\textup{$\bm{L}\in\mathbb{D}$
	with $\bm{L}(j)=\bm{t}_e$}
	\bigg\}
	\le \frac1{2^{k(1+\epsilon_4)}}\,.
	\]
The same statement holds if we replace $\textup{\texttt{\footnotesize +}}$ with $\textup{\texttt{\footnotesize -}}$ throughout.


\begin{proof} We claim that
	\begin{equation}
	\min\Bigg\{
	\sum_{ e \in\delta v(\textup{\texttt{\footnotesize +}})} 
		\pi_e\Big( \{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}}\}\Big),
	\sum_{ e \in\delta v(\textup{\texttt{\footnotesize +}})} 
		\pi_e\Big( \{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}}\}\Big)
	\Bigg\}
	\ge \frac{k \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})}{300}\,.
	\end{equation}
Let us first note that
(9.66) implies the result of the lemma: indeed, if (9.66) holds,
then condition
(9.43) of Lemma~9.8 is satisfied with $\epsilon_2=1/300$, and applying that lemma gives
	\[
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
	\le \frac{\bm{\varpi}_{\bm{L},j}(\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})}
		{1- 2^{-k\epsilon_3}}
	\le O\Big( \bm{\varpi}_{\bm{L},j}
		(\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})\Big)
	\]
for $j=j(\bm{t})$ and all $\bm{L}$ such that $\bm{L}(j)=\bm{t}$.
If in addition $\bm{L}\in\mathbb{D}$, then
combining with Lemma~9.10 gives
	\[
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}})
	\le O\Big( \bm{\varpi}_{\bm{L},j}
		(\upsilon=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize v}})\Big)
	\le O\bigg( \frac1{2^{k(1+\epsilon_4)}}\bigg)\,.
	\]
Thus it suffices to prove (9.66).\smallskip


\noindent\textbf{\textup{Step 1. Preliminary bounds.}}
 For $e\in\delta v(\textup{\texttt{\footnotesize +}})$ we have $\pi_e(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})= \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})-O(2^{-k})\ge 2^{-k/15}$, so Lemma~9.6 gives
	\[
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
	\ge \frac{\pi_e(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})}8
	\ge \frac18
	\Bigg\{ \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
		-O\bigg(\frac1{2^k}\bigg)
		\Bigg\}
	\]
for all $\bm{L},j$ with $\bm{L}(j)=\bm{t}_e$. Combining with
Lemma~9.5 gives
	\begin{equation}
	\bm{\varpi}_{\bm{L},j}
		\Bigg(
		\hspace{-3pt}\begin{array}{c}\sigma=\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}},\\
		\Sigma=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\end{array}\hspace{-3pt}
		\Bigg)
	\ge \omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
		-O\bigg(\frac{k^2}{2^k}\bigg)
	\ge 
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
	\Big\{ 1-o_k(1)\Big\}
	\,.\end{equation}
Suppose for contradiction that (9.66) fails. Since $v$ is non-defective, it must also be nice (Definition~3.8), so
	\[
	\sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\pi_e\Big(\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize g}}\}\Big)
	\ge \sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	(\pi_e)^1(\textup{\texttt{\footnotesize r}}) - 
		\frac{k \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})}{300}
	\ge \frac{k 2^{k-1} \ln 2}{2^k}
		\Big\{1-o_k(1)\Big\}
	- \frac{ k \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})}{300}
	\ge \frac{k}{3}\,.
	\]
Therefore, it holds for some
$\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}}\}$ that 
	\begin{equation}
	\sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\pi_e(\textup{\texttt{\footnotesize r}}\tau) \ge \frac{k}{6}
	\end{equation}
--- suppose this is the case for $\tau=\textup{\texttt{\footnotesize y}}$. 
Then Lemma~9.9 
(whose condition 
(9.52) 
is satisfied, due to
(9.68)) gives
	\[\bm{\varpi}_{\bm{L},j}
	\Bigg(\hspace{-3pt}
		\begin{array}{c}\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\\
		\upsilon^1=\textup{\texttt{\footnotesize v}}\end{array}\hspace{-3pt}
		\Bigg) 
	\ge \omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	\bigg\{ 1-\frac1{2^{k\epsilon_3}}\bigg\}
	\]
for all $e\in\delta v(\textup{\texttt{\footnotesize +}})$
and all $\bm{L}(j)=\bm{t}_e$. If $\bm{L}$ is also diverse, then combining with Lemma~9.7 gives 
	\begin{equation}
	\bm{\varpi}_{\bm{L},j}
		\Bigg(
		\hspace{-3pt}
		\begin{array}{c}\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\\
		\Sigma=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}
		\end{array}\hspace{-3pt}
		\Bigg) 
	\ge \bm{\varpi}_{\bm{L},j}\Bigg(\hspace{-3pt}
		\begin{array}{c}\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\\
		\upsilon^1=\textup{\texttt{\footnotesize v}}\end{array}\hspace{-3pt}
		\Bigg) 
	-\bm{\varpi}_{\bm{L},j}\Bigg(
		\hspace{-3pt}
		\begin{array}{c}
		\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\\
		\varsigma^1\ne\textup{\texttt{\footnotesize w}},
		\varsigma^2\ne\textup{\texttt{\footnotesize w}}
		\end{array}\hspace{-3pt}
		\Bigg)
	\ge \bm{\varpi}_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
		\bigg\{ 1-\frac1{2^{k\epsilon_3}}\bigg\}
		-\frac1{2^{k(1+\epsilon_1)}}\,.\end{equation}
Note that (9.69) used the assumption that $v$ is non-defective, which implies that $\bm{L}$ is nice (i.e., neighbors only nice variables) whenever $\bm{L}(j)=\bm{t}_e$ for $e\in\delta v$. We now define a probability measure $\bm{\pi}$ on the space of pairs $(e,\bm{L})$, where $e\in\delta v(\textup{\texttt{\footnotesize +}})$ and $\bm{t}_e\in\bm{L}$, such that
	\begin{equation}
	\bm{\pi}(e,\bm{L})
	\equiv
	\frac{\mathbf{1}\{e\in\delta v(\textup{\texttt{\footnotesize +}})\}}
		{|\delta v(\textup{\texttt{\footnotesize +}})|}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)\,.
	\end{equation}
We can equivalently regard $\bm{\pi}$ as a probability measure on pairs $(\bm{t},\bm{L})$ where $\bm{t}=\bm{t}_e$. Now, on this probability space, define the random variable
	\[X\equiv X(e,\bm{L})
	\equiv 
	\mathbf{1}\{\bm{L}\in\mathbb{D}\}
	\frac{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})}
	{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
	\equiv X(\bm{t},\bm{L})\,,\]
and note that $0\le X\le 1$ with probability one.
The expectation of $X$ with respect to $\bm{\pi}$ is
	\begin{align*}
	\mathbf{E}_{\bm{\pi}} X
	&\stackrel{(9.70)}{=}
		\frac1{|\delta v(\textup{\texttt{\footnotesize +}})|}
	\Bigg\{ \sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\frac{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})}
	{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
	-O\Bigg(
	\sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\sum_{\bm{L}}\mathbf{1}\{\bm{L}\notin\mathbb{D}\}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)\Bigg)
	\Bigg\}\\
	&\stackrel{(9.65)}{\ge}
	\frac1{|\delta v(\textup{\texttt{\footnotesize +}})|} \sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\sum_{\bm{L}}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\frac{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})}{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
	- \frac1k
	=\frac1{|\delta v(\textup{\texttt{\footnotesize +}})|} \sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\frac{\pi_e(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})}{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
	- \frac1k\\
	&\stackrel{(9.68)}{\ge} 
	\Big\{ 1-o_k(1)\Big\}
	\frac{2^{k-1} \cdot k/6}{k 2^{k-1}\ln2}
	\ge \frac15\,.
	\end{align*}
On the other hand, since we noted above that $0\le X\le 1$, we have
	\[
	\mathbf{E}_{\bm{\pi}} X
	\le \bm{\pi}\bigg(X \ge \frac1{10}\bigg)
	+ \frac1{10}
	\Bigg\{1-\bm{\pi}\bigg(X \ge \frac1{10}\bigg)\Bigg\}\,,
	\]
and rearranging gives
$\bm{\pi}(X \ge 1/10)\ge 1/9$. On the event $X(e,\bm{L})\ge1/10$, it follows from (9.69) that
	\begin{equation}
	\bm{\varpi}_{\bm{L},j}
	\Bigg(\hspace{-3pt}\begin{array}{c}
		\sigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\\
		\Sigma=\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}\end{array}\hspace{-3pt}
		\Bigg)
	\ge \omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})
	\Big\{1-o_k(1)\Big\}\,.\end{equation}
In the next step we will perform a switching argument between (9.67)
and (9.71).\smallskip


\noindent\textbf{\textup{Step 2. Edge switching argument.}} Let $\mathscr{G}=(V,F,E)$ be any (processed) $\textup{$k$-\textsc{sat}}$ graph. Fix a clause type $\bm{L}$ and index $1\le j\le k(\bm{L})$, and let $E(\bm{L},j)$ denote the subset of all edges
$e=(av)\in E$ such that $\bm{L}_a=\bm{L}$ and $j(\bm{t}_e)=j$. Suppose $\smash{\underline{\smash{\sigma}}}$ is a valid pair coloring on $\mathscr{G}$, and let $\smash{\underline{\smash{\Sigma}}}$ be the corresponding configuration from Definition~9.1. Suppose we have two edges $e=(av)$ and $e'=(a'v')$ in $E(\bm{L},j)$, such that
	\[
	\mathbf{X}_{av} \equiv
	\begin{pmatrix} \sigma_{av}\\
		\Sigma_{av}\end{pmatrix}
	= \begin{pmatrix} \textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}} \\
		\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\end{pmatrix}
	\equiv A_1\,,\quad
	\mathbf{X}_{a'v'}
	\equiv\begin{pmatrix} \sigma_{a'v'}\\
		\Sigma_{a'v'}\end{pmatrix}
	= \begin{pmatrix} \textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}} \\
		\textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}\end{pmatrix}
	\equiv A_2\,.
	\]
If we cut the edges $e,e'$ and form new edges 
$(a'v)$, $(av')$, then a valid configuration
$(\smash{\underline{\smash{\sigma}}}',\smash{\underline{\smash{\Sigma}}}')$ on the switched graph $\mathscr{G}'$ is given by setting
	\[\mathbf{X}_{a'v}
	\equiv\begin{pmatrix} \sigma_{a'v}\\
		\Sigma_{a'v}\end{pmatrix}
	= \begin{pmatrix}
		\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}}\\ \textup{\texttt{\footnotesize v}}\textup{\texttt{\footnotesize w}}\end{pmatrix}
	\equiv B_1\,,\quad
	\mathbf{X}_{av'}
	\equiv\begin{pmatrix} \sigma_{av'}\\
		\Sigma_{av'}\end{pmatrix}
	=\begin{pmatrix}\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}} \\
		\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\end{pmatrix}
	\equiv B_2\,,
	\]
keeping all other colors unchanged. Moreover, the switching preserves all single-copy marginals, 
so $\smash{\underline{\smash{\sigma}}}'$ is a judicious configuration on $\mathscr{G}'$.
If $X(\bm{t},\bm{L})\ge1/10$ for $\bm{t}=\bm{L}(j)$, then
	\begin{align*}
	p(A_1)
	&\equiv
	\frac{|\{e \in E(\bm{L},j) : \mathbf{X}_{av}=A_1\}|}
		{|E(\bm{L},j)|}
	\stackrel{(9.67)}
	{\ge} \bigg\{1-o_k(1)\bigg\}
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})\,,\\
	p(A_2)
	&\equiv
	\frac{|\{e \in E(\bm{L},j) : \mathbf{X}_{av}=A_2\}|}
		{|E(\bm{L},j)|}
	\stackrel{(9.71)}{\ge}\bigg\{1-o_k(1)\bigg\}
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})\,.\end{align*}
Suppose $\bm{\varpi}$ (the empirical measure on the augmented spins $(\sigma,\Sigma)$) gives the maximal 
second moment contribution $\mathbb{E}_{\mathscr{D}}\bm{Z}^2(\bm{\varpi})$, 
subject to the restriction that its projection $\omega$ lies in $I_0$. Let $\bm{\Omega}$ denote the space of all (valid) pairs $(\mathscr{G},\smash{\underline{\smash{\sigma}}})$ that are 
consistent with this $\bm{\varpi}$, and consider the probability measure
	\[
	\mathbf{P}(\mathscr{G},\smash{\underline{\smash{\sigma}}})
	= \frac{\mathbb{P}_{\mathscr{D}}(\mathscr{G}) \mathbf{1}\{(\mathscr{G},\smash{\underline{\smash{\sigma}}})\in\bm{\Omega}\}}
		{\mathbb{E}_{\mathscr{D}} \bm{Z}^2(\bm{\varpi})}\,.
	\]
Let $(\mathscr{G},\smash{\underline{\smash{\sigma}}})\in\bm{\Omega}$ be sampled according to measure $\mathbf{P}$, and define the subsets of edges
	\begin{align*}
	E_A&\equiv E_A(\mathscr{G},\smash{\underline{\smash{\sigma}}})
	\equiv
	\bigg\{e\in E(\bm{L},j): \bm{X}_e \in\{A_1,A_2\}\bigg\}\,,\\
	E_B&\equiv E_B(\mathscr{G},\smash{\underline{\smash{\sigma}}})
	\equiv
	\bigg\{e\in E(\bm{L},j): \bm{X}_e \in\{B_1,B_2\}\bigg\}\,.
	\end{align*}
If we rematch the edges within $E_A$, and
also rematch the edges within $E_B$ (uniformly at random), the resulting $(\mathscr{G}',\smash{\underline{\smash{\sigma}}}')$ will also be distributed roughly according to $\mathbf{P}$. The number of $B_1$-edges in $(\mathscr{G}',\smash{\underline{\smash{\sigma}}}')$
is lower bounded by the number of switched edges from $E_A(\mathscr{G},\smash{\underline{\smash{\sigma}}})$, so we conclude
	\[
	\frac{p(B_1)}{1-o_n(1)}
	\ge
	\frac{|E_A(\mathscr{G},\smash{\underline{\smash{\sigma}}})|}{|E(\bm{L},j)|}
	\frac{p(A_1) p(A_2)}{p(A_1)+p(A_2)}
	\ge
	\Big\{1-o_n(1)\Big\}
	p(A_1) p(A_2)\,.
	\]
Recalling the definition of the $A_i,B_i$, the above can be rewritten as
	\[\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	\ge \frac{\omega_{\bm{L},j}(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}})
		\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}})}{1+o_k(1)}
	\ge \frac{\pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}{11}\,,
	\]
where the last step uses the assumption that $X(\bm{t},\bm{L})\ge 1/10$. It follows that
	\begin{align*}
	\sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}\pi_e(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})
	&\ge\sum_{e\in\delta v(\textup{\texttt{\footnotesize +}})}
	\sum_{\bm{L}}
	\mathbf{1}\bigg\{X(e,\bm{L})\ge \frac1{10}\bigg\}
	\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e) 
	\omega_{\bm{L},j}(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}})\\
	&= |\delta v(\textup{\texttt{\footnotesize +}})|
	\bm{\pi}\bigg(X \ge \frac1{10}\bigg) 
	\frac{\pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}{11}
	\ge \frac{k2^{k-1}\ln2}{9[1-o_k(1)]}
	\frac{\pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})}{11 \cdot 2^k}
	\ge \frac{k \pi_v(\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}})}{300}\,,
	\end{align*}
proving (9.66). A very similar argument proves (9.66) in the case that (9.68) holds for $\tau=\textup{\texttt{\footnotesize g}}$ instead of $\tau=\textup{\texttt{\footnotesize y}}$. As explained above, 
(9.66) implies the lemma, so this concludes the proof.
\end{proof}

In the notation of Lemma~9.11,
suppose $v$ is a non-defective variable with $\cancel{\mathbb{D}}(v)=\cancel{\mathbb{L}}(v)=0$. Then for every $e\in\delta v$, and every
$\bm{L}\ni_j\bm{t}_e$ we have 
	\begin{equation}
	\bigg|\frac{\omega_{\bm{L},j}(\sigma)}
	{{}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\sigma^1){}_\star\hspace{-1pt}\pi_{\bm{L}(j)}(\sigma^2)}
	-1\bigg| \le \frac{k^{O(1)}}{2^{k\epsilon_\circ}}\,,
	\end{equation}














for all $\sigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$ and all $\bm{L}$,
with $\epsilon_\circ$ as in Lemma~9.7.

Let $\mathscr{G}'$ be the random $\textup{$k$-\textsc{sat}}$ instance, and $\mathscr{G}=\textup{\textsf{pr}}\mathscr{G}'$ the processed graph, with neighborhood profile $\mathscr{D}$. Recall Lemma~3.42, and let
	\begin{equation}
	\omega(\mathscr{D})
	\in
	\textup{arg\,max}_\omega
	\Bigg\{
	\bm{\Psi}_{\mathscr{D},2}(\omega)
	:\omega\in\bm{I}_0
	\Bigg\}\,.
	\end{equation}
(We do not yet argue that $\omega(\mathscr{D})$ is unique;
that will be shown in the \hyperlink{p:second.moment.judicious.proof}{proof of 
Proposition~3.32}.) There exists an absolute constant $\zeta_*>0$ such that if $\mathscr{D}$ expands on type-subsets
in the sense of Definition~8.2, then
any maximizer $\omega(\mathscr{D})$ must satisfy the \textup{``a~priori''} bounds
	\begin{equation}
	\Bigg|
		\frac{\omega_{\bm{L},j}(\sigma)}
		{{}_{*}\omega_{\bm{L},j}(\sigma)}
		- 1 \Bigg| \le
		\begin{cases}
		2^{-k\zeta_*}& \textup{if $\textup{\texttt{\footnotesize r}}[\sigma]\le1$,}\\
		2^{k(1-\zeta_*)}&\textup{if $\textup{\texttt{\footnotesize r}}[\sigma]=2$.}
		\end{cases}
	\end{equation}
whenever $\bm{L}(j)$ is a strongly non-defective edge type in the sense of Remark~6.5.

For any $\epsilon_\infty>0$ there exists $k_0<\infty$ large enough (depending only on $\epsilon_\infty$) such that the following holds for all $k\ge k_0$. Suppose $v$ is a non-defective variable such that (in the notation of Lemma~9.11)
	\begin{equation}
	\max\Big\{\cancel{\mathbb{D}}(v),
		\cancel{\mathbb{L}}(v)\Big\}
		\le \frac{2^k}{2^{k\epsilon_\infty}}\,.
	\end{equation}
Then $v$ is diverse (Definition~9.3), and furthermore $\pi_v$ satisfies the estimate
	\begin{equation}
	\max\Bigg\{\bigg|\pi_v(x)-\frac14\bigg|
	: x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}^2
	\Bigg\}\le\frac1{100}\,.\end{equation}

\begin{proof} Without loss of generality we can assume that $\epsilon_\infty$ is much smaller than the other constants 
$\epsilon_1,\epsilon_2,\epsilon_3,\epsilon_4,\epsilon_\circ$ appearing in this section.

We will prove the result by contradiction, so let $v$ be a variable of type $\bm{T}$ which satisfies the conditions of the proposition, but for which the estimate~(9.119) fails to hold. It will be used repeatedly in the proof that since $v$ is non-defective (Definition~3.10), it must be nice, and all clause types neighboring to $v$ must also be nice (Definition~3.8). As in (9.76) and (9.77) we let $X_e\equiv(\sigma_e,\varsigma_e)$. We also denote $\mathcal{X}_e\equiv(X_e,\bm{L}_e)$. We consider the law $\mathbf{P}$ of the random variable 
	\[
	\mathcal{X} \equiv \mathcal{X}_v \equiv (\mathcal{X}_e)_{e\in\delta v}
	\equiv (\smash{\underline{\smash{X}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})
	\equiv\bigg((X_e)_{e\in\delta v}, 
	(\bm{L}_e)_{e\in\delta v}\bigg)\,.\]
The measure $\mathbf{P}$ must maximize entropy subject to the following constraints (cf.\ (9.78)--(9.80)):
for all $e\in\delta v$, 
	{\setlength{\jot}{0pt}\begin{alignat}{2}
	\mathbf{P}(\bm{L}_e=\bm{L})
	&=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
	\quad&&\textup{for all $\bm{L}$,}
	 \\ 
	\mathbf{P}(\sigma^i_e=\sigma^i \,|\,
		\bm{L}_e=\bm{L})
	&= {}_\star\hspace{-1pt}\pi_e(\sigma^i)
	\quad&&\textup{for all $\bm{L}$ and
		 all $\sigma^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$,}
	 \\
	\mathbf{P}(\varsigma_e=\varsigma
		\,|\,\bm{L}_e=\bm{L})
	&=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\quad&&\textup{for all $\bm{L}$
		and all $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$.}

	\end{alignat}}
Via a series of transformations of the measure $\mathbf{P}$ we will construct another distribution $\mathbf{P}^f$ satisfying the same constraints
(9.120)--(9.122) but with higher entropy, yielding the required contradiction. The remainder of the proof is outlined as follows:
\begin{enumerate}[--]
\item In \hyperlink{l:DIVERSE.product.Pa}{Part 1}
we define a measure $\mathbf{P}^a$ satisfying
constraints (9.120), (9.121), and 
(9.123), where
(9.123) is a relaxation of
(9.122). We show that $\mathbf{P}^a$ has a simple explicit form, and has substantially larger entropy than $\mathbf{P}$ (see (9.132) below).


\item In \hyperlink{l:DIDERSE.Pa.bounds}{Part 2} we prove probabilistic estimates on various quantities under the measure $\mathbf{P}^a$. Let $\mathcal{X}^a$ denote a sample from $\mathbf{P}^a$; in the rest of the proof we transform $\mathcal{X}^a$ without changing its frozen spin $x=x^a\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$.

\item In \hyperlink{l:DIVERSE.Pb}{Part 3} we transform $\mathcal{X}^a$ into $\mathcal{X}^b$, and in \hyperlink{l:DIVERSE.Pc}{Part 4} we transform $\mathcal{X}^b$ into $\mathcal{X}^c$. In these transformations, $(\varsigma_e)^i$ can only change between \textup{\texttt{\footnotesize red}} and \textup{\texttt{\footnotesize white}}, so any $(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ remains unchanged. The transformations combined will guarantee (see (9.160) below) that in the configuration $\mathcal{X}^c$, if $x=x^c$ has $x^i=z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$, then some $e\in\delta v(z)$ will have $(\sigma^{c,i})_e=\textup{\texttt{\footnotesize r}}$, $(\sigma^c)_e\ne\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$, and $(\bm{L}^c)_e\in\mathbb{D}\cap\mathbb{L}$. The condition (9.160) will allow more flexibility to change spins from non-\textup{\texttt{\footnotesize white}} to \textup{\texttt{\footnotesize white}} in the following step. The law $\mathbf{P}^c$ of $\mathcal{X}^c$ satisfies
(9.120), but need not satisfy
(9.121) or (9.122), in particular, it can have less than the correct density of \textup{\texttt{\footnotesize red}} spins (see (9.172)
and (9.173)).

\item In \hyperlink{l:DIVERSE.Pd}{Part 5} we transform $\mathcal{X}^c$ to $\mathcal{X}^d$ by changing $(\varsigma^{c,i})_e\ne\textup{\texttt{\footnotesize w}}$ to $(\varsigma^{d,i})_e=\textup{\texttt{\footnotesize w}}$ in some cases --- the condition (9.160) from the previous step allows more flexibility to do this without invalidating the configuration. The goal of this step is to create enough \textup{\texttt{\footnotesize white}} spins which can be altered in the next step to ensure that the constraints (9.121) or (9.122) will be satisfied.
At the same time, we cannot change too many spins to \textup{\texttt{\footnotesize white}}, since this could result in too much decrease in entropy.

\item In \hyperlink{l:DIVERSE.Pe}{Part 6} we transform
$\mathcal{X}^d$ to $\mathcal{X}^f$, where we use $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. In this final step we change
 $(\varsigma^{d,i})_e=\textup{\texttt{\footnotesize w}}$
to $(\varsigma^{f,i})_e\ne\textup{\texttt{\footnotesize w}}$ in some cases, such that the law $\mathbf{P}^f$ of $\mathcal{X}^f$ satisfies the original constraints
(9.120)--(9.122)
(see (9.182) below).
Finally we show that $\mathbf{P}^f$ does not have much smaller entropy than $\mathbf{P}^a$, and as a result must have substantially larger entropy than $\mathbf{P}$, giving the contradiction.
\end{enumerate}
We now turn to the details of the transformation.\smallskip




\noindent\textbf{\textup{\hypertarget{l:DIVERSE.product.Pa}{Part 1}. Product solution $\mathbf{P}^a$ for relaxed constraints.}} Let $\mathbf{P}^a$ be the probability measure over configurations $\mathcal{X}$ which maximizes entropy subject to the constraints (9.120), (9.121), and (in place of (9.122))
	\begin{equation}
	\mathbf{P}^a(\varsigma_e^i=\varsigma^i
			\,|\,\bm{L}_e=\bm{L})
		=\bm{\zeta}_e(\varsigma^i\,|\,\bm{L})
		\quad\textup{for all $\bm{L}$
			and all
			$\varsigma^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}$.}
	\end{equation}
Let us note that the law $\mathbf{P}^a$ has a quite simple form: by the method of Lagrange multipliers, it must be expressible as
(cf.\ (9.81))
	\begin{equation}
	\mathbf{P}^a\Big(
	\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\varsigma}}}_{\delta v},
	\smash{\underline{\smash{\bm{L}}}}_{\delta v} \Big)
	\cong \psi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}
	\Bigg\{
	\mathbf{1}\{\sigma_e\sim\varsigma_e\}
	\psi_e(\bm{L}_e)
	\prod_{i=1,2}
	\bigg[
	(\beta_e)^i((\sigma_e)^i\,|\,\bm{L}_e)
	(\chi_e)^i( (\varsigma_e)^i\,|\,\bm{L}_e)
	\bigg]
	\Bigg\}\,,
	\end{equation}
where $\psi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})$ is parametrized as in
(7.55) from Definition~7.24. A valid solution is given by simply setting $\psi_v\equiv1$,
$\psi_e(\bm{L})=\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)$,
and (cf.\ (9.84) and (9.85))
	\begin{align*}
	\begin{pmatrix}
	(\beta_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})\\
	(\beta_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})\\
	(\beta_e)^i(\textup{\texttt{\footnotesize g}}\,|\,\bm{L})
	=(\beta_e)^i(\textup{\texttt{\footnotesize b}}\,|\,\bm{L})\equiv(\beta_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})
	\end{pmatrix}
	&= 
	\begin{pmatrix}
	1\\
	[{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize y}})\\
	[{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize c}})-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})]/{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize c}})
	\end{pmatrix}
	\stackrel{(9.82)}{=} 
	\begin{pmatrix}
	\Theta(1)\\ \Theta(1) \\ \Theta(1)
	\end{pmatrix}\,,\\

	\begin{pmatrix}
	(\chi_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})\\
	(\chi_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})\\
	(\chi_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})\\
	(\chi_e)^i(\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
	\end{pmatrix}
	&=\begin{pmatrix}
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})/{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize r}})\\
	(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})
		/[{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})]\\
	(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})
	/[{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize c}})
		-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})]\\
	1
	\end{pmatrix}
	\stackrel{(9.82)}{=} 
	\begin{pmatrix}
	\Theta(1/2^k)\\
	O(k^2/2^k)\\
	O(k^2/2^k)\\
	1
	\end{pmatrix}
	\,,\end{align*}
where the estimates on
$(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})$
for $\tau\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ come from Lemma~9.5. Note that for $e\in\delta v$, $\bm{L}=\bm{L}_e$, $i=1,2$, and $\sigma^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$ we have
	\begin{equation}
	(\hat{q}_e)^i(\sigma^i\,|\,\bm{L})\equiv
	(\beta_e)^i(\sigma^i\,|\,\bm{L})
	\sum_{\varsigma^i}
	\mathbf{1}\{\varsigma^i \sim \sigma^i\}
	(\chi_e)^i(\varsigma^i\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\sigma^i)}{{}_\star\hspace{-1pt}\dot{q}_e(\sigma^i)}\,,
	\end{equation}
where we emphasize that the right-hand side of (9.125) does not depend on $\bm{L}$. Indeed,
	\[
	(\hat{q}_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})
	= (\beta_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})
	(\chi_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})
	= \frac{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}{{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize r}})}\,,
	\]
which verifies (9.125) for the case $\sigma^i=\textup{\texttt{\footnotesize r}}$. Next,
	\begin{align*}
	(\hat{q}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})
	&= (\beta_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})
	\bigg(
	(\chi_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})
	+(\chi_e)^i(\textup{\texttt{\footnotesize w}}\,|\,\bm{L})\bigg)\\
	&= \frac{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize y}})}
	\cdot\Bigg\{
	\frac{(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})-(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}+1
	\Bigg\}
	= \frac{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})}{{}_\star\hspace{-1pt}\dot{q}_e(\textup{\texttt{\footnotesize y}})}\,,
	\end{align*}
which verifies (9.125) for the case $\sigma^i=\textup{\texttt{\footnotesize y}}$. A similar calculation gives
(9.125) for $\sigma^i\in\{\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$. It follows from (9.125),
together with the identity ${}_\star\hspace{-1pt}\pi_e(\tau)/{}_\star\hspace{-1pt}\dot{q}_e(\tau) \cong {}_\star\hspace{-1pt}\hat{q}_e(\tau)$,
that the marginal of (9.124) over
$(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v})$ is given by
	\begin{align}
	\mathbf{P}^a\Big(\smash{\underline{\smash{\sigma}}}_{\delta v},\smash{\underline{\smash{\bm{L}}}}_{\delta v}\Big)
	&\cong
	\varphi_v(\smash{\underline{\smash{\sigma}}}_{\delta v})
	\prod_{e\in\delta v}\Bigg\{
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\prod_{i=1,2}
	{}_\star\hspace{-1pt}\hat{q}_e((\sigma_e)^i)\Bigg\} \\
	& \cong
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\underline{\smash{\sigma}}}_{\delta v})^1)
	{}_\star\hspace{-1pt}\dot{\nu}_v((\smash{\underline{\smash{\sigma}}}_{\delta v})^2)
	\prod_{e\in\delta v}
	\pi_{\mathscr{D}}(\bm{L}_e\,|\,\bm{t}_e)
	\,,
	\end{align}
where ${}_\star\hspace{-1pt}\dot{\nu}_v$ is as in 
(3.56). In particular, we see that under $\mathbf{P}^a$,
the random variables $(\smash{\underline{\smash{\sigma}}}_{\delta v})^1$, $(\smash{\underline{\smash{\sigma}}}_{\delta v})^2$, and $\smash{\underline{\smash{\bm{L}}}}_e$ (for $e\in\delta v$) are mutually independent. Moreover, conditional on $(\smash{\underline{\smash{\sigma}}},\smash{\underline{\smash{\bm{L}}}})_{\delta v}$, 
the $(\varsigma_e)^i$ are all independent from one another, with conditional laws depending only on
 $(\bm{L}_e,(\sigma_e)^i)$. If $(\sigma_e)^i=\textup{\texttt{\footnotesize r}}$ then $(\varsigma_e)^i= \textup{\texttt{\footnotesize r}} $ also. 
If $(\sigma_e)^i=\textup{\texttt{\footnotesize y}}$ then $(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\}$; and the conditional probability of 
$(\varsigma_e)^i=\textup{\texttt{\footnotesize y}}$ is given by
	\begin{equation}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i= \textup{\texttt{\footnotesize y}}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\textup{\texttt{\footnotesize y}}
	\bigg)
	= \frac{(\chi_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}
	{(\chi_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})+(\chi_e)^i(\textup{\texttt{\footnotesize w}}\,|\,\bm{L})}
	= \frac{(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize y}}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)\,,
	\end{equation}
where the last inequality follows by
Lemma~9.5. Similarly, if $(\sigma_e)^i =\tau\in\{\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$ then
$(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}$; and the conditional probability of $(\varsigma_e)^i=\textup{\texttt{\footnotesize c}}$ is given by
	\begin{equation}
	\mathbf{P}^a
	\bigg( (\varsigma_e)^i=\textup{\texttt{\footnotesize c}}
	\,\bigg|\,
	\bm{L}_e=\bm{L}, (\sigma_e)^i=\tau
	\bigg)
	= \frac{(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize c}}\,|\,\bm{L})}
		{{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize b}})+{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize g}})}
	\le O\bigg(\frac{k^2}{2^k}\bigg)
	\end{equation}
for $\tau\in\{\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$. The independence between the two copies $i=1,2$ gives furthermore
	\begin{equation}
	\mathbf{P}^a\bigg(\varsigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	= \prod_{i=1}^2 \mathbf{P}^a\bigg(
		(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg) 
	\le O\bigg( \frac{k^4}{4^k}\bigg)\,.
	\end{equation}
Note also that if $x=x_v\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ is the frozen spin, then $x^1$ and $x^2$ are independent under $\mathbf{P}^a$, and the marginal law of each $x^i$ is determined by the ${}_\star\hspace{-1pt}\pi_e$ for $e\in\delta v$.
Since we assumed that $v$ is non-defective, it follows that
	\begin{equation}
	\max\Bigg\{
	\bigg|\mathbf{P}^a\Big( x =z \Big)
		 -\frac14\bigg|
		: z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}^2
		\Bigg\} =o_k(1)\,.
	\end{equation}
If $\mathbf{P}'$ is any other probability measure satisfying the same constraints as $\mathbf{P}^a$ (namely (9.120), (9.121), and (9.123)), then
it follows by the same derivation as
for (8.9) that
the relative entropy between $\mathbf{P}'$ and $\mathbf{P}^a$ 
satisfies
	\begin{equation}
	\mathcal{H}(\mathbf{P}'\,|\,\mathbf{P}^a)
	= \bigg\langle \mathbf{P}',\ln \frac{\mathbf{P}'}{\mathbf{P}^a}
		\bigg\rangle
	=\mathcal{H}(\mathbf{P}^a) -\mathcal{H}(\mathbf{P}')\,.
	\end{equation}
Now suppose that $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ is the frozen spin corresponding to $\mathcal{X}\sim\mathbf{P}$ (meaning that its law fails condition (9.119)), while $x^a\equiv(x^{a,1},x^{a,2})\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ is the frozen spin corresponding to $\mathcal{X}^a\sim\mathbf{P}^a$ (so that its law satisfies condition 
(9.130)). Therefore we obtain
	\begin{equation}
	\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a) \ge
	\mathcal{D}_\textup{KL}(x\,|\,x^a)
	\ge \frac1{10^6}\,.
	\end{equation}
It follows by combining the last few calculations that
	\begin{equation}
	\mathcal{H}(\mathbf{P}^a)
	\stackrel{(9.131)}{=}
	\mathcal{H}(\mathbf{P})
	+\mathcal{H}(\mathbf{P}\,|\,\mathbf{P}^a)
	\stackrel{(9.132)}{\ge}
	\mathcal{H}(\mathbf{P})
	+\frac1{10^6}\,.
	\end{equation}
In the remainder of the proof we will make a sequence of transformations, from $\mathbf{P}^a$ to $\mathbf{P}^b$ and so on, until we arrive at a measure
$\mathbf{P}^f$ that satisfies the original constraints (9.120)--(9.122). We will show that
none of the transformations substantially reduce the entropy. Thus the final measure $\mathbf{P}^f$
will have similar entropy as $\mathbf{P}^a$, and hence will have greater entropy than $\mathbf{P}$ by (9.132). But we assumed $\mathbf{P}$ to be the measure of maximal entropy satisfying constraints (9.120)--(9.122), so this will give the desired contradiction. The measures $\mathbf{P}^a$ through $\mathbf{P}^f$ will all be coupled together, and the frozen spin $x$ will be left unchanged throughout the transformations.\smallskip

\noindent\textbf{\textup{\hypertarget{l:DIDERSE.Pa.bounds}{Part 2}. Bounds on $\mathbf{P}^a$.}} Using the assumed bound (9.118) on $\cancel{\mathbb{D}}(v)$ and $\cancel{\mathbb{L}}(v)$, we can select a subset of four distinct edges incident to $v$,
	\begin{equation}
	\bm{E}\equiv
	\bigg\{e^{\textup{\texttt{\footnotesize +}},1},e^{\textup{\texttt{\footnotesize +}},2},
	e^{\textup{\texttt{\footnotesize -}},1},e^{\textup{\texttt{\footnotesize -}},2}\bigg\}
	\subset \delta v\,,\end{equation}
where $e^{\textup{\texttt{\footnotesize +}},i}\in\delta v(\textup{\texttt{\footnotesize +}})$,
and $e^{\textup{\texttt{\footnotesize -}},i}\in\delta v(\textup{\texttt{\footnotesize -}})$,
such that each $e\in\bm{E}$ satisfies
	\begin{equation}
	\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e) 
		\mathbf{1}\{\bm{L}\in \mathbb{D}\cap\mathbb{L}\}
		\ge\frac12\,.\end{equation}
For a configuration $\mathcal{X}$ as in (9.77), we define the following quantities:
	\begin{align*}
\mathfrak{R}^i&\equiv
	\mathfrak{R}^i(\mathcal{X})
	\equiv \sum_{e\in\delta v\setminus \bm{E}}
	\mathbf{1}\Big\{
	(\sigma_e)^i=\textup{\texttt{\footnotesize r}}
	\Big\}\,,\\
\mathfrak{H}
	&\equiv\mathfrak{H}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
	\sum_{i=1,2}
	\mathbf{1}\Big\{
	(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
	\Big\}\,,\\
	\mathfrak{W}
	&\equiv \mathfrak{W}(\mathcal{X})
	\equiv\sum_{e\in\delta v\setminus \bm{E}} 
		\mathbf{1}\Big\{
		\varsigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}},
		\bm{L}_e \in \mathbb{D}\cap\mathbb{L}
		\Big\}\,,\\
	T&\equiv T(\mathcal{X})
		\equiv\mathbf{1}
		\bigg\{\mathfrak{W}(\mathcal{X})
			\le \bigg(1-\frac1{k^{10}}\bigg)
				|\delta v|\bigg\}\,.
	\end{align*}
We now prove some straightforward probabilistic bounds (under the measure $\mathbf{P}^a$) for the above quantities. For $e\in\delta v$ let $R_e$ denote independent Bernoulli random variables with
	\begin{equation}
	\mathbb{P}(R_e=1) 
	= \frac{{}_\star\hspace{-1pt}\hat{q}_e(\textup{\texttt{\footnotesize r}})}{{}_\star\hspace{-1pt}\hat{q}_e(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\})}
	= \Theta\bigg(\frac1{2^k}\bigg)\,.\end{equation}
We see from (9.126) that under $\mathbf{P}^a(\cdot\,|\,x^i=\textup{\texttt{\footnotesize +}})$, the total number of edges $e\in\delta v$ with $(\sigma_e)^i=\textup{\texttt{\footnotesize r}}$ is equidistributed as the sum of $R_e$ over $e\in\delta v(\textup{\texttt{\footnotesize +}})$, conditioned on that sum being strictly positive. Therefore
	\begin{align}
	\mathbf{P}^a\Bigg(
		\sum_{i=1,2}\mathfrak{R}^i\ge
		\frac{k^3}{2} \Bigg)
	&\le \mathbf{P}^a \Bigg(
	\sum_{i=1,2}
	\sum_{e\in\delta v} \mathbf{1}\{(\sigma_e)^i=\textup{\texttt{\footnotesize r}}\}
	\ge \frac{k^3}{2} \Bigg)
	\le O(1)\max_{z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}}
	\Bigg\{
	\frac{\mathbb{P}( \sum_{e\in\delta v(z)} R_e \ge k^3/4)}
		{\mathbb{P}(\sum_{e\in\delta v(z)} R_e \ge1)}
		\Bigg\}\\
	&\le\frac{\exp(-\Omega(k^3\ln k))
	}{1-o_k(1)}
	\le \frac1{\exp(\Omega(k^3\ln k))}\,,

	\end{align}
where the second-to-last inequality follows by a Chernoff bound. Next recall from (9.127) and 
(9.128) that
under $\mathbf{P}^a$, conditional on 
$(\sigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}$, the chance for $(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$
is $O(k^2/2^k)$. Thus, under $\mathbf{P}^a$,
the total number of edges $e$ with $(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ for either $i=1,2$ is stochastically dominated by a binomial random variable with $\Theta(k2^k)$ trials
and success probability $\Theta(1/2^k)$. It follows by another Chernoff bound, and by combining with (9.137), that
	\begin{equation}
	\mathbf{P}^a\Big(\mathfrak{H} \ge k^3\Big)
	\le \mathbf{P}^a\Bigg(
		\sum_{e\in\delta v}\sum_{i=1,2}
		\mathbf{1}\Big\{
		(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
		\Big\} \ge k^3
		\Bigg)
	\le\frac1{\exp(\Omega(k^3\ln k))}\,.\end{equation}
Next recall from (9.126)
that the $\bm{L}_e$ for $e\in\delta v$ are mutually independent under $\mathbf{P}^a$. The assumption (9.118) bounds the expected number (under $\mathbf{P}^a$) of edges $e\in\delta v$ with $\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}$. It follows by Azuma's inequality that
	\begin{equation}
	\mathbf{P}^a
	\Bigg(\sum_{e\in\delta v}
	\mathbf{1}\{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}\}
	\ge \frac{k2^k}{2^{k\epsilon_\infty}} \Bigg)
	\le 
	\frac1{\exp (\Omega(2^{k(1-2\epsilon_\infty)}k))}\,.\end{equation}
Combining with (9.138), 
and recalling the definitions of $\mathfrak{W}$ and $T$, we obtain
	\begin{align}
	\mathbf{P}^a(T=1) &=
	\mathbf{P}^a\Bigg(\mathfrak{W}
		\le \bigg(1-\frac1{k^{10}}\bigg)
		|\delta v|
		 \Bigg)\\
	&\le
	\mathbf{P}^a
	\Bigg(
	\max\bigg\{ \mathfrak{H} 
	,\sum_{e\in\delta v}
	\mathbf{1}\{\bm{L}_e\notin\mathbb{D}\cap\mathbb{L}\}
	\bigg\} \ge
	\frac{|\delta v|}{3k^{10}}\Bigg)
	\le \frac1{\exp(\Omega(k^3\ln k))}\,.

	\end{align}
Recall from (9.134) the choice of four distinct edges $\bm{E}$ from $\delta v$. 
For each $e\in\bm{E}$ define
	\begin{equation}
	\Gamma(e)\equiv 
	\begin{cases}
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\textup{\texttt{\footnotesize +}},i}$, and $x^{a,i}=\textup{\texttt{\footnotesize +}}$,}\\
	1&\textup{if $T(\mathcal{X}^a)=1$, 
		$e=e^{\textup{\texttt{\footnotesize -}},i}$, and $x^{a,i}=\textup{\texttt{\footnotesize -}}$,}\\
	0&\textup{otherwise.}
	\end{cases}\end{equation}
In the first transformation (described below), given $\mathcal{X}^a$ we will construct a modified configuration $\mathcal{X}^b$ in which $(\sigma_e)^i=\textup{\texttt{\footnotesize r}}$ and $\bm{L}_e\in\mathbb{D}\cap\mathbb{L}$ whenever 
$e=e^{\textup{\texttt{\footnotesize \textpm}},i}$ with $\Gamma(e)=1$. (This ensures that a frozen spin $x^i\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ has at least one incident $\textup{\texttt{\footnotesize red}}$ edge in $\delta v(x^i)$, and gives more flexibility to adjust the colors on the other incident edges.) For $e\in\bm{E}$ and $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ define
	\begin{equation}
	p_z(e)
	\equiv\mathbf{P}^a(\Gamma(e)=1,x=z)
	\le \mathbf{P}^a(T=1)
	\stackrel{(9.140)}{\le}
	\frac{1}{\exp(\Omega(k^3\ln k))}\,.
	\end{equation}
Note the definition of $\Gamma(e)$ implies
$p_z(e^{\textup{\texttt{\footnotesize +}},i})=0$ if $z^i\ne\textup{\texttt{\footnotesize +}}$, and likewise
$p_z(e^{\textup{\texttt{\footnotesize -}},i})=0$ if $z^i\ne\textup{\texttt{\footnotesize -}}$. For $e\in\bm{E}$ we also let
	\[r_z(e)
	\equiv
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x=z,(\sigma_e)^i=\textup{\texttt{\footnotesize r}},\sigma_e\ne\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}},
	\mathfrak{R}^i\ge2, T=0
	\bigg)\,.
	\]
Note having $(\sigma_e)^i=\textup{\texttt{\footnotesize r}}$ necessitates $x^i=\textup{\texttt{\footnotesize +}}$, so 
$r_z(e^{\textup{\texttt{\footnotesize +}},i})=0$ if $z^i\ne\textup{\texttt{\footnotesize +}}$
and $r_z(e^{\textup{\texttt{\footnotesize -}},i})=0$ if $z^i\ne\textup{\texttt{\footnotesize -}}$. In all other cases we claim that $r_z(e)\ge \Omega(1)/4^k$. Without loss of generality it suffices to consider the case $e=e^{\textup{\texttt{\footnotesize +}},1}$ and $z\in\{\textup{\texttt{\footnotesize +}}\}\times\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}$. In this case, recalling the bound
(9.140) gives
	\[
	r_z(e)
	\ge
	\mathbf{P}^a\bigg(
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L},
	x^2=z^2,\sigma_e\in\{\textup{\texttt{\footnotesize r}}\}
		\times\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\},
		\mathfrak{R}^i\ge2
	\bigg)
	-\frac1{\exp(\Omega(k^3\ln k))}\,.\]
Next recall from (9.126) that $(\smash{\underline{\smash{\sigma}}}_{\delta v})^1$, $(\smash{\underline{\smash{\sigma}}}_{\delta v})^2$, and $\bm{L}_e$ ($e\in\delta v$) are mutually independent under $\mathbf{P}^a$. It follows by straightforward calculations that for any $\bm{L}$ we have
	\[
	\mathbf{P}^a\bigg(
	\mathfrak{R}^i\ge2
	\,\bigg|\,\bm{L}_e=\bm{L},
	x^2=z^2,\sigma_e\in\{\textup{\texttt{\footnotesize r}}\}
		\times\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}\bigg)
	\ge 1-o_k(1)\,.
	\]
Combining with (9.135) gives
	\begin{equation}
	r_z(e)
	\ge
	\frac{1-o_k(1)}{2}
	\mathbf{P}^a\bigg(
	(\sigma_e)^1=\textup{\texttt{\footnotesize r}}
	\bigg)
	\mathbf{P}^a\bigg(x^2=z^2,
	(\sigma_e)^2\ne\textup{\texttt{\footnotesize r}}
	\bigg)-\frac1{\exp(\Omega(k^3\ln k))}
	\ge \frac{\Omega(1)}{4^k}\,,\end{equation}
as claimed. It follows by comparing (9.142) with (9.143) that $p_z(e)/r_z(e)=o_k(1)$. For $e\in\bm{E}$,
we define Bernoulli random variables $\Xi(e)$ such that if $r_z(e)=0$ then $\Xi(e)\equiv0$, and otherwise if $e=e^{\textup{\texttt{\footnotesize \textpm}},i}$ with $r_z(e)>0$ then
	\begin{equation}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1 \,\bigg|\, x=z,
		\mathcal{X}^a=\mathcal{X}\bigg)
	= \frac{p_z(e)}{r_z(e)}
	\mathbf{1}\bigg\{
	\bm{L}_e \in \mathbb{D}\cap \mathbb{L}, x=z,
	(\sigma_e)^i=\textup{\texttt{\footnotesize r}},
	\sigma_e\ne\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}, 
	\mathfrak{R}^i\geq 2,T=0
	\bigg\}\end{equation}
(for all possible values of $z,\mathcal{X}$). It then follows from the definition of $r_z(e)$ that for all $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$ we have
	\begin{equation}
	\mathbf{P}^a\bigg(
	\Xi(e) = 1,x=z\bigg)
	=p_z(e) =\mathbf{P}^a\bigg(
	\Gamma(e) = 1,x=z\bigg)\,,\end{equation}
and consequently $\mathbf{P}^a(\Xi(e) = 1)=\mathbf{P}^a(\Gamma(e) = 1)$. Further, by the independence properties of $\mathbf{P}^a$ that we see from the expression (9.126), we have
	\begin{equation}
	\mathbf{P}^a\Bigg(
		\bm{L}_e=\bm{L}
		\,\Bigg|\, \Xi(e) = 1, \Big(\sigma_e,
			\big(\sigma_{e'},\varsigma_{e'},\bm{L}_{e'}\big)_{e'\in
				\delta v\setminus e}\Big)
				\Bigg)
	= \pi_{\mathscr{D}}\Big(\bm{L}\,
		\Big|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L}
		\Big)\,.\end{equation}
This concludes our estimates on $\mathbf{P}^a$, and we now turn to the construction of $\mathbf{P}^b$.\smallskip

\noindent\textbf{\textup{\hypertarget{l:DIVERSE.Pb}{Part 3}. Construction of $\mathbf{P}^b$.}} Recall (9.134) that $\bm{E}$ is a subset of four distinct edges in $\delta v$. In the above we defined Bernoulli random variables $\Gamma(e)$ and $\Xi(e)$ for $e\in\bm{E}$. Recall moreover that $\Gamma(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=1$, while $\Xi(e)=1$ can only occur on the event $T=T(\mathcal{X}^a)=0$, so in particular we can never have $\Gamma(e)=\Xi(e)=1$. In the construction we will essentially ``swap'' the events $\Gamma(e)=1$ and $\Xi(e)=1$.
To make this precise, recall that we write $\mathcal{X}_e\equiv(\sigma_e,\varsigma_e,\bm{L}_e)$. Given $\mathcal{X}^a\sim\mathbf{P}^a$, we let $\mathcal{X}^b$ be defined as follows:
\begin{enumerate}[--]
\item If $e\in\delta v\setminus\bm{E}$ then set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=\Xi(e)=0$ then we also set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
\item If $e\in\bm{E}$ with $\Gamma(e)=1$ (hence $\Xi(e)=0$),
and $x_v=z$, then we let $(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)\,.
	\end{equation}
\item If $e\in\bm{E}$ with $\Xi(e)=1$ (hence $\Gamma(e)=0$),
and $x_v=z$, then we let 
$(\mathcal{X}^b)_e$ be sampled from the law
	\begin{equation}
	\mathbf{P}^b\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Xi(e)=1\bigg)
	=\mathbf{P}^a\bigg(\mathcal{X}_e\in\cdot \,\bigg|\, x_v=z,\Gamma(e)=1\bigg)\,.
	\end{equation}
\end{enumerate}
This results in a valid configuration $\mathcal{X}^b$ which has the same frozen spin as $\mathcal{X}^a$, that is, $x^a=x^b\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$. For the sake of concreteness, we give two examples of the above construction:
\begin{enumerate}[(a)]
\item \textit{Example on event $T=1$.} Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$, such that $T=T(\mathcal{X}^a)=1$. In this case it follows from the definition (9.141) of $\Gamma(e)$ that $\Gamma(e^{\textup{\texttt{\footnotesize +}},1})=\Gamma(e^{\textup{\texttt{\footnotesize +}},2})=1$. Since $x^a=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$, we must have $(\sigma^a)_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$ for $e\in\{e^{\textup{\texttt{\footnotesize +}},1},e^{\textup{\texttt{\footnotesize +}},2}\}$. The resampling step (9.147) results in a modified configuration $\mathcal{X}^b$. It follows from the definition (9.144) of $\Xi(e)$ that in the modified configuration,
	{\setlength{\jot}{0pt}\begin{align*}
	&\textup{$(\sigma^b)_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}}$ for $e = e^{\textup{\texttt{\footnotesize +}},1}$,}\\
	&\textup{$(\sigma^b)_e=\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}}$ for $e = e^{\textup{\texttt{\footnotesize +}},2}$.}
	\end{align*}}
Thus, for $e=e^{\textup{\texttt{\footnotesize \textpm}},i}$ with $\Gamma(e)=1$,
the procedure (9.147) makes
$(\sigma_e)^i$ marginally more likely to be $\textup{\texttt{\footnotesize red}}$,
but makes $\sigma_e$ less likely to be $\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$.

\item \textit{Example on event $T=0$.} 
Suppose we have $\mathcal{X}^a\sim\mathbf{P}^a$ with frozen spin $x^a=\textup{\texttt{\footnotesize +}}\textup{\texttt{\footnotesize +}}$, such that $T=T(\mathcal{X}^a)=0$. Recalling (9.144), suppose that we have $\Xi(e^{\textup{\texttt{\footnotesize +}},1})=1$
while $\Xi(e^{\textup{\texttt{\footnotesize +}},2})=0$. In particular, this means for $e=e^{\textup{\texttt{\footnotesize +}},1}$ we must have $(\sigma^a)_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}}$. The resampling step (9.148) results in a modified configuration $\mathcal{X}^b$. It follows from the definition (9.141) of $\Gamma(e)$ that in the modified configuration we must have $(\sigma^b)_e \in \{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\}^2$
for $e=e^{\textup{\texttt{\footnotesize +}},1}$. Thus, for $e=e^{\textup{\texttt{\footnotesize \textpm}},i}$ with $\Xi(e)=1$,
the procedure (9.148)
makes $(\sigma_e)^i$ marginally less likely to be $\textup{\texttt{\footnotesize red}}$,
but makes $\sigma_e$ more likely to be $\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$.
\end{enumerate}
We let $\mathbb{P}$ denote the joint law of $(\mathcal{X}^a,\mathcal{X}^b)$, and let $\mathbf{P}^b$ denote the marginal law of $\mathcal{X}^b$. Note that $\mathbf{P}^a$ and $\mathbf{P}^b$ have the same edge marginals: for $e\in\delta v\setminus \bm{E}$ it is clear that $(\mathcal{X}^a)_e$ and $(\mathcal{X}^b)_e$ have the same marginal law, since in the coupling we set $(\mathcal{X}^b)_e=(\mathcal{X}^a)_e$.
For $e\in\bm{E}$, we have
	{\setlength{\jot}{0pt}\begin{align}
	&\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1) \\ 
	&=\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)
	+\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^b(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)\\ 
	&=
	\mathbf{P}^a(\Xi(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Xi(e)=1)
	+\mathbf{P}^a(\Gamma(e)=1\,|\,x_v=z)
	\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,\Gamma(e)=1)\\
	&=\mathbf{P}^a(\mathcal{X}_e\in\cdot\,|\, x_v=z,
		\Gamma(e)+\Xi(e)=1)\,,

	\end{align}}
where the transition to the third line uses (9.145), (9.147), and (9.148). This verifies that $\mathbf{P}^b(\mathcal{X}_e\in\cdot)=\mathbf{P}^a(\mathcal{X}_e\in\cdot)$ for all $e\in\delta v$, so the measure $\mathbf{P}^b$ again satisfies the constraints (9.120), (9.121), and (9.123).
We now compare the entropy of $\mathbf{P}^a$ and $\mathbf{P}^b$. As above, denote $T=T(\mathcal{X}^a)$. Write $\bm{E}_a\equiv\{e\in\bm{E}:\Gamma(e)+\Xi(e)=1\}$. Denote $\mathcal{X}\equiv(\mathcal{Y},\mathcal{Z})$ where
	{\setlength{\jot}{0pt}\begin{align*}
	\mathcal{Y}&\equiv (\mathcal{X}_e : e\in\bm{E}_a)\,,\\
	\mathcal{Z}&\equiv (\mathcal{X}_e : e\in\delta v\setminus\bm{E}_a)\,.
	\end{align*}}
If $\bm{E}_a=\varnothing$ then $\mathcal{Y}$ is the null vector. Likewise denote $\smash{\underline{\smash{X}}}_{\delta v}\equiv (Y,Z)$
where $Y\equiv (X_e:e\in\bm{E}_a)$. We then have
	{\setlength{\jot}{0pt}\begin{align}
	\mathcal{H}(\mathcal{X}^b) 
	&\ge\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( \mathcal{Y}^b\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)\\
	&=\mathcal{H}(T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( (\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a}\,|\, T,\bm{E}_a,\mathcal{Z}^b)
		+\mathcal{H}( Y^b\,|\, T,\bm{E}_a,\mathcal{Z}^b,(\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a})
		-\mathcal{H}(T)-\mathcal{H}(\bm{E}_a)
	\,,\\ 
	\mathcal{H}(\mathcal{X}^a) 
	&\le \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a) +
		\mathcal{H}(\mathcal{Y}^a\,|\,T,\bm{E}_a,\mathcal{Z}^a)\\
	&= \mathcal{H}(T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}((\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a}\,|\,T,\bm{E}_a,\mathcal{Z}^a)
		+\mathcal{H}(Y^a\,|\,T,\bm{E}_a,\mathcal{Z}^a,(\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a})
		\,.

	\end{align}}
Recall that the edges outside $\bm{E}_a$ are left unchanged by the transformation from $\mathcal{X}^a$ to $\mathcal{X}^b$, so
	\begin{equation}
	\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^b\bigg)
	=\mathcal{H}\bigg(T,\bm{E}_a,\mathcal{Z}^a\bigg)\,.\end{equation}
Next, (9.140) and (9.145) together imply that
	\[
	\mathbf{P}^a(\bm{E}_a\ne\varnothing) 
	\le O\Big( \mathbf{P}^a(T=1)\Big)
	\le O\bigg( \frac{1}{\exp(\Omega(k^3\ln k))}
		\bigg)\,,\]
from which it follows that
	\begin{equation}
	\max\bigg\{\mathcal{H}(T),\mathcal{H}(\bm{E}_a),
		\mathcal{H}(Y^a\,|\,\bm{E}_a),
		\mathcal{H}(Y^b\,|\,\bm{E}_a)
		\bigg\} = o_k(1)\,.\end{equation}
We emphasize that in (9.153) we must put $Y^a$ and $Y^b$ rather than $\mathcal{Y}^a$ and $\mathcal{Y}^b$:
this is because $Y$ consists of spins
$X_e$ which take only $O(1)$ possibilities, while $\mathcal{Y}$ consists of spins $\mathcal{X}_e=(X_e,\bm{L}_e)$ which take a large number of possibilities (indeed, growing with the neighborhood radius $R$ of (3.1)) and therefore can have large conditional entropy given $\bm{E}_a$. To deal with the clause types $\bm{L}_e$ we note that
	\begin{align}
	&\mathcal{H}\bigg( 
	(\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T, \mathcal{Z}^a\bigg) \\ 
 	&\stackrel{(9.146)}{=}
	\sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^a(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^a(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap\mathbb{L})\Big)\\ 
	&\stackrel{(9.145)}{=} \sum_{e\in \bm{E}}
	\Bigg\{
	\mathbf{P}^b(\Gamma(e)=1)
		\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot\,|\,\bm{t}_e)\Big)
	+\mathbf{P}^b(\Xi(e)=1)
	\mathcal{H}\Big(\pi_{\mathscr{D}}(\cdot
	\,|\,\bm{t}_e, \bm{L}_e \in \mathbb{D}\cap \mathbb{L})\Big)
	\Bigg\}\\
	&\stackrel{(9.146)}{=}
	\mathcal{H}\bigg( 
	(\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a}
	\,\bigg|\,
	\bm{E}_a,T,\mathcal{Z}^b
	\bigg)\,. 
	\end{align}
Combining (9.153) and (9.154) gives 
	\begin{align}
	&\bigg| \mathcal{H}\Big( \mathcal{Y}^a 
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)- 
	\mathcal{H}\Big( \mathcal{Y}^b
		\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\bigg| \\ 
	&=
	\bigg|\mathcal{H}\Big( (\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^a\Big)
	-\mathcal{H}\Big( (\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a}\,\Big|\, \bm{E}_a,T,\mathcal{Z}^b\Big)\\

	&\qquad+\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a}\Big)
	\bigg|\\ 
	&\stackrel{(9.154)}{=}
	\bigg|\mathcal{H}\Big( Y^a \,\Big|\, \bm{E}_a,T,\mathcal{Z}^a,(\smash{\underline{\smash{\bm{L}}}}^a)_{\bm{E}_a}\Big)
	-\mathcal{H}\Big( Y^b \,\Big|\, \bm{E}_a,T,\mathcal{Z}^b,(\smash{\underline{\smash{\bm{L}}}}^b)_{\bm{E}_a}\Big)\bigg|
	\stackrel{(9.153)}{=} o_k(1)\,.

	\end{align}
Finally, combining (9.150), (9.151), (9.152),
(9.153), and (9.155) gives
	\begin{equation}
	\mathcal{H}(\mathbf{P}^b)-\mathcal{H}(\mathbf{P}^a)
	=\mathcal{H}(\mathcal{X}^b) - \mathcal{H}(\mathcal{X}^a)
	\ge o_k(1)\,.
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^b$.\smallskip

\noindent\textbf{\textup{\hypertarget{l:DIVERSE.Pc}{Part 4}. Construction of $\mathbf{P}^c$.}}
Given a configuration $\mathcal{X}$, for 
$z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ and
$i=1,2$ let
	\begin{equation}
	\hat{\bm{E}}^{z,i}
	\equiv \hat{\bm{E}}^{z,i}(\mathcal{X})
	\equiv \bigg\{ e\in\delta v(z):
	(\sigma_e)^i=\textup{\texttt{\footnotesize r}},\sigma_e\ne\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}},
	\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\end{equation}
Write $\hat{\bm{E}}^i\equiv
\hat{\bm{E}}^{\textup{\texttt{\footnotesize -}},i}\cup\hat{\bm{E}}^{\textup{\texttt{\footnotesize +}},i}$.
Note that $\hat{\bm{E}}^1\cap\hat{\bm{E}}^2=\varnothing$. Recall from (9.134) the definition of $\bm{E}$, and for $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ let
	\[
	\acute{\bm{E}}^z
	\equiv \acute{\bm{E}}^z(\mathcal{X})
	\equiv\bigg\{e\in\delta v(z)\setminus\bm{E}
	: \varsigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}},\bm{L}_e\in\mathbb{D}\cap\mathbb{L}\bigg\}\,.
	\]
(The sets $\acute{\bm{E}}^{\textup{\texttt{\footnotesize \textpm}}}(\mathcal{X}^a)$
are disjoint from $\bm{E}$, but
the sets $\hat{\bm{E}}^i$ can intersect $\bm{E}$.) We construct $\mathcal{X}^c$ as follows:
\begin{enumerate}[(II-2)]
\item[\hypertarget{i:DIVERSE.I1}{(I-1)}] On the event $\{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2\}$,
choose $\hat{e}^1$ uniformly at random from $\hat{\bm{E}}^1(\mathcal{X}^a)$. For $e=\hat{e}^1$, set 
$(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$ with probability $1-2^{-k\epsilon_\infty/2}$. With the remaining probability $2^{-k\epsilon_\infty/2}$ let $(\mathcal{X}^c)_e$ 
for $e=\hat{e}^1$
be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&=(\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize w}})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
	&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
	\end{align*}}
Let $p^{\textup{I},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}
	p^{\textup{I},1}(e,\bm{L})
	= \frac1{2^{k\epsilon_\infty/2}}
	\mathbb{E}
	\Bigg(
	\frac{\mathbf{1}\{e\in\hat{\bm{E}}^1(\mathcal{X}^a)\}}
		{|\hat{\bm{E}}^1(\mathcal{X}^a)|};
	(\bm{L}^a)_e=\bm{L},
	\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2
	\Bigg)\,,\end{equation}
where $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 

\item[\hypertarget{i:DIVERSE.I2}{(I-2)}]
On the event $\{\mathcal{X}^a=\mathcal{X}^b,T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\ge2\}$, perform the analogue of 
\hyperlink{i:DIVERSE.I1}{(I-1)} switching the roles of the two copies, and define the corresponding probability $p^{\textup{I},2}(e,\bm{L})$.

\item[\hypertarget{i:DIVERSE.II1}{(II-1)}] 
On the event $\{x^{a,1}\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\},
T(\mathcal{X}^a)=0,|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1\}$, choose $\acute{e}^1$ uniformly at random from $\acute{\bm{E}}^{x^1}(\mathcal{X}^a)$. (Note the condition $T(\mathcal{X}^a)=0$ guarantees that the sets $\acute{\bm{E}}^{\textup{\texttt{\footnotesize \textpm}}}(\mathcal{X}^a)$ are both large, so it is possible to choose $\acute{e}^1$.) Let $(\mathcal{X}^c)_e$ for $e=\acute{e}^1$ be defined by
	{\setlength{\jot}{0pt}\begin{align*}
	(\sigma^{c,1},\varsigma^{c,1})_e
	&= (\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize r}})\,,\\
	(\sigma^{c,2},\varsigma^{c,2},\bm{L}^c)_e
		&=(\sigma^{b,2},\varsigma^{b,2},\bm{L}^b)_e
		\,.
	\end{align*}}
Let $p^{\textup{II},1}(e,\bm{L})$ denote the probability that edge $e$ has clause type $\bm{L}$ and is changed by the above:
	\begin{equation}
	p^{\textup{II},1}(e,\bm{L})
	= \sum_{z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}}
	\mathbb{E}\Bigg(
	\frac{\mathbf{1}\{e\in\acute{E}^z(\mathcal{X}^a)\}}
		{|\acute{E}^z(\mathcal{X}^a)|}
	; (\bm{L}^a)_e=\bm{L}, x^{a,1}=z,
	T(\mathcal{X}^a)=0,
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\Bigg)\,,
	\end{equation}
where again $\mathbb{E}$ denotes expectation with respect to the joint law $\mathbb{P}$ of $(\mathcal{X}^a,\mathcal{X}^b)$. 
\item[\hypertarget{i:DIVERSE.II2}{(II-2)}] 
Lastly, on the event
$\{x^{a,2}\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\},T(\mathcal{X}^a)=0,|\hat{\bm{E}}^2(\mathcal{X}^a)|\le1\}$,
perform the analogue of \hyperlink{i:DIVERSE.II1}{(II-1)} switching the roles of the two copies, with the modification that if \hyperlink{i:DIVERSE.II1}{(II-1)} already occurred, then $\acute{e}^2$ is chosen uniformly at random from $\acute{\bm{E}}(\mathcal{X}^a)^2\setminus\{\acute{e}^2\}$. Define the corresponding probability $p^{\textup{II},2}(e,\bm{L})$.
\end{enumerate}
We point out that
steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)}
can only occur if $\mathcal{X}^a=\mathcal{X}^b$,
but steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
can occur even in the case
$\mathcal{X}^a\ne\mathcal{X}^b$. Note also that \hyperlink{i:DIVERSE.I1}{(I-1)} and \hyperlink{i:DIVERSE.II1}{(II-1)}
 cannot both occur, and likewise \hyperlink{i:DIVERSE.I2}{(I-2)} and 
 \hyperlink{i:DIVERSE.II2}{(II-2)}
 cannot both occur. To finish the construction, for all edges $e\in\delta v$ which were not chosen as $\hat{e}^i$ or $\acute{e}^i$ in any of the above steps, set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$. Note that the frozen spin has not changed, $x=x^a=x^b=x^c\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$. Moreover we have $(\bm{L}^b)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. It is straightforward to verify that the resulting $\mathcal{X}^c$ is a valid configuration with the same frozen spin, $x^b=x^c\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$.
Moreover, we observe that the construction so far guarantees 
	\begin{equation} 
	\hat{\bm{E}}^{z,i}(\mathcal{X}^c)\ne\varnothing
	\quad\textup{whenever}\quad
	x^{c,i}=z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}\,,
	\end{equation}
for $\hat{\bm{E}}^{z,i}$ as defined by (9.157). Indeed, if $x=x^c$
has in the first copy $x^1=z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$, we have these cases:
\begin{enumerate}[--]
\item Suppose $T(\mathcal{X}^a)=1$. It follows from (9.141) that we will have $\Gamma(e)=1$ for $e=e^{z,1}\in\bm{E}$. In this case the resampling step 
(9.147) and the definition 
(9.144)
of $\Xi(e)$ results in
a modified configuration $\mathcal{X}^b$ such that
 $e$ belongs to $\hat{\bm{E}}^{z,1}(\mathcal{X}^b)$.
(If $x^2=y\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ then we may also have $\Gamma(e^{y,2})=1$, in which case the set $\hat{\bm{E}}^{y,2}$ also increases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations.)
Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$,
and steps 
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $T(\mathcal{X}^a)=1$.
It follows that 
	\[|\hat{\bm{E}}^{z,1}(\mathcal{X}^c)|
	=|\hat{\bm{E}}^{z,1}(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^{z,1}(\mathcal{X}^a)|+1
	\ge1\,,\]
since $e=e^{z,1}\in\hat{\bm{E}}^{z,1}(\mathcal{X}^b)\setminus 
\hat{\bm{E}}^{z,1}(\mathcal{X}^a)$.

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a=\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. In this case, the only way for an edge $e$ to belong to $\hat{\bm{E}}^1(\mathcal{X}^a)=\hat{\bm{E}}^1(\mathcal{X}^b)$ and not to $\hat{\bm{E}}^1(\mathcal{X}^c)$ is if $e$ is chosen as $\hat{e}^1$ in step \hyperlink{i:DIVERSE.I1}{(I-1)}. It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	\ge |\hat{\bm{E}}^1(\mathcal{X}^b)|-1
	= |\hat{\bm{E}}^1(\mathcal{X}^a)|-1
	\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$, $\mathcal{X}^a\ne\mathcal{X}^b$, and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$. 
In this case, we see from (9.144)
that we may have $\Xi(e)=1$
for $e=e^{z,1}$. This means $e\in\hat{\bm{E}}^1(\mathcal{X}^a)$, and the resampling step (9.148) results in $\mathcal{X}^b$ such that $e\notin\hat{\bm{E}}^1(\mathcal{X}^b)$. (If $x^2=y\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ then we may also have $\Xi(e^{y,2})=1$, in which case the set 
$\hat{\bm{E}}^{y,2}$
also decreases going from $\mathcal{X}^a$ to $\mathcal{X}^b$, but this is not relevant to the current considerations since the $\hat{\bm{E}}^i$ are disjoint.) Then steps \hyperlink{i:DIVERSE.I1}{(I-1)}
and \hyperlink{i:DIVERSE.I2}{(I-2)} do not occur
because $\mathcal{X}^a\ne\mathcal{X}^b$, and steps
\hyperlink{i:DIVERSE.II1}{(II-1)}
and \hyperlink{i:DIVERSE.II2}{(II-2)}
do not occur because $|\hat{\bm{E}}^1(\mathcal{X}^a)|\ge2$.
It follows that
	\[
	|\hat{\bm{E}}^1(\mathcal{X}^c)|
	=|\hat{\bm{E}}^1(\mathcal{X}^b)|
	\ge|\hat{\bm{E}}^1(\mathcal{X}^a)|-1\ge1\,.
	\]

\item Suppose $T(\mathcal{X}^a)=0$ and $|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1$. In this case, step 
\hyperlink{i:DIVERSE.II1}{(II-1)}
occurs and results in 
a configuration $\mathcal{X}^c$ such that
$\hat{\bm{E}}^1(\mathcal{X}^c)$ contains $\hat{e}^1$, and so is nonempty.
\end{enumerate}
This verifies the property (9.160), which will be used
in later steps of the proof. We now let $\mathbb{P}$ denote the joint law of
 $(\mathcal{X}^a,\mathcal{X}^b,\mathcal{X}^c)$, and let $\mathbf{P}^c$ denote the marginal law of $\mathcal{X}^c$. 

We first estimate the probability $p^{\textup{I},1}(e,\bm{L})$ from (9.158). For an upper bound, note in order for $e\in\hat{\bm{E}}^1(\mathcal{X})$ we must have $(\sigma_e)^1=\textup{\texttt{\footnotesize r}}$, so for all clause types $\bm{L}$ we have
	\begin{equation}
	p^{\textup{I},1}(e,\bm{L})
	\le
	\frac{\mathbf{P}^a( \bm{L}_e=\bm{L}, (\sigma_e)^1=\textup{\texttt{\footnotesize r}} )}
		{2^{k\epsilon_\infty/2}}
	= \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\cdot {}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})}
		{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next, since the total probability that \hyperlink{i:DIVERSE.I1}{(I-1)} occurs is at most $2^{-k\epsilon_\infty/2}$, we can also bound
	\begin{equation}
	\sum_{e\in\delta v}\sum_{\bm{L}} 
	p^{\textup{I},1}(e,\bm{L})
	\le \frac1{2^{k\epsilon_\infty/2}}\,.\end{equation}
Next we note that $p^{\textup{I},1}(e,\bm{L})=0$ if $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. In the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we will derive a lower bound on $p^{\textup{I},1}(e,\bm{L})$. Recall $R_e$ from (9.136), and let $S_e$ be an independent copy of $R_e$. By similar considerations as for (9.137), we have
	\begin{equation}
	\mathbf{P}^a\Bigg(
	\ddot{\mathfrak{r}}(\mathcal{X})
	\equiv
	\sum_{e\in\delta v} \mathbf{1}\{\sigma_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}
	\ge k^{1/2}\Bigg)
	\le O(1)
	\max_{z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}}\Bigg\{
	\frac{\mathbb{P}(\sum_{e\in\delta v(z)}
		R_e S_e \ge k^{1/2})}
	{\mathbb{P}(\sum_{e\in\delta v(z)} R_e\ge1)^2}\Bigg\}
	\le \frac1{\exp(\Omega(k^{3/2}))}\,.\end{equation}
Next, for $e\in\delta v$, let $G_e$ denote independent Bernoulli random variables with
	\[\mathbb{P}(G_e=1)
	=\mathbf{P}^a(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})
	=\sum_{\bm{L}}
		\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)
		\mathbf{1}\{\bm{L}\in\mathbb{D}\cap\mathbb{L}\}\,.\]
For $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ and any fixed $e\in\delta v(z)$, on the event $\{(\sigma_e)^1=\textup{\texttt{\footnotesize r}}\}$ we have
	\begin{equation}
	(\mathfrak{r}_e)^1(\mathcal{X})
	\equiv
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\bigg\{(\sigma_{e'})^1=\textup{\texttt{\footnotesize r}},
		\bm{L}_{e'} \in \mathbb{D}\cap\mathbb{L}
	\bigg\}
	\ge \Big|\hat{\bm{E}}^1(\mathcal{X})\setminus
		\{e\}\Big|
	\ge (\mathfrak{r}_e)^1(\mathcal{X}) 
	- \ddot{\mathfrak{r}}(\mathcal{X})\,,\end{equation}
where $\ddot{\mathfrak{r}}(\mathcal{X})$ was defined on the left-hand side of (9.163). By similar considerations as for (9.137) and (9.163), we can express
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\textup{\texttt{\footnotesize r}}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)\,.
	\]
To bound this last probability, note that
for both $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$ we have
	\begin{align*}
	&\mathrm{Var}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	\le \mathbb{E}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
	R_{e'} G_{e'}\Bigg)
	=\sum_{e'\in\delta v(z)\setminus e}
	\mathbb{E} R_{e'}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'})\\
	&\qquad=
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}
	-\sum_{e'\in\delta v(z)\setminus e}
	(\mathbb{E} R_{e'}) \mathbb{E}(1-G_{e'}) 
	\stackrel{(9.118)}{=}
	\bigg(1-o_k(1)\bigg) \frac{k\ln 2}{2}\,.
	\end{align*}
We can use this last estimate together with Bernstein's inequality to bound
	\begin{equation}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \le \frac{k}{3}
	\,\Bigg|\, (\sigma_e)^1=\textup{\texttt{\footnotesize r}}\Bigg)
	=\mathbb{P}\Bigg(
	 \sum_{e'\in\delta v(z)\setminus e}
	 R_{e'} G_{e'} \le \frac{k}{3}\Bigg)
	\le \frac1{\exp(\Omega(k))}\,.\end{equation}
On the other hand, by similar arguments as for (9.137), we can bound
	\[
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \ge k
	\,\Bigg|\, (\sigma_e)^1=\textup{\texttt{\footnotesize r}}\Bigg)
	\le \mathbb{P}\Bigg( \sum_{e'\in\delta v(z)\setminus e}
		R_{e'} \ge k\Bigg)
	\le \frac1{\exp(\Omega(k\ln k))}\,.
	\]
Combining the last two bounds gives
	\begin{equation}
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in
		\bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\, (\sigma_e)^1=\textup{\texttt{\footnotesize r}}\Bigg)
	\ge1- \frac1{\exp(\Omega(k))}\,.
	\end{equation}
Returning to (9.158), 
for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can lower bound
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	&\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\textup{\texttt{\footnotesize r}},
	(\sigma_e)^2\ne\textup{\texttt{\footnotesize r}},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)\\
	&\qquad-\Bigg\{\mathbf{P}^a(T=1)
	+\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
	+\mathbf{P}^a(\ddot{\mathfrak{r}}\ge k^{1/2})
		\Bigg\}\,.\end{align*}
In the above we used the assumption that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, so if
$(\sigma_e)^1=\textup{\texttt{\footnotesize r}}$ and $(\sigma_e)^2\ne\textup{\texttt{\footnotesize r}}$
then $e\in\hat{\bm{E}}^1$.
We also used that if $(\mathfrak{r}_e)^1 \ge k/3$
and $\ddot{\mathfrak{r}}\le k^{1/2}$, then
certainly (9.164) implies $|\hat{\bm{E}}^1|\ge2$, as is required for step (I-1) to occur. Lastly we used that if
$(\mathfrak{r}_e)^1 \le k$, then 
it follows from (9.164) that $|\hat{\bm{E}}^1|\le k+1$, so edge $e$ has probability at least $1/(k+1) \ge 1/(2k)$ to be chosen as $\hat{e}^1$. Now recall from the previous construction that
$\mathbb{P}(\mathcal{X}^a\ne \mathcal{X}^b)
\le O(\mathbf{P}^a(T=1))$, so applying (9.140) and (9.163) gives
	\begin{align*}
	p^{\textup{I},1}(e,\bm{L}) 
	\ge \frac1{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Bigg(
	\bm{L}_e=\bm{L},
	(\sigma_e)^1=\textup{\texttt{\footnotesize r}},
	(\sigma_e)^2\ne\textup{\texttt{\footnotesize r}},
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\Bigg)
	-\frac1{\exp(\Omega(k^{3/2}))}\,.
	\end{align*}
It then follows (again using the independence properties of $\mathbf{P}^a$) that
	\begin{align}
	p^{\textup{I},1}(e,\bm{L}) 
	&\stackrel{(9.126)}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\mathbf{P}^a\Big((\sigma_e)^1=\textup{\texttt{\footnotesize r}}\Big)
	\mathbf{P}^a\Big((\sigma_e)^2\ne\textup{\texttt{\footnotesize r}}\Big)
	\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1 \in \bigg[\frac{k}{3},k\bigg]
	\,\Bigg|\,
	(\sigma_e)^1=\textup{\texttt{\footnotesize r}}
	\Bigg) \\
	&\stackrel{(9.166)}{\ge}
	\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k\epsilon_\infty/2} \cdot 2k}
	\cdot \frac{1-o_k(1)}{2^k}\,,
	\end{align}
as long as $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. This concludes our analysis of $p^{\textup{I},1}(e,\bm{L})$. Clearly, 
(9.162) and (9.167) also hold for 
$p^{\textup{I},2}(e,\bm{L})$.


We next prove an upper bound on the probability 
$p^{\textup{II},1}(e,\bm{L})$ from
(9.159). Recall that the condition $T(\mathcal{X}^a)=0$ implies 
$|\acute{\bm{E}}^z(\mathcal{X}^a)| = \Theta(k2^k)$
for both $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$.
It follows that we can upper bound (9.159) as
	\[
	p^{\textup{II},1}(e,\bm{L})
	\le
	O\bigg(\frac1{k2^k}\bigg)
	\cdot
	\mathbf{P}^a\bigg(\bm{L}_e=\bm{L},
	|\hat{\bm{E}}^1(\mathcal{X}^a)|\le1
	\bigg)
	\le
	O\bigg(\frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}{k2^k}\bigg)
	\cdot\mathbf{P}^a\bigg(
		|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\{e\}|\le1
		\bigg)\,.\]
Recall from
(9.164) 
that $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\{e\}| \le (\mathfrak{r}_e)^1(\mathcal{X}^a)$. Then, arguing similarly as for 
(9.165), 
for each $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$
we can apply Bernstein's inequality to upper bound
	\begin{align*}
	&\mathbf{P}^a\Bigg(
	(\mathfrak{r}_e)^1
	=
	\sum_{e'\in\delta v(z)\setminus e}
	\mathbf{1}\Big\{(\sigma_{e'})^1=\textup{\texttt{\footnotesize r}},
	\bm{L}_{e'}\in\mathbb{D}\cap\mathbb{L}
	\Big\} \le1
	\,\Bigg|\, x^1=z\Bigg) \\
	&\qquad= \frac{\mathbb{P}(\sum_{e'
		\in\delta v(z)\setminus e} R_{e'} G_{e'}
			\le1)}
		{\mathbb{P}(\sum_{e'\in\delta v(z)} R_{e'}\ge1)}
	\le \frac1{\exp(k c_0)}\,,
	\end{align*}
for a positive absolute constant $c_0$.
On the other hand, if $(\mathfrak{r}_e)^1\ge2$, in order for $|\hat{\bm{E}}^1(\mathcal{X}^a)\setminus\{e\}|\le1$ it must be that
$(\sigma^{a,2})_{e'}=\textup{\texttt{\footnotesize r}}$ for all but at most one of the edges $e'$ contributing to $(\mathfrak{r}_e)^1$, which has chance $O(2^{-k})$. Then
	\[
	\mathbf{P}^a\bigg(
		\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\{e\}=\varnothing\bigg)
	\le
	\mathbf{P}^a \bigg((\mathfrak{r}_e)^1\le1\bigg)
	+\underbrace{\mathbf{P}^a\bigg(
	(\mathfrak{r}_e)^1\ge2,
	|\hat{\bm{E}}^1(\mathcal{X}^a)
		\setminus\{e\}| \le1
		\bigg)}_{O(1/2^k)}
	\le \frac1{\exp(k c_0)}\,.\]
Substituting into the above expression for
$p^{\textup{II},1}(e,\bm{L})$ gives
	\begin{equation}
	p^{\textup{II},1}(e,\bm{L})
	\le \frac{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
		{2^{k(1+c_0)}}\,.
	\end{equation}
A similar bound holds for $p^{\textup{II},2}(e,\bm{L})$, and this concludes our analysis of $p^{\textup{II},1}(e,\bm{L})$.

We now turn to estimating the entropy of $\mathbf{P}^c$. Let $\bm{E}_b$ be the (random) subset of edges $e\in\delta v$ for which $(\mathcal{X}^b)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^b)_e\ne(X^c)_e$. It follows by combining (9.162) and (9.168) that
	\begin{equation}
	\mathbb{E}(|\bm{E}_b|)
	\le \sum_{e\in\delta v}\sum_{\bm{L}}\sum_{i=1,2}
		\bigg(
		p^{\textup{I},i}(e,\bm{L})
		+p^{\textup{II},i}(e,\bm{L})\bigg)
	\le O\bigg( \frac1{2^{k\epsilon_\infty/2}}\bigg)\,.\end{equation}
We write $\mathcal{H}(\bm{E}_b)$ to denote the entropy of the random variable $\bm{E}_b$, and we write $H(p)\equiv -p\ln p-(1-p)\ln (1-p)$ to denote the binary entropy function evaluated at $p\in[0,1]$. Then
	\begin{equation}
	\mathcal{H}(\bm{E}_b)
	\le \sum_{e\in\delta v} \mathcal{H}( \mathbf{1}\{e\in\bm{E}_b\} )
	\le |\delta v|
	H\bigg( \frac{ \mathbb{E}(|\bm{E}_b|) }{|\delta v|}\bigg)
	\stackrel{(9.169)}{=} 
	o_k(1)\,,
	\end{equation}
where the second step used Jensen's inequality and the concavity of the binary entropy function. Now decompose $\smash{\underline{\smash{X}}}_{\delta v}\equiv (U,W)$ where $U\equiv(X_e:e\in\bm{E}_b)$. 
Note if $\bm{E}_b$ is given, then $U^b$ takes at most $O(1)$ distinct values, so it follows from (9.170) that the conditional entropy of $U^b$ given $\bm{E}_b$ is small, that is,
$\mathcal{H}(U^b \,|\, \bm{E}_b)=o_k(1)$. Then, since $\mathcal{X}^b$ can be determined as a function of $(\mathcal{X}^c,\bm{E}_b,U^b)$, we have
	\begin{equation}
	\mathcal{H}(\mathcal{X}^b)
	\le \mathcal{H}(\mathcal{X}^c) +
	\bigg( \mathcal{H}(\bm{E}_b) + \mathcal{H}(U^b \,|\, \bm{E}_b)\bigg)
	\stackrel{(9.170)}{\le}
	\mathcal{H}(\mathcal{X}^c) + o_k(1)\,.
	\end{equation}
This verifies that the entropy of $\mathbf{P}^c$ is not much smaller than that of $\mathbf{P}^b$.

We finally estimate how the transformation from $\mathbf{P}^b$ to $\mathbf{P}^c$ affects the edge marginals. Recall that steps \hyperlink{i:DIVERSE.I1}{(I-1)} and 
\hyperlink{i:DIVERSE.I2}{(I-2)} can change $(\varsigma_e)^i$
from $\textup{\texttt{\footnotesize red}}$ to $\textup{\texttt{\footnotesize white}}$, and the probability of such a change is lower bounded by (9.167). Meanwhile, steps
\hyperlink{i:DIVERSE.II1}{(II-1)} and 
\hyperlink{i:DIVERSE.II2}{(II-2)} 
can change $(\varsigma_e)^i$ from $\textup{\texttt{\footnotesize white}}$ to $\textup{\texttt{\footnotesize red}}$,
and the probability of such a change is upper bounded by (9.168).
It follows that for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$,
	\begin{align}
	&\mathbf{P}^c\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+\sum_{i=1,2}
	\frac{p^{\textup{II},i}(e,\bm{L})- p^{\textup{I},i}(e,\bm{L})}
		{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\\
	\qquad&\le
	\mathbf{P}^b\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	+ O\bigg( \frac{1}{2^{k(1+c_0)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\,,

	\end{align}
where the last step also used our earlier observation
(9.149) that $\mathbf{P}^b$ has the same edge marginals as $\mathbf{P}^a$. On the other hand, since the probability of
\hyperlink{i:DIVERSE.I1}{(I-1)} or
\hyperlink{i:DIVERSE.I2}{(I-2)} is upper bounded by (9.161), we also have
	\begin{equation}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge
	\mathbf{P}^b\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\sum_{i=1,2}
	\frac{p^{\textup{I},i}(e,\bm{L})}{\pi_{\mathscr{D}}(\bm{L}\,|\,\bm{t}_e)}
	\ge{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})- 
	O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. In the case $(\bm{L}^b)\notin \mathbb{D}\cap\mathbb{L}$ we always set $(\mathcal{X}^c)_e=(\mathcal{X}^b)_e$,
so 
	\begin{equation}
	\mathbf{P}^c\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	=
	\mathbf{P}^b\bigg( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\end{equation}
for all $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$. Finally, since we did not yet change any spin with $(\varsigma_e)^i\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$
or $\varsigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, we have
	{\setlength{\jot}{0pt}\begin{align}

	\mathbf{P}^c((\varsigma_e)^i=\tau\,|\, \bm{L}_e=\bm{L})
	&=(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})
	\textup{ for all }\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}, \\
	\mathbf{P}^c(\varsigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\,|\, \bm{L}_e=\bm{L})
	&= \mathbf{P}^a(\varsigma_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\,|\, \bm{L}_e=\bm{L})
	\le O(k^4/4^k)

	\end{align}}
for all $\bm{L}$, where the final bound uses (9.129).\smallskip

\noindent\textbf{\textup{\hypertarget{l:DIVERSE.Pd}{Part 5}. Construction of $\mathbf{P}^d$.}} We now construct $\mathcal{X}^d$ from $\mathcal{X}^c$. We will leave the clause type unchanged, $(\bm{L}^d)_e=(\bm{L}^c)_e$ for all $e\in\delta v$. We change some edges from non-\textup{\texttt{\footnotesize white}} to \textup{\texttt{\footnotesize white}}, according to the following rules.
\begin{enumerate}[(A)]
\item If $\bm{L}\not\in\mathbb{D}\cap\mathbb{L}$ and $(\varsigma^c)_e\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$, then set $(\varsigma^d)_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$, and
for $i=1,2$ set
	\[
	(\sigma^{d,i})_e
	=\begin{cases}
	\textup{\texttt{\footnotesize b}} &\textup{if $(\sigma^{c,i})_e=\textup{\texttt{\footnotesize r}}$,}\\
	(\sigma^{c,i})_e &\textup{otherwise.}
	\end{cases}
	\]
\item If $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ then modify the spin on $e$ as follows:
\begin{enumerate}[(i)]
\item If $(\varsigma^c)_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$ then set
$(\sigma^d,\varsigma^d)_e=(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})$.

\item If $(\varsigma^c)_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2\setminus\{\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\}$ then set
$(\sigma^d)_e=(\sigma^c)_e$, and for $i=1,2$ set
	\[
	(\varsigma^{d,i})_e
	=\begin{cases}
	\textup{\texttt{\footnotesize r}}&\textup{if $(\sigma^{c,i})_e=\textup{\texttt{\footnotesize r}}$,}\\
	\textup{\texttt{\footnotesize w}}&\textup{otherwise.}
	\end{cases}
	\]

\item If $(\varsigma^c)_e\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}\times\{\textup{\texttt{\footnotesize w}}\}$ then set
$(\sigma^d)_e=(\sigma^c)_e$. For $\tau=(\varsigma^{c,1})_e\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ define the quantity
	\[\theta=
	(\theta_e)^1(\tau\,|\,\bm{L})
	\equiv\min\bigg\{1, \frac{2^{-k(1+\epsilon_\infty/2)} }
		{(\bm{\zeta}_e)^1(\tau \,|\,\bm{L})}\bigg\}\,.
	\]
Set
 $(\varsigma^d)_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$ with probability $\theta$. With the remaining probability $1-\theta$ leave $(\varsigma^d)_e$ unchanged.
If $(\varsigma^c)_e\in\{\textup{\texttt{\footnotesize w}}\}\times\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ then perform the analogous procedure with the roles of the two copies switched.

\item Lastly, if $(\varsigma^c)_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$ then set
$(X^d)_e=(\sigma^d,\varsigma^d)_e=(\sigma^c,\varsigma^c)_e=(X^c)_e$.
\end{enumerate}
\end{enumerate}
Note that property (9.160)
of $\mathcal{X}^c$ ensures that the above transformation results in a valid configuration $\mathcal{X}^d$
with the same frozen spin, $x^c=x^d\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$. 
Since the transformation does not add any \textup{\texttt{\footnotesize red}} spins, for $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ we can bound
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\le\mathbf{P}^c\bigg(\varsigma_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\stackrel{(9.172)}{\le} {}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad=\zeta_e(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
	+\zeta_e(\{\textup{\texttt{\footnotesize r}}\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}\,|\,\bm{L})
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)\\
	&\qquad\stackrel{\odot}{\le}
	\zeta_e(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
	+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
	-\Omega\bigg( \frac{1}{k 2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le \zeta_e(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,|\,\bm{L})\,.
	\end{align*}
The inequality marked $\odot$ above follows from Lemma~9.7 and the assumption $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, with $\epsilon_\circ$ as in Definition~9.4, and recalling that we took $\epsilon_\infty\le\epsilon_\circ$. For a lower bound, we note that for the case $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, the above transformation removes \textup{\texttt{\footnotesize red}} spins only in the case $(\sigma^c)_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}$. It follows that, for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$, we have
	\begin{align*}
	&\mathbf{P}^d\bigg( (\varsigma_e)^1=\textup{\texttt{\footnotesize r}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge \mathbf{P}^c\bigg( (\varsigma_e)^1=\textup{\texttt{\footnotesize r}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-\mathbf{P}^c\bigg(
		\sigma_e=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}\,\bigg|\, \bm{L}_e=\bm{L}\bigg) \\
	&\stackrel{(9.129)}{\ge} \mathbf{P}^c\bigg( (\varsigma_e)^1=\textup{\texttt{\footnotesize r}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		- O\bigg( \frac{k^4}{4^k} \bigg)
	\stackrel{(9.173)}{\ge}
	 {}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}}) 
	 -O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	 - O\bigg( \frac{k^4}{4^k} \bigg) \\
	&\ge\zeta_e(\varsigma=\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Similar bounds hold if we exchange the roles of the two copies, so we also have
	\[\zeta_e(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}}\,|\,\bm{L})
		- O\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
	\le\mathbf{P}^d\bigg(\varsigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le \zeta_e(\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}}\,|\,\bm{L})\]
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. 
For $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ 
and $\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ we also have
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\textup{\texttt{\footnotesize w}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\le
	\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg((\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\stackrel{(9.175)}{=}
	\Big(1-(\theta_e)^1(\tau)\Big)
	(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})\\
	&\qquad=\max\bigg\{0,
		(\bm{\zeta}_e)^i(\tau\,|\,\bm{L})-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}
	=\max\bigg\{0,
		\bm{\zeta}_e(\tau\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}\\
	&\qquad\le \bm{\zeta}_e(\tau\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
		+O\bigg( \frac1{2^{k(1+\epsilon_\circ)}}\bigg)
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\le \bm{\zeta}_e(\tau\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\end{align*}	
where the transition to the last line is by another application of Lemma~9.7, again using that $\bm{L}\in\mathbb{D}\cap\mathbb{L}$. For a lower bound on the same quantity, we have
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$ and $\tau\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}$ that
	\begin{align*}
	&\mathbf{P}^d\bigg(\varsigma_e=\tau\textup{\texttt{\footnotesize w}}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	\ge\Big(1-(\theta_e)^1(\tau)\Big)
	\bigg\{
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
	-\mathbf{P}^c\bigg( \varsigma_e\in\{\tau\}\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)\bigg\}\\
	&\qquad\stackrel{(9.176)}{\ge}
		\Big(1-(\theta_e)^1(\tau)\Big)
	\mathbf{P}^c\bigg( (\varsigma_e)^1=\tau
		\,\bigg|\, \bm{L}_e=\bm{L}\bigg)
		-O\bigg(\frac{k^4}{4^k}\bigg)\\
	&\qquad\stackrel{(9.175)}{=}
	\max\bigg\{0,
		\bm{\zeta}_e(\tau\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
		+\bm{\zeta}_e(\tau\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}\,|\,\bm{L})
		-\frac1{2^{k(1+\epsilon_\infty/2)}}
	\bigg\}-O\bigg(\frac{k^4}{4^k}\bigg)
	\ge \bm{\zeta}_e(\tau\textup{\texttt{\footnotesize w}}\,|\,\bm{L})
	-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,.
	\end{align*}
Finally, the above procedure never yields $(\varsigma^d)_e\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$, so
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}^2$ we have
	\[
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge 0 = \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)\,,
	\]
where the last inequality again uses Lemma~9.7. In summary, in the above we have shown
	\begin{equation}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge \mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
		-\Theta\bigg(\frac1{2^{k(1+\epsilon_\infty/2)}}\bigg)
		\end{equation}
for all $\bm{L}\in\mathbb{D}\cap\mathbb{L}$
and all $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2\setminus\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$. On the other hand, for $\bm{L}\notin\mathbb{D}\cap\mathbb{L}$ we have
	\begin{equation}
	\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\ge0=
	\mathbf{P}^d\bigg(\varsigma_e=\varsigma
		\,\bigg|\,\bm{L}_e=\bm{L}\bigg)
	\ge \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	- O\bigg( \frac{k^2}{2^k}\bigg)
	\end{equation}
for all $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2\setminus\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$, where the last inequality is by Lemma~9.5.

We now turn to estimating the entropy of $\mathbf{P}^d$. To this end, let $\bm{E}_c$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^c)_e$, or equivalently $(X^d)_e\ne(X^c)_e$. Note that if 
$(\varsigma^{c,i})_e\ne\textup{\texttt{\footnotesize w}}$
and $(\varsigma^{d,i})_e\ne\textup{\texttt{\footnotesize w}}$,
then $(\varsigma^{c,i})_e=(\varsigma^{d,i})_e$
so $e\notin\bm{E}_c$.
If $e\in\bm{E}_c$ then
the above procedure must transform
$(\varsigma^{c,i})_e\ne\textup{\texttt{\footnotesize w}}$ into $(\varsigma^{d,i})_e=\textup{\texttt{\footnotesize w}}$ for at least one index $i=1,2$, so we can bound
	\begin{align*}
	&\mathbb{P}(e\in \bm{E}_c\,\bigg|\,\bm{L}_e=\bm{L})
	\le \sum_{i=1,2}
	\bigg\{ \mathbf{P}^c\Big( (\varsigma_e)^i\ne\textup{\texttt{\footnotesize w}}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\textup{\texttt{\footnotesize w}}
		\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}\\
	&\qquad\le
	\sum_{i=1,2}\bigg\{
	(\bm{\zeta}_e)^i\Big(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\}
		\,\Big|\,\bm{L}\Big)
	-\mathbf{P}^d\Big( (\varsigma_e)^i\ne\textup{\texttt{\footnotesize w}}
		\,\Big|\,\bm{L}\Big)\bigg\}
	\le O(1)\sum_{\varsigma\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}}
		\bigg|
		\bm{\zeta}_e(\varsigma\,|\,\bm{L})
		- \mathbf{P}^d\Big(\varsigma_e=\varsigma
			\,\Big|\,\bm{L}_e=\bm{L}\Big)
		\bigg|\,,
	\end{align*}
where the transition to the second line follows by combining (9.172) and (9.175). Applying
(9.177) and (9.178) gives
	\begin{align}
	\mathbb{E}(|\bm{E}_c|)
	&\le
	O(1)\sum_{e\in\delta v}
		\sum_{\varsigma\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}}
		\bigg\{
		\frac{\mathbf{P}^c(\bm{L}_e\in\mathbb{D}\cap\mathbb{L})}
			{2^{k(1+\epsilon_\infty/2)}}
		+\frac{\mathbf{P}^c(\bm{L}_e\notin\mathbb{D}\cap\mathbb{L})}
			{2^k/k^2}\bigg\}\\
	&\le O\bigg(\frac{k}{2^{k\epsilon_\infty/2}}
	+ \frac{\cancel{\mathbb{D}}(v)+\cancel{\mathbb{L}}(v)}
		{2^k/k^2}\bigg)
	\stackrel{(9.118)}{\le}
	O\bigg(\frac{k^2}{2^{k\epsilon_\infty/2}}\bigg)\,,
	\end{align}
similarly to the estimate
(9.169) from the previous transformation. It follows by the same argument as for (9.171) that
	\begin{equation}
	\mathcal{H}(\mathbf{P}^c) 
	=\mathcal{H}(\mathcal{X}^c) 
	\le \mathcal{H}(\mathcal{X}^d) + o_k(1)
	= \mathcal{H}(\mathbf{P}^d) + o_k(1).
	\end{equation}
This concludes our analysis of the measure $\mathbf{P}^d$.\smallskip

\noindent\textbf{\textup{\hypertarget{l:DIVERSE.Pe}{Part 6}. Construction of $\mathbf{P}^f$.}}
In the final step of the proof we construct $\mathcal{X}^f$ from $\mathcal{X}^d$, where we have chosen the notation $\mathcal{X}^f$ rather than $\mathcal{X}^e$ to avoid confusion with edge labels $e\in\delta v$. For $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ we define subsets $A^\sigma$ of $
\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$ as follows:
	{\setlength{\jot}{0pt}\begin{align*}
	A^{\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}}}&=\{(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize r}}),
		(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize r}}),(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize r}}),
		(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize w}}),(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize c}}),
		(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize c}}),(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize w}}),
		(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize c}})\}\,,\\
	A^{\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}}}&=\{
		(\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize r}}\textup{\texttt{\footnotesize y}}),
		(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize y}}),
		(\textup{\texttt{\footnotesize b}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}}\textup{\texttt{\footnotesize y}})
		\}\,,\\
	A^{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}}}&=\{
		(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize r}}),
		(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize w}}),
		(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize b}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize c}})
		\}\,,\\
A^{\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}}}&=\{(\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize y}}\textup{\texttt{\footnotesize y}})\}\,.
\end{align*}}
Note that for each $\sigma\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ and every $(\sigma',\varsigma')\in A^\sigma$ we have the compatibility relation $\sigma'\sim\varsigma'$; and the spins $\sigma,\sigma'$ correspond to the same frozen spin $x\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}^2$. Moreover, for each $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2\setminus\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$ 
there is exactly one spin $\sigma\equiv\sigma^f(\varsigma)\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ such that 
$(\sigma',\varsigma)\in A^\sigma$ for some $\sigma'$.
We then define distributions $\xi^\sigma(\cdot\,|\,\bm{L})$ over pairs $X\equiv (\sigma,\varsigma)\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize g}},\textup{\texttt{\footnotesize b}}\}^2\times\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2$ by setting
	\begin{equation}
	\xi^\sigma((\sigma,\varsigma)\,|\,\bm{L})
	=\frac{\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d(\varsigma_e = \varsigma \,|\, \bm{L}_e=\bm{L})}{\mathbf{P}^d(\sigma_e = \sigma, \varsigma_e= \textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}
		\,|\, \bm{L}_e=\bm{L} )}
	\end{equation}
for all $(\sigma,\varsigma)\in A^\sigma$, and assigning the remaining probability to the event $\{(\sigma,\varsigma)=(\sigma,\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})\}$. To see that these distributions are well-defined, note that on the right-hand side of (9.181), the denominator is $\Theta(1)$, while (9.177) and (9.178) together imply that the numerator is nonnegative and small. It follows that
	\[
	\xi^\sigma((\sigma,\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})\,|\,\bm{L})
	= 1-\sum_{X'\in A^\sigma}
		\xi^\sigma(X'\,|\,\bm{L})
	\in[0,1]\,,
	\]
so $\xi^\sigma(\cdot\,|\,\bm{L})$ is a valid probability measure over $A^\sigma \cup \{(\sigma,\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})\}$. In the final transformation, given $\mathcal{X}^d$, for each $e\in\delta v$ we set $(\bm{L}^f)_e=(\bm{L}^d)_e$. If $(\sigma^d)_e\in\{\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize b}}\}^2$ and $(\varsigma^d)_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$, then we let $(X^f)_e$ be a sample from $\xi^\sigma(\cdot\,|\,(\bm{L}^d)_e)$. In all other cases we let $(X^f)_e=(X^d)_e$. It is straightforward to verify that this results in a valid configuration $\mathcal{X}^f$ with the same frozen spin,
$x^f=x^d\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$. For each $\varsigma\in\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize y}},\textup{\texttt{\footnotesize c}},\textup{\texttt{\footnotesize w}}\}^2\setminus\{\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}\}$,
	\begin{align}
	&\mathbf{P}^f\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	= \mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \sum_{\sigma: \sigma=\sigma^f(\varsigma)}
	\mathbf{P}^d\Big(
	\sigma_e=\sigma,
	\varsigma_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}
	\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\xi^\sigma( (\sigma,\varsigma) \,|\,\bm{L})\\
	&\qquad\stackrel{(9.181)}{=}
	\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)
	+ \bigg\{ \bm{\zeta}_e(\varsigma\,|\,\bm{L})
	-\mathbf{P}^d\Big(\varsigma_e=\varsigma\,\Big|\,\bm{L}_e=\bm{L}\Big)\bigg\}
	=\bm{\zeta}_e(\varsigma\,|\,\bm{L})
	\,,
	\end{align}
so $\mathbf{P}^f$ satisfies condition
(9.122). On the other hand, since $x^a=x^f\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}},\textup{\texttt{\footnotesize f}}\}^2$, we have
	\[
	\mathbf{P}^f\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	=\mathbf{P}^a\Big( x^i=z\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{(9.126)}{=} \begin{cases}
	{}_\star\hspace{-1pt}\pi_e(\{\textup{\texttt{\footnotesize r}},\textup{\texttt{\footnotesize b}}\})
	&\textup{if $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$
		and $e\in\delta v(z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize y}})
	&\textup{if $z\in\{\textup{\texttt{\footnotesize -}},\textup{\texttt{\footnotesize +}}\}$
		and $e\in\delta v(\textup{\texttt{\footnotesize -}} z)$,}\\
	{}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize g}}) 
	&\textup{if $z=\textup{\texttt{\footnotesize f}}$.}
	\end{cases}
	\]
Moreover, since $(\varsigma_e)^i=\textup{\texttt{\footnotesize r}}$ if and only if $(\sigma_e)^i=\textup{\texttt{\footnotesize r}}$, it follows that
	\[
	\mathbf{P}^f\Big( (\sigma_e)^i=\textup{\texttt{\footnotesize r}}\,\Big|\,\bm{L}_e=\bm{L}\Big)
	\stackrel{(9.182)}{=}
	(\bm{\zeta}_e)^i(\textup{\texttt{\footnotesize r}}\,|\,\bm{L})
	= {}_\star\hspace{-1pt}\pi_e(\textup{\texttt{\footnotesize r}})\,.
	\]
It follows from the last two displays combined that $\mathbf{P}^f$ satisfies condition~(9.121).
Lastly, since $(\bm{L}^a)_e=(\bm{L}^f)_e$ for all $e$, 
and $\mathbf{P}^a$ satisfied condition (9.120) by construction,
we can conclude that $\mathbf{P}^f$ also satisfies 
condition~(9.120).

We now estimate the entropy of $\mathbf{P}^f$.
Let $\bm{E}_d$ denote the subset of edges $e\in\delta v$ for which $(\mathcal{X}^d)_e\ne(\mathcal{X}^f)_d$. For any edge in $e\in \bm{E}_d$ we must have $(\varsigma^d)_e=\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$ and $(\varsigma^f)_e\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}$. As a result we can bound
	\begin{align*}
	\mathbb{E}(|\bm{E}_d|)
	&\le \sum_{e\in \delta v}
	\bigg(
	\mathbf{P}^f(\varsigma_e\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})
	- \mathbf{P}^d(\varsigma_e\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}})
	\bigg)
	= \sum_{e\in \delta v}
	\sum_{\varsigma\ne\textup{\texttt{\footnotesize w}}\textup{\texttt{\footnotesize w}}}\bigg(
	 \bm{\zeta}_e(\varsigma)
	 - \mathbf{P}^d(\varsigma_e=\varsigma)
	 \bigg) \le 
	 O\bigg( \frac{k^2}{2^{k \epsilon_\infty/2}}\bigg)\,,
\end{align*}
using the same reasoning as for (9.179). It then follows by the argument of~(9.171) that
	\begin{equation}
	\mathcal{H}(\mathbf{P}^d)\le \mathcal{H}(\mathbf{P}^f) + o_k(1)\,.\end{equation}
Combining equations~(9.156), (9.171), (9.180),(9.183),
and (9.133) gives
	\[
	\mathcal{H}(\mathbf{P}^f)
	\ge \mathcal{H}(\mathbf{P}^a) - o_k(1)
	\stackrel{(9.133)}{\ge}
	\mathcal{H}(\mathbf{P}) + \frac1{10^6} - o_k(1)\,.
	\]
This contradicts the assumption that $\mathbf{P}$ is the maximal-entropy measure satisfying constraints
(9.120)--(9.122), thereby concluding the proof of the proposition.
\end{proof}
